INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1,'ivorycoast','Zino Cigares & Lounge — Flagship Zone 4','Abidjan, Marcory — Rue Paul Langevin','Flagship Lounge & Cave','+225 27 22 51 05 09','€€€€','Inauguré le 6 janv. 2025 par les frères Kamal et Charan Daswani. 160 m², cave humidifiée où l\'on entre 120 m² (450+ refs Habanos), fumoir lounge 120 m² (150 personnes). Ouvert 10h-2h. Groupe présent depuis 1980, inauguré par Zino Davidoff en personne.','cigars-connect.com',1,'2026-03-18 09:43:40','2026-09-02 15:29:30','10h–2h','https://www.google.com/maps/search/?api=1&query=Zino%20Cigares%20%26%20Lounge%20%28Flagship%20Zone%204%29%2C%20Abidjan%2C%20C%C3%B4te%20d%27Ivoire',NULL,NULL,NULL,0,'Opened le 6 janv. 2025 par les frères Kamal et Charan Daswani. 160 sqm, walk-in humidor 120 sqm (450+ refs Habanos), smoking lounge lounge 120 sqm (150 people). Open 10h-2h. Group present depuis 1980, opened par Zino Davidoff en person.','Inaugurado le 6 janv. 2025 par les frères Kamal y Charan Daswani. 160 m², walk-in humidor 120 m² (450+ refs Habanos), salón de fumadores lounge 120 m² (150 personas). Abierto 10h-2h. Groupe présent desde 1980, inaugurado par Zino Davidoff en personne.','Eröffnund le 6 janv. 2025 par les frères Kamal und Charan Daswani. 160 m², walk-in Humidor 120 m² (450+ refs Habanos), Raucherlounge lounge 120 m² (150 Personen). Geöffnund 10h-2h. Groupe présent seit 1980, eröffnund par Zino Davidoff en personne.','2025年1月6日开业 由卡迈勒和查兰·达斯瓦尼兄弟. 160 ㎡, 步入式恒温恒湿雪茄柜 120 ㎡ (450多款哈瓦那斯雪茄), 雪茄休息室 120 ㎡ (150 人). 营业时间10:00-02:00. 集团自1980年起运营,  par Zino Davidoff en 人.','افتُتح في 6 يناير 2025 على يد الأخوين كامال وتشاران داسواني. 160 م², غرفة الهيوميدور للدخول 120 م² (أكثر من 450 سيجارة هابانوس), صالة تدخين السيجار 120 م² (150 شخصًا). مفتوح من 10 صباحًا حتى 2 فجرًا. المجموعة موجودة منذ 1980,  par Zino Davidoff en شخص.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2,'ivorycoast','Zino Cigares — Cap Sud','Abidjan, Rue des Jardins — Galerie Cap Sud','Civette & Cave à Cigares','+225 27 22 51 05 10','€€€€','Inaugurée en déc. 2020. Toutes marques Habanos, Arturo Fuente, Davidoff, Rocky Patel, La Flor Dominicana, Plasencia, Gurkha. Accessoires Elie Bleu, Chacom, Zippo.','baab.ci',1,'2026-03-18 09:43:40','2026-03-22 15:18:20',NULL,'https://www.google.com/maps/search/?api=1&query=Zino%20Cigares%20%28Cap%20Sud%29%2C%20Abidjan%2C%20C%C3%B4te%20d%27Ivoire',NULL,NULL,NULL,0,'Openede in Dec. 2020. All brands Habanos, Arturo Fuente, Davidoff, Rocky Patel, La Flor Dominicana, Plasencia, Gurkha. Accessoires Elie Bleu, Chacom, Zippo.','Inauguradoe en déc. 2020. Todas las marcas Habanos, Arturo Fuente, Davidoff, Rocky Patel, La Flor Dominicana, Plasencia, Gurkha. Accessoires Elie Bleu, Chacom, Zippo.','Eröffnunde en déc. 2020. Alle Marken Habanos, Arturo Fuente, Davidoff, Rocky Patel, La Flor Dominicana, Plasencia, Gurkha. Accessoires Elie Bleu, Chacom, Zippo.','2020年12月开业. 全系列哈瓦那斯品牌, Arturo Fuente, Davidoff, Rocky Patel, La Flor Dominicana, Plasencia, Gurkha. 配件 Elie Bleu, Chacom, Zippo.','افتُتحت في ديسمبر 2020. جميع ماركات هابانوس, Arturo Fuente, Davidoff, Rocky Patel, La Flor Dominicana, Plasencia, Gurkha. إكسسوارات Elie Bleu, Chacom, Zippo.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (3,'ivorycoast','Zino Bar Lounge','Abidjan, Marcory Résidentiel — Bvd de la Lorraine, Rue des Citronniers','Bar & Lounge Cigares','+225 07 07 56 43 43','€€€','Lounge cigares d\'Abidjan, à Marcory Résidentiel. Sélection de Habanos et de cigares premium.','TripAdvisor, avis vérifiés',1,'2026-03-18 09:43:40','2026-08-05 13:44:22',NULL,'https://www.google.com/maps/search/?api=1&query=Zino%20Bar%20Lounge%2C%20Abidjan%2C%20C%C3%B4te%20d%27Ivoire',NULL,NULL,NULL,0,'Cigar lounge in Abidjan, in Marcory Résidentiel. A selection of Habanos and premium cigars.','Cigar lounge en Abiyán, en Marcory Résidentiel. Selección de Habanos y puros premium.','Zigarrenlounge in Abidjan, im Viertel Marcory Résidentiel. Auswahl an Habanos und Premium-Zigarren.','阿比让 Marcory Résidentiel 区的雪茄厅。精选哈瓦那与高端雪茄。','صالة سيجار في أبيدجان، بحي ماركوري السكني. تشكيلة من هابانوس والسيجار الفاخر.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (4,'ivorycoast','Cigarro CI — Diamond Center Beverly Hills','Abidjan, Beverly Hills — Diamond Center','Lounge Cigares & Civette','+225 07 69 03 00 30','€€€','Lounge Cigarro CI dans le Diamond Center Beverly Hills. Instagram: @cigarro.ci','fourni par l\'établissement',1,'2026-03-18 09:43:40','2026-09-02 15:29:30',NULL,'https://www.google.com/maps/search/?api=1&query=Cigarro%20CI%20%28Diamond%20Center%20Beverly%20Hills%29%2C%20Abidjan%2C%20C%C3%B4te%20d%27Ivoire',NULL,'cigarro.ci',5.0,1,'Cigarro CI lounge in the Diamond Center Beverly Hills. Instagram: @cigarro.ci','Lounge Cigarro CI en el Diamond Center Beverly Hills. Instagram: @cigarro.ci','Cigarro-CI-Lounge im Diamond Center Beverly Hills. Instagram: @cigarro.ci','位于 Diamond Center Beverly Hills 的 Cigarro CI 雪茄厅。Instagram：@cigarro.ci','صالة «سيغارو CI» في مركز دياموند بيفرلي هيلز. إنستغرام: @cigarro.ci',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (5,'ivorycoast','Cigarro CI — Rue du Dr Blanchard Zone 4','Abidjan, Zone 4 — Rue du Docteur Blanchard','Lounge Cigares & Civette','+225 07 69 03 00 30','€€€','Deuxième adresse Cigarro CI en Zone 4. Instagram: @cigarro.ci','fourni par l\'établissement',1,'2026-03-18 09:43:40','2026-09-02 15:29:30',NULL,'https://www.google.com/maps/search/?api=1&query=Cigarro%20CI%2C%20Abidjan%2C%20C%C3%B4te%20d%27Ivoire',NULL,'cigarro.ci',5.0,1,'Cigarro CI\'s second address, in Zone 4. Instagram: @cigarro.ci','La segunda dirección de Cigarro CI, en la Zona 4. Instagram: @cigarro.ci','Die zweite Adresse von Cigarro CI, in Zone 4. Instagram: @cigarro.ci','Cigarro CI 的第二家门店，位于 4 区。Instagram：@cigarro.ci','العنوان الثاني لـ«سيغارو CI» في المنطقة 4. إنستغرام: @cigarro.ci',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (6,'ivorycoast','Boca Chica Club Bar & Cigare Lounge','Abidjan, Plateau — Hôtel Noom (3e étage)','Hôtel Cigar Bar & Club',NULL,'€€€€','Lounge au 3e étage de l\'Hôtel Noom Plateau. Cigares de luxe, whiskys, champagnes, fauteuils Club cuir. Soul, Blues, Smooth Jazz.','baab.ci, bocachicaabidjan.com',1,'2026-03-18 09:43:40','2026-08-01 18:15:50',NULL,'https://www.google.com/maps/search/?api=1&query=Boca%20Chica%20Club%20Bar%20%26%20Cigare%20Lounge%2C%20Abidjan%2C%20C%C3%B4te%20d%27Ivoire',NULL,NULL,NULL,0,'Third-floor lounge at the Hôtel Noom Plateau. Luxury cigars, whiskies, champagnes and leather club armchairs. Soul, blues and smooth jazz.','Lounge en la tercera planta del Hôtel Noom Plateau. Puros de lujo, whiskies, champanes y sillones club de cuero. Soul, blues y smooth jazz.','Lounge im dritten Stock des Hôtel Noom Plateau. Luxuszigarren, Whiskys, Champagner und lederne Clubsessel. Soul, Blues und Smooth Jazz.','Hôtel Noom Plateau 三楼的休闲厅。奢华雪茄、威士忌、香槟与皮质俱乐部扶手椅。播放灵魂乐、蓝调与柔和爵士。','صالة في الطابق الثالث من فندق نووم بلاتو. سيجار فاخر وويسكي وشمبانيا وكراسي نادٍ جلدية. موسيقى سول وبلوز وجاز هادئ.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (7,'ivorycoast','Elite Cigar Abidjan','Abidjan','Restaurant, Lounge & Cigar Shop','+225 07 07 17 28 68','€€€','Repaire d\'amateurs, cadre discret et chaleureux. Restaurant, salon, boutique de cigares et terrasse.','baab.ci, Facebook',1,'2026-03-18 09:43:40','2026-08-26 11:06:16',NULL,'https://www.google.com/maps/search/?api=1&query=Elite%20Cigar%20Abidjan%2C%20Abidjan%2C%20C%C3%B4te%20d%27Ivoire',NULL,NULL,NULL,0,'A haven for aficionados, discreet and warm. Restaurant, lounge, cigar shop and terrace.','Refugio de aficionados, de ambiente discreto y acogedor. Restaurante, salón, tienda de puros y terraza.','Ein Treffpunkt für Liebhaber, diskret und behaglich. Restaurant, Lounge, Zigarrenladen und Terrasse.','雪茄爱好者聚集地，环境低调温馨。设餐厅、休息室、雪茄专卖店与露台。','ملتقى عشاق السيجار، بأجواء هادئة ودافئة. مطعم، وصالة، ومتجر سيجار، وشرفة.',NULL,NULL,NULL);
