INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (24,'tanzania','Zanzibar Cigar Club — Stone Town','Stone Town, Zanzibar','Lounge & Cave',NULL,'€€€','Lounge cigares dans la vieille ville de Zanzibar classée UNESCO. Ambiance spice island.','tripadvisor.com avis vérifiés',1,'2026-03-18 09:43:40','2026-09-03 12:11:42',NULL,'https://www.google.com/maps/search/?api=1&query=Zanzibar%20Cigar%20Club%20%28Stone%20Town%29%2C%20Stone%20Town%2C%20Tanzania',NULL,NULL,NULL,0,'Cigar lounge in the UNESCO-listed old town of Zanzibar. Spice island atmosphere.','Cigar lounge en el casco antiguo de Zanzíbar, Patrimonio de la Humanidad. Ambiente de isla de las especias.','Zigarrenlounge in der UNESCO-gelisteten Altstadt von Sansibar. Gewürzinsel-Atmosphäre.','雪茄休息室 位于古城 的Zanzibar classée UNESCO. Ambiance spice island.','صالات السيجار في المدينة القديمة من Zanzibar classée UNESCO. Ambiance spice island.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (25,'france','À La Civette (fondée 1716)','Paris 1er — 157 Rue Saint-Honoré, près Palais-Royal','Civette Historique (plus ancienne du monde)','+33 1 42 96 04 99','€€€€','Fondée en 1716 et en activité sans interruption depuis. Clients historiques : Danton, Napoléon, Robespierre, Mirabeau, Degas, George Sand. Plus de 350 références de Cuba, du Honduras, du Nicaragua et de République dominicaine. Pipes et spiritueux.','alacivette.com officiel',1,'2026-03-18 09:43:40','2026-08-25 22:42:29',NULL,'https://www.google.com/maps/search/?api=1&query=%C3%80%20La%20Civette%20%28fond%C3%A9e%201716%29%2C%20Paris%201er%2C%20France',NULL,NULL,NULL,0,'Founded in 1716 and trading without interruption ever since. Historic patrons: Danton, Napoleon, Robespierre, Mirabeau, Degas, George Sand. Over 350 references from Cuba, Honduras, Nicaragua and the Dominican Republic. Pipes and fine spirits.','Fundada en 1716 y en activo sin interrupción desde entonces. Clientes históricos: Danton, Napoleón, Robespierre, Mirabeau, Degas, George Sand. Más de 350 referencias de Cuba, Honduras, Nicaragua y República Dominicana. Pipas y licores selectos.','1716 gegründet und seither ohne Unterbrechung in Betrieb. Historische Kunden: Danton, Napoleon, Robespierre, Mirabeau, Degas, George Sand. Über 350 Referenzen aus Kuba, Honduras, Nicaragua und der Dominikanischen Republik. Pfeifen und edle Spirituosen.','1716 年创立，此后经营从未中断。历史上的顾客包括丹东、拿破仑、罗伯斯庇尔、米拉波、德加与乔治·桑。备有 350 余款来自古巴、洪都拉斯、尼加拉瓜和多米尼加共和国的产品，另售烟斗与精致烈酒。','تأسّست عام 1716 وظلّت تعمل دون انقطاع منذ ذلك الحين. من زبائنها التاريخيين: دانتون ونابليون وروبسبير وميرابو وديغا وجورج ساند. أكثر من 350 صنفًا من كوبا وهندوراس ونيكاراغوا وجمهورية الدومينيكان، إضافة إلى الغلايين والمشروبات الروحية الفاخرة.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (26,'france','Bar Aristide (Hôtel Lutetia)','Paris 6e — 45 Boulevard Raspail','Palace Cigar Bar','+33 1 49 54 46 46','€€€€','Premier palace Art Nouveau de Paris. Bar Aristide avec deux fumoirs distincts. Sélection pointue de cigares cubains, mixologie signature raffinée. Matisse, Saint-Exupéry y fumèrent.','cigaroa.com, hotel-lutetia.com',1,'2026-03-18 09:43:40','2026-08-05 12:51:13',NULL,'https://www.google.com/maps/search/?api=1&query=Bar%20Aristide%20%28H%C3%B4tel%20Lutetia%29%2C%20Paris%206e%2C%20France',NULL,NULL,NULL,0,'Paris\'s first Art Nouveau palace hotel. The Aristide bar with two separate smoking rooms. A sharp selection of Cuban cigars and refined signature mixology. Matisse and Saint-Exupéry smoked here.','El primer palacio modernista de París. El bar Aristide, con dos fumadores independientes. Selección exigente de puros cubanos y coctelería de autor refinada. Matisse y Saint-Exupéry fumaron aquí.','Das erste Jugendstil-Grandhotel von Paris. Die Aristide-Bar mit zwei getrennten Rauchsalons. Anspruchsvolle kubanische Zigarrenauswahl und raffinierte Signature-Mixologie. Matisse und Saint-Exupéry rauchten hier.','巴黎首家新艺术风格宫殿酒店。Aristide 酒吧设两间独立吸烟室。古巴雪茄选品讲究，招牌调酒精致。马蒂斯与圣埃克苏佩里曾在此吸烟。','أول فندق قصر بطراز الآرت نوفو في باريس. بار «أريستيد» بصالتَي تدخين منفصلتين. تشكيلة دقيقة من السيجار الكوبي وفنّ كوكتيل مميّز. دخّن هنا ماتيس وسانت إكزوبيري.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (27,'france','Le Gaspard (La Réserve Paris)','Paris 8e — 42 avenue Gabriel','Palace Cigar Room','+33 1 58 36 60 60','€€€€','Cigar room dans l\'hôtel La Réserve Paris, avenue Gabriel.','enthusiastreport.com, la-reserve.com',1,'2026-03-18 09:43:40','2026-08-05 11:35:28',NULL,'https://www.google.com/maps/search/?api=1&query=Le%20Gaspard%20%28La%20R%C3%A9serve%20Paris%29%2C%20Paris%208e%2C%20France',NULL,NULL,NULL,0,'Cigar room in the hotel La Réserve Paris, avenue Gabriel.','Cigar room en el hotel La Réserve Paris, avenue Gabriel.','Cigar Room im Hotel La Réserve Paris, Avenue Gabriel.','位于巴黎 La Réserve 酒店（加布里埃尔大道）的雪茄室。','غرفة سيجار في فندق لا ريزيرف باريس، بجادة غابرييل.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (28,'france','L\'Héritage 105 — Cigar Bar','Paris 8e — 105 Rue du Faubourg Saint-Honoré','Restaurant, Lounge & Cigar Bar','+33 1 42 89 47 15','€€€€','Concept trois-en-un: restaurant bistronomique, lounge bar, cigar bar. Sélection de havanes d\'exception, spiritueux choisis. Au coeur du Paris luxueux.','lheritage105.com officiel',1,'2026-03-18 09:43:40','2026-08-01 18:08:34',NULL,NULL,NULL,NULL,NULL,0,'A three-in-one concept: bistronomy restaurant, lounge bar and cigar bar. Exceptional Havanas and a curated spirits list, in the heart of luxury Paris.','Concepto tres en uno: restaurante bistronómico, lounge bar y cigar bar. Selección de habanos excepcionales y destilados escogidos, en pleno París del lujo.','Drei-in-eins-Konzept: Bistronomie-Restaurant, Lounge-Bar und Zigarrenbar. Außergewöhnliche Havannas und ausgewählte Spirituosen, im Herzen des luxuriösen Paris.','三合一概念：小酒馆式美食餐厅、休闲酒吧与雪茄吧。臻选哈瓦那雪茄与精选烈酒，坐落于巴黎奢华腹地。','مفهوم ثلاثي: مطعم بيسترونومي وصالة بار وبار سيجار. تشكيلة استثنائية من سيجار هافانا ومشروبات روحية منتقاة، في قلب باريس الفاخرة.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (29,'france','Peninsula Lounge Kléber','Paris 16e — 19 Avenue Kléber (Hôtel Peninsula)','Palace Cigar Lounge','+33 1 58 12 28 88','€€€€','Lounge Kléber dans l\'hôtel Peninsula Paris, avenue Kléber.','cigaroa.com',1,'2026-03-18 09:43:40','2026-08-05 12:02:56',NULL,'https://www.google.com/maps/search/?api=1&query=Peninsula%20Lounge%20Kl%C3%A9ber%2C%20Paris%2016e%2C%20France',NULL,NULL,NULL,0,'The Kléber lounge in the Peninsula Paris hotel, avenue Kléber.','El lounge Kléber del hotel Peninsula Paris, avenue Kléber.','Die Kléber-Lounge im Hotel Peninsula Paris, Avenue Kléber.','巴黎半岛酒店（克莱贝尔大道）的 Kléber 休息厅。','صالة كليبر في فندق بينينسولا باريس، بجادة كليبر.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (30,'spain','La Casa del Habano — Madrid (Club Pasión Habanos)','Madrid — Paseo de Recoletos 1','La Casa del Habano Officielle',NULL,'€€€€','Club Pasión Habanos à Madrid, la référence espagnole du cigare cubain.','PDF officiel Habanos S.A.',1,'2026-03-18 09:43:40','2026-08-01 18:06:14',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%20%28Madrid%20%28Club%20Pasi%C3%B3n%20Habanos%29%29%2C%20Madrid%2C%20Spain',NULL,NULL,NULL,0,'Club Pasión Habanos in Madrid, Spain\'s benchmark for the Cuban cigar.','Club Pasión Habanos en Madrid, la referencia española del puro cubano.','Club Pasión Habanos in Madrid, die spanische Referenz für die kubanische Zigarre.','马德里的 Club Pasión Habanos，西班牙古巴雪茄的标杆。','نادي «باسيون هابانوس» في مدريد، المرجع الإسباني للسيجار الكوبي.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (31,'spain','Gimeno — La Rambla','Barcelona — Ramblas 100, Barrio Gótico','Civette Historique (fondée 1920)','+34 93 318 49 47','€€€€','Fondée en 1920, référence absolue du cigare à Barcelone. Rez-de-chaussée + sous-sol cave humidifiée où l\'on entre. Toute la gamme Altadis/Habanos + accessoires. 10h-19h lun-sam.','barcelona.com, tripadvisor vérifiés',1,'2026-03-18 09:43:40','2026-08-25 02:40:14',NULL,'https://www.google.com/maps/search/?api=1&query=Gimeno%20%28La%20Rambla%29%2C%20Barcelona%2C%20Spain',NULL,NULL,NULL,0,'Founded in 1920, the absolute cigar reference in Barcelona. Ground floor plus a basement walk-in humidor. The full Altadis/Habanos range and accessories. Open 10am–7pm, Monday to Saturday.','Fundado en 1920, la referencia absoluta del puro en Barcelona. Planta baja y humidor walk-in en el sótano. Toda la gama Altadis/Habanos y accesorios. De 10:00 a 19:00, de lunes a sábado.','1920 gegründet, die absolute Zigarrenreferenz in Barcelona. Erdgeschoss plus begehbarer Humidor im Untergeschoss. Das komplette Altadis/Habanos-Sortiment und Zubehör. Mo–Sa 10–19 Uhr.','创立于 1920 年，巴塞罗那雪茄的绝对标杆。一楼加地下层步入式雪茄柜。Altadis／Habanos 全系列与配件。周一至周六 10:00–19:00。','تأسّس عام 1920، وهو المرجع المطلق للسيجار في برشلونة. طابق أرضي وقبو بمرطّبة قابلة للدخول. تشكيلة ألتاديس/هابانوس الكاملة والملحقات. من 10:00 إلى 19:00، الاثنين إلى السبت.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (32,'spain','Bluesman Cigar Lounge — Hotel El Palace','Barcelona — Gran Via de les Corts Catalanes 668 (El Palace Hotel)','Palace Cigar Lounge','+34 93 510 11 30','€€€€','Lounge cigares dans l\'hôtel El Palace de Barcelone, Gran Via de les Corts Catalanes.','hotelpalacebarcelona.com officiel',1,'2026-03-18 09:43:40','2026-08-05 12:02:56',NULL,'https://www.google.com/maps/search/?api=1&query=Bluesman%20Cigar%20Lounge%20%28Hotel%20El%20Palace%29%2C%20Barcelona%2C%20Spain',NULL,NULL,NULL,0,'Cigar lounge in the El Palace hotel in Barcelona, Gran Via de les Corts Catalanes.','Cigar lounge en el hotel El Palace de Barcelona, Gran Via de les Corts Catalanes.','Zigarrenlounge im Hotel El Palace in Barcelona, Gran Via de les Corts Catalanes.','位于巴塞罗那 El Palace 酒店（Gran Via de les Corts Catalanes）的雪茄厅。','صالة سيجار في فندق إل بالاس ببرشلونة، بشارع غران فيا دي ليس كورتس كاتالانس.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (33,'spain','Cava Magallanes','Madrid — Rua de Magallanes 1','Cave & Lounge Premium','+34 91 446 69 96','€€€€','Davidoff Best Performance EMEA Award 2021. Cave de référence de Madrid, sélection premium, accords cigare-spiritueux.','cigarjournal.com Golden Band Awards 2021',1,'2026-03-18 09:43:40','2026-08-05 12:40:54',NULL,'https://www.google.com/maps/search/?api=1&query=Cava%20Magallanes%2C%20Madrid%2C%20Spain',NULL,NULL,NULL,0,'Davidoff Best Performance EMEA Award 2021. Madrid\'s benchmark shop, premium selection, cigar-and-spirits pairings.','Davidoff Best Performance EMEA Award 2021. El estanco de referencia de Madrid, selección premium y maridajes puro-destilado.','Davidoff Best Performance EMEA Award 2021. Madrids maßgeblicher Laden, Premium-Auswahl, Zigarren-Spirituosen-Pairings.','2021 年大卫杜夫 EMEA 最佳表现奖。马德里的标杆商行，高端精选，雪茄与烈酒搭配。','جائزة دافيدوف لأفضل أداء في أوروبا والشرق الأوسط وأفريقيا 2021. المتجر المرجعي في مدريد، بتشكيلة فاخرة ومزاوجات بين السيجار والمشروبات الروحية.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (34,'germany','Cigarworld Lounge','Düsseldorf — Burghofstrasse 28, 40223','Cave & Lounge Géant (fondé 2005)','+49 211 1593 985','€€€€','Le plus grand lounge cigares d\'Allemagne, fondé en 2005. Plus de 3 000 références, cave humidifiée où l\'on entre professionnel, salons de dégustation climatisés à Düsseldorf.','cigarworld.de, londoncigarsmoker.com',1,'2026-03-18 09:43:40','2026-08-25 02:40:14',NULL,'https://www.google.com/maps/search/?api=1&query=Cigarworld%20Lounge%2C%20D%C3%BCsseldorf%2C%20Germany',NULL,NULL,NULL,0,'Germany\'s largest cigar lounge, founded in 2005. Over 3,000 references, professional walk-in humidor, air-conditioned tasting rooms in Düsseldorf.','El mayor cigar lounge de Alemania, fundado en 2005. Más de 3000 referencias, humidor walk-in profesional y salas de degustación climatizadas en Düsseldorf.','Deutschlands größte Zigarrenlounge, gegründet 2005. Über 3000 Referenzen, professioneller begehbarer Humidor, klimatisierte Verkostungsräume in Düsseldorf.','德国最大的雪茄厅，创立于 2005 年。逾 3000 款雪茄、专业步入式雪茄柜，以及杜塞尔多夫的恒温品鉴室。','أكبر صالة سيجار في ألمانيا، تأسّست عام 2005. أكثر من 3000 صنف، ومرطّبة احترافية قابلة للدخول، وقاعات تذوّق مكيّفة في دوسلدورف.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (35,'germany','La Casa del Habano Hamburg — Chilehaus','Hamburg — Burchardstrasse 15, Chilehaus C, 20095','La Casa del Habano Officielle','+49 40 30704880','€€€€','Dans le Chilehaus, bâtiment expressionniste de 1924 classé Patrimoine Mondial UNESCO. LCDH de Hambourg depuis 2006. Géré par Janet et Christoph Walters, experts cigares 3e génération. Lounge intérieur, rums, cognacs, champagnes.','flavoredtimes.com, cigarjournal.com',1,'2026-03-18 09:43:40','2026-08-05 12:40:54',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%20Hamburg%20%28Chilehaus%29%2C%20Hamburg%2C%20Germany',NULL,NULL,NULL,0,'In the Chilehaus, a 1924 Expressionist building listed as UNESCO World Heritage. Hamburg\'s La Casa del Habano since 2006. Run by Janet and Christoph Walters, third-generation cigar experts. Indoor lounge, rums, cognacs, champagnes.','En el Chilehaus, edificio expresionista de 1924 declarado Patrimonio Mundial de la UNESCO. La Casa del Habano de Hamburgo desde 2006. Dirigida por Janet y Christoph Walters, expertos cigarreros de tercera generación. Lounge interior, rones, coñacs y champanes.','Im Chilehaus, einem expressionistischen Bau von 1924 und UNESCO-Welterbe. Hamburgs La Casa del Habano seit 2006. Geführt von Janet und Christoph Walters, Zigarrenexperten in dritter Generation. Innenlounge, Rum, Cognac, Champagner.','Dans Chilehaus, 1924年表现主义建筑 classé 联合国教科文组织世界遗产. LCDH 的Hambourg 自2006年起. 由 Janet、Christoph Walters, 雪茄专家 第三代. 休息室 intérieur, 朗姆酒, 干邑, 香槟.','Dans Chilehaus, مبنى تعبيري من عام 1924 classé تراث عالمي ليونسكو. LCDH من Hambourg منذ 2006. تديره Janet وChristoph Walters, خبراء السيجار الجيل الثالث. الصالة intérieur, روم, كونياك, شامبانيا.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (36,'germany','Duske & Duske','Hamburg — Große Bleichen 36','Cave & Habanos Specialist','+49 40 343385','€€€','Façade historique de marchand de Porto, spécialiste Habanos officiel. Cigares cubains complets. Accords avec Prime\'s Rum (mélange caribéen) et plus de 150 types de Porto et Madeira vintage (dont 1870). Futur membre réseau LCDH.','flavoredtimes.com',1,'2026-03-18 09:43:40','2026-08-05 12:40:54',NULL,'https://www.google.com/maps/search/?api=1&query=Duske%20%26%20Duske%2C%20Hamburg%2C%20Germany',NULL,NULL,NULL,0,'Historic merchant\'s front in Porto, an official Habanos specialist. Full range of Cuban cigars. Pairings with Prime\'s Rum (a Caribbean blend) and more than 150 vintage ports and madeiras, including an 1870. Future member of the La Casa del Habano network.','Fachada histórica de comerciante en Oporto, especialista oficial Habanos. Puros cubanos al completo. Maridajes con Prime\'s Rum (mezcla caribeña) y más de 150 oportos y maderas vintage, incluido un 1870. Futuro miembro de la red La Casa del Habano.','Historische Kaufmannsfassade in Porto, offizieller Habanos-Spezialist. Vollständiges Sortiment kubanischer Zigarren. Pairings mit Prime\'s Rum (karibischer Blend) und über 150 Vintage-Portweinen und Madeiras, darunter ein 1870er. Künftiges Mitglied des La-Casa-del-Habano-Netzes.','Façade 历史悠久 de marchand 的Porto, spécialiste Habanos officiel. Cigares cubains complets. Accords，配有Prime\'','Façade تاريخي de marchand من Porto, spécialiste Habanos officiel. Cigares cubains complets. Accords مع Prime\'',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (37,'germany','Carlos André Cigar Lounge (Se7en Oceans)','Hamburg — Europa Passage, 2e étage, Ballindamm 40','Restaurant Étoilé Cigar Lounge','+49 40 32507944','€€€€','Lounge cigares dans le complexe gastronomique Se7en Oceans (restaurant étoilé Michelin). Cave humidifiée où l\'on entre. Vue sur le Binnenalster. La Aurora, Davidoff, cubains. Bar cocktail complet.','cigarjournal.com, flavoredtimes.com',1,'2026-03-18 09:43:40','2026-08-25 02:40:14',NULL,'https://www.google.com/maps/search/?api=1&query=Carlos%20Andr%C3%A9%20Cigar%20Lounge%20%28Se7en%20Oceans%29%2C%20Hamburg%2C%20Germany',NULL,NULL,NULL,0,'Cigar lounge in the Se7en Oceans gastronomic complex (Michelin-starred restaurant). Walk-in humidor. Views over the Binnenalster. La Aurora, Davidoff and Cubans. Full cocktail bar.','Cigar lounge en el complejo gastronómico Se7en Oceans (restaurante con estrella Michelin). Humidor walk-in. Vistas al Binnenalster. La Aurora, Davidoff y cubanos. Bar de cócteles completo.','Zigarrenlounge im Gastronomiekomplex Se7en Oceans (Sterne-Restaurant). Begehbarer Humidor. Blick auf die Binnenalster. La Aurora, Davidoff und Kubaner. Vollwertige Cocktailbar.','雪茄休息室 位于complexe gastronomique Se7en Oceans (restaurant étoilé Michelin). Walk-in 雪茄保湿箱. Vue sur Binnenalster. La Aurora, Davidoff, cubains. 雪茄吧 cocktail complet.','صالات السيجار في complexe gastronomique Se7en Oceans (restaurant étoilé Michelin). Walk-in الهيوميدور. Vue sur Binnenalster. La Aurora, Davidoff, cubains. بار السيجار cocktail complet.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (38,'germany','Atlantic Hotel Bar & Smoker\'s Lounge','Hamburg — An der Alster 72-79, 20099','Hôtel 5 étoiles Cigar Lounge','+49 40 28880','€€€€','Grand hôtel légendaire de Hambourg face au lac Alster. Lounge Davidoff attenant au bar Atlantic. Décor vert, fauteuils cuir, ambiance détendue. Ouvert dim-jeu 10h-minuit, ven-sam 10h-1h.','londoncigarsmoker.com vérifiée sur place',1,'2026-03-18 09:43:40','2026-08-01 18:11:43',NULL,NULL,NULL,NULL,NULL,0,'Legendary grand hotel in Hamburg facing Lake Alster. Davidoff lounge adjoining the Atlantic bar. Green decor, leather armchairs, relaxed atmosphere. Open Sun–Thu 10am–midnight, Fri–Sat 10am–1am.','Gran hotel legendario de Hamburgo frente al lago Alster. Lounge Davidoff contiguo al bar Atlantic. Decoración verde, sillones de cuero, ambiente relajado. Abierto de dom. a jue. de 10:00 a 24:00 y vie.-sáb. de 10:00 a 1:00.','Legendäres Grandhotel in Hamburg an der Alster. Davidoff-Lounge neben der Atlantic-Bar. Grünes Dekor, Ledersessel, entspannte Atmosphäre. Geöffnet So–Do 10–24 Uhr, Fr–Sa 10–1 Uhr.','汉堡传奇大酒店，面朝阿尔斯特湖。大卫杜夫雪茄厅紧邻 Atlantic 酒吧。绿色装潢、皮质扶手椅，氛围轻松。周日至周四 10:00–24:00，周五至周六 10:00–1:00。','فندق فخم أسطوري في هامبورغ يطلّ على بحيرة ألستر. صالة دافيدوف الملاصقة لبار أتلانتيك. ديكور أخضر وكراسي جلدية وأجواء مريحة. يفتح الأحد–الخميس 10:00–24:00، والجمعة–السبت 10:00–1:00.',NULL,NULL,NULL);
