INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (44,'switzerland','La Casa del Habano — Lugano','Lugano — Via Motta 12, 6900','La Casa del Habano Officielle','+41 91 922 57 43','€€€€','La Casa del Habano officielle de Lugano (Suisse italienne).','PDF officiel Habanos S.A.',1,'2026-03-18 09:43:40','2026-08-05 11:55:09',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%20%28Lugano%29%2C%20Lugano%2C%20Switzerland',NULL,NULL,NULL,0,'Official La Casa del Habano in Lugano (Italian-speaking Switzerland).','La Casa del Habano oficial de Lugano (Suiza italiana).','Offizielle La Casa del Habano in Lugano (italienischsprachige Schweiz).','卢加诺官方 La Casa del Habano（瑞士意大利语区）。','«لا كاسا ديل هابانو» الرسمي في لوغانو (سويسرا الناطقة بالإيطالية).',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (45,'switzerland','La Casa del Habano — Nyon','Nyon, bords du Lac Léman','La Casa del Habano Officielle (seule en Suisse Romande)',NULL,'€€€€','Seule LCDH de Suisse romande. Raretés et éditions exclusives non disponibles ailleurs. Distributeur Intertabak AG.','habanos.com officiel',1,'2026-03-18 09:43:40','2026-08-01 18:19:56',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%20%28Nyon%29%2C%20Nyon%2C%20Switzerland',NULL,NULL,NULL,0,'The only La Casa del Habano in French-speaking Switzerland. Rarities and exclusive editions unavailable elsewhere. Distributed by Intertabak AG.','La única La Casa del Habano de la Suiza francófona. Rarezas y ediciones exclusivas no disponibles en otros lugares. Distribuida por Intertabak AG.','Die einzige La Casa del Habano der Westschweiz. Raritäten und exklusive Editionen, die es sonst nirgends gibt. Vertrieb durch Intertabak AG.','瑞士法语区唯一的 La Casa del Habano。备有别处买不到的珍品与专属版本。由 Intertabak AG 供货。','«لا كاسا ديل هابانو» الوحيد في سويسرا الناطقة بالفرنسية. نوادر وإصدارات حصرية لا تتوفّر في مكان آخر. يورّده Intertabak AG.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (46,'switzerland','La Casa del Habano — Mendrisio','Mendrisio — Via Angelo Maspoli 11 (près FoxTown)','La Casa del Habano Officielle',NULL,'€€€','9e LCDH de Suisse, inaugurée avril 2024. Propriétaires Alain Proietto & Sofia Belfasto.','habanos.com officiel 2024',1,'2026-03-18 09:43:40','2026-08-01 18:06:14',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%20%28Mendrisio%29%2C%20Mendrisio%2C%20Switzerland',NULL,NULL,NULL,0,'Switzerland\'s 9th La Casa del Habano, opened in April 2024. Owners Alain Proietto & Sofia Belfasto.','La 9.ª La Casa del Habano de Suiza, inaugurada en abril de 2024. Propietarios: Alain Proietto y Sofia Belfasto.','Die 9. La Casa del Habano der Schweiz, eröffnet im April 2024. Inhaber: Alain Proietto & Sofia Belfasto.','瑞士第 9 家 La Casa del Habano，2024 年 4 月开业。业主为 Alain Proietto 与 Sofia Belfasto。','تاسع «لا كاسا ديل هابانو» في سويسرا، افتُتح في أبريل 2024. المالكان ألان بروييتو وصوفيا بلفاستو.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (47,'uk','James J. Fox — St James\'s Street (fondé 1787)','London — 19 St James\'s Street, SW1A 1ES','Cigare Merchant Historique (fondé 1787)','+44 20 7930 3787','€€€€','Maison fondée en 1787 par Robert Lewis, réunie à James J. Fox en 1992. Salon de dégustation de 27 places au premier étage, musée Churchill au sous-sol. Clients historiques : Winston Churchill — sa dernière commande date du 23 décembre 1964 — et Oscar Wilde. L\'un des rares lieux du Royaume-Uni où l\'on peut fumer à l\'intérieur, au titre de l\'exemption accordée aux buralistes spécialisés.','jjfox.co.uk officiel',1,'2026-03-18 09:43:40','2026-08-26 10:38:34',NULL,NULL,NULL,NULL,NULL,0,'Founded in 1787 by Robert Lewis and merged with James J. Fox in 1992. A 27-seat tasting lounge on the first floor, a Churchill museum in the basement. Historic customers: Winston Churchill — his last order dated 23 December 1964 — and Oscar Wilde. One of the few places in the UK where you may smoke indoors, under the exemption granted to specialist tobacconists.','Casa fundada en 1787 por Robert Lewis y unida a James J. Fox en 1992. Salón de degustación de 27 plazas en la primera planta y museo Churchill en el sótano. Clientes históricos: Winston Churchill —su último pedido data del 23 de diciembre de 1964— y Oscar Wilde. Uno de los pocos lugares del Reino Unido donde se puede fumar en interior, al amparo de la exención concedida a los estancos especializados.','1787 von Robert Lewis gegründet, 1992 mit James J. Fox zusammengeführt. Verkostungslounge mit 27 Plätzen im ersten Stock, Churchill-Museum im Untergeschoss. Historische Kunden: Winston Churchill — seine letzte Bestellung datiert vom 23. Dezember 1964 — und Oscar Wilde. Einer der wenigen Orte im Vereinigten Königreich, an denen drinnen geraucht werden darf, dank der Ausnahme für Fachhändler.','1787 年由 Robert Lewis 创立，1992 年与 James J. Fox 合并。二楼设 27 座品鉴厅，地下层设丘吉尔博物馆。历史客户包括温斯顿·丘吉尔——他最后一笔订单为 1964 年 12 月 23 日——与奥斯卡·王尔德。依照给予专业烟草商的豁免，这里是英国少数可在室内吸烟的场所之一。','أسّسها روبرت لويس عام 1787 واندمجت مع «جيمس ج. فوكس» عام 1992. صالة تذوّق بسبعة وعشرين مقعدًا في الطابق الأول، ومتحف تشرشل في الطابق السفلي. من زبائنها التاريخيين ونستون تشرشل — وآخر طلبية له بتاريخ 23 ديسمبر 1964 — وأوسكار وايلد. وبفضل الاستثناء الممنوح لتجار التبغ المتخصّصين، هي من الأماكن القليلة في المملكة المتحدة التي يُسمح فيها بالتدخين داخل المبنى.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (48,'uk','James J. Fox — Harrods (La Casa del Habano)','London — Harrods, 87-135 Brompton Road, Knightsbridge, SW1X 7XL','La Casa del Habano dans Harrods',NULL,'€€€€','La Casa del Habano intégrée dans Harrods. Lounge de dégustation 10 places, système Airkel air filtration.','jjfox.co.uk officiel',1,'2026-03-18 09:43:40','2026-09-03 12:11:42',NULL,'https://www.google.com/maps/search/?api=1&query=James%20J.%20Fox%20%28Harrods%20%28La%20Casa%20del%20Habano%29%29%2C%20London%2C%20United%20Kingdom',NULL,NULL,NULL,0,'La Casa del Habano inside Harrods. A ten-seat tasting lounge with an Airkel air-filtration system.','La Casa del Habano integrada en Harrods. Lounge de degustación de diez plazas con sistema de filtración de aire Airkel.','La Casa del Habano im Inneren von Harrods. Verkostungslounge mit zehn Plätzen und Airkel-Luftfilteranlage.','哈瓦那之家 intégrée dans Harrods. 休息室 de dégustation 10 places, système Airkel air filtration.','لا كاسا ديل هابانو intégrée dans Harrods. الصالة de dégustation 10 places, système Airkel air filtration.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (49,'uk','James J. Fox — Selfridges','London — Selfridges, Oxford Street','Cave Premium Selfridges',NULL,'€€€€','The Cigar Room dans le légendaire Selfridges. Troisième boutique du groupe JJ Fox.','jjfox.co.uk officiel',1,'2026-03-18 09:43:40','2026-08-01 18:19:56',NULL,'https://www.google.com/maps/search/?api=1&query=James%20J.%20Fox%20%28Selfridges%29%2C%20London%2C%20United%20Kingdom',NULL,NULL,NULL,0,'The Cigar Room inside the legendary Selfridges. The JJ Fox group\'s third shop.','The Cigar Room en los legendarios Selfridges. Tercera tienda del grupo JJ Fox.','The Cigar Room im legendären Selfridges. Das dritte Geschäft der JJ-Fox-Gruppe.','传奇百货 Selfridges 内的 The Cigar Room。JJ Fox 集团的第三家门店。','«ذا سيجار روم» داخل متجر سلفريدجز الأسطوري. المتجر الثالث لمجموعة JJ Fox.',NULL,NULL,NULL);
