INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (89,'italy','Remedy Wine & Spirits — Cigar Room','Milano — Viale Majno 26 (angle Via Morelli)','Wine Bar & Cigar Room Premium','+39 02 38293660','€€€€','Ouvert en 2024, le rêve des bon vivants milanais. Divans en cuir, 18 000 bouteilles de vins, cigar room avec poltrone et humidor. Ouvert 18h-1h.','lombardiasecrets.com',1,'2026-03-18 09:43:40','2026-08-05 12:51:13',NULL,'https://www.google.com/maps/search/?api=1&query=Remedy%20Wine%20%26%20Spirits%20%28Cigar%20Room%29%2C%20Milano%2C%20Italy',NULL,NULL,NULL,0,'Opened in 2024, the dream of Milan\'s bon vivants. Leather sofas, 18,000 bottles of wine, a cigar room with armchairs and a humidor. Open 6pm–1am.','Inaugurado en 2024, el sueño de los bon vivants milaneses. Sofás de cuero, 18 000 botellas de vino y un cigar room con butacas y humidor. Abierto de 18:00 a 1:00.','2024 eröffnet, der Traum der Mailänder Lebemänner. Ledersofas, 18 000 Weinflaschen, ein Zigarrenraum mit Sesseln und Humidor. Geöffnet 18–1 Uhr.','Ouvert 2024年开业, le rêve des bon vivants milanais. Divans en cuir, 18 000 bouteilles de vins, cigar room，配有poltrone、雪茄保湿箱. Ouvert 18h-1h.','Ouvert عام 2024, le rêve des bon vivants milanais. Divans en cuir, 18 000 bouteilles de vins, cigar room مع poltrone والهيوميدور. Ouvert 18h-1h.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (90,'italy','Hotel De\' Ricci — Cigar Lounge (Charade Bar)','Roma — Via Colonna Antonina 32','Habanos Lounge Officiel','+39 06 680 06 04','€€€€','L\'une des 2 Habanos Lounge officielles de Rome reconnues par Habanos S.A. Wine Boutique Hotel avec 1500 étiquettes. Sélection exclusive cubaine: Trinidad, Cohiba, Montecristo. Ouvert au public avec consommation min. 30€.','foodconfidential.it, beyondthemagazine.it',1,'2026-03-18 09:43:40','2026-08-01 18:11:44',NULL,NULL,NULL,NULL,NULL,0,'One of Rome\'s two official Habanos Lounges recognised by Habanos S.A. A wine boutique hotel with 1,500 labels. Exclusive Cuban selection: Trinidad, Cohiba, Montecristo. Open to the public with a €30 minimum spend.','Uno de los dos Habanos Lounge oficiales de Roma reconocidos por Habanos S.A. Wine Boutique Hotel con 1500 etiquetas. Selección cubana exclusiva: Trinidad, Cohiba, Montecristo. Abierto al público con un consumo mínimo de 30 €.','Eine der beiden von Habanos S.A. anerkannten offiziellen Habanos Lounges Roms. Wein-Boutiquehotel mit 1500 Etiketten. Exklusive kubanische Auswahl: Trinidad, Cohiba, Montecristo. Öffentlich zugänglich, Mindestverzehr 30 €.','罗马两家获 Habanos S.A. 认可的官方 Habanos Lounge 之一。葡萄酒精品酒店，藏酒 1500 款。古巴雪茄独家精选：特立尼达、高希霸、蒙特克里斯托。对公众开放，最低消费 30 欧元。','إحدى صالتَي «هابانوس لاونج» الرسميتين في روما المعتمدتين من هابانوس ش.م. فندق بوتيك للنبيذ يضم 1500 صنف. تشكيلة كوبية حصرية: ترينيداد وكوهيبا ومونتكريستو. مفتوح للعموم بحدّ أدنى للاستهلاك 30 يورو.',NULL,NULL,NULL);
