INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (116,'japan','La Casa del Habano by Cigar Club Iikura','Tokyo — 2-3-9 Azabudai, Minato-ku','La Casa del Habano Officielle','+81 3 3583 7130','€€€€','La Casa del Habano officielle de Tokyo. Yutaka Kobayashi, Master Trainer Habanos Academia.','PDF officiel Habanos S.A., cigarjournal.com',1,'2026-03-18 09:43:40','2026-08-05 12:51:13',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%20by%20Cigar%20Club%20Iikura%2C%20Tokyo%2C%20Japan',NULL,NULL,NULL,0,'Tokyo\'s official La Casa del Habano. Yutaka Kobayashi, Master Trainer of the Habanos Academia.','La Casa del Habano oficialle de Tokyo. Yutaka Kobayashi, Master Trainer Habanos Academia.','La Casa del Habano offiziellle de Tokyo. Yutaka Kobayashi, Master Trainer Habanos Academia.','官方哈瓦那之家 的Tokyo. Yutaka Kobayashi, Master Trainer Habanos Academia.','لا كاسا ديل هابانو الرسمية من Tokyo. Yutaka Kobayashi, Master Trainer Habanos Academia.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (117,'japan','Davidoff of Geneva — Ginza Flagship','Tokyo — 8-5-6 Ginza, Chuo-ku','Davidoff Flagship','+81 3 5537 6511','€€€€','Flagship Davidoff de Tokyo à Ginza. Refuge pour executives depuis le ban sur le tabac dans les bureaux. Davidoff Signature 2000 et Aniversario Special R populaires.','cigarjournal.com',1,'2026-03-18 09:43:40','2026-08-05 12:40:55',NULL,'https://www.google.com/maps/search/?api=1&query=Davidoff%20of%20Geneva%20%28Ginza%20Flagship%29%2C%20Tokyo%2C%20Japan',NULL,NULL,NULL,0,'Davidoff\'s Tokyo flagship in Ginza. A refuge for executives since smoking was banned in offices. The Davidoff Signature 2000 and the Aniversario Special R are the favourites.','Tienda insignia de Davidoff en Tokio, en Ginza. Refugio de ejecutivos desde la prohibición de fumar en las oficinas. El Davidoff Signature 2000 y el Aniversario Special R son los favoritos.','Davidoffs Tokioter Flagshipstore in Ginza. Zufluchtsort für Führungskräfte, seit in Büros nicht mehr geraucht werden darf. Beliebt sind die Davidoff Signature 2000 und die Aniversario Special R.','位于银座的东京大卫杜夫旗舰店。自办公场所禁烟以来，成为高管们的避风港。Davidoff Signature 2000 与 Aniversario Special R 最受欢迎。','متجر دافيدوف الرئيسي في طوكيو بحي غينزا. ملاذ للمديرين منذ حظر التدخين في المكاتب. الأكثر رواجًا: دافيدوف سيغنتشر 2000 وأنيفرسايو سبيشال R.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (118,'japan','Le Connaisseur — Roppongi','Tokyo — 1-14-1 Nishiazabu, Minato-ku (Roppongi)','Cigar Bar (Cohiba Atmosphere)','+81 3 3796 3696','€€€€','Répertorié par Habanos S.A. comme Cohiba Atmosphere. Lounge cigares de référence à Tokyo. Hisashi Shimura derrière le bar depuis 20 ans. Ouvert jusqu\'à 4h le week-end.','cigarjournal.com, PDF officiel Habanos S.A.',1,'2026-03-18 09:43:40','2026-08-05 12:51:13',NULL,'https://www.google.com/maps/search/?api=1&query=Le%20Connaisseur%20%28Roppongi%29%2C%20Tokyo%2C%20Japan',NULL,NULL,NULL,0,'Listed by Habanos S.A. as a Cohiba Atmosphere. Tokyo\'s benchmark cigar lounge. Hisashi Shimura has been behind the bar for twenty years. Open until 4am at weekends.','Registrado por Habanos S.A. como Cohiba Atmosphere. El cigar lounge de referencia de Tokio. Hisashi Shimura lleva veinte años tras la barra. Abierto hasta las 4:00 los fines de semana.','Von Habanos S.A. als Cohiba Atmosphere gelistet. Tokios maßgebliche Zigarrenlounge. Hisashi Shimura steht seit zwanzig Jahren hinter der Bar. Am Wochenende bis 4 Uhr geöffnet.','经 Habanos S.A. 认证为高希霸 Atmosphere。东京的标杆雪茄厅。志村久志已在吧台后驻守二十年。周末营业至凌晨 4 点。','مُدرج لدى هابانوس ش.م. بصفته «كوهيبا أتموسفير». صالة السيجار المرجعية في طوكيو. هيساشي شيمورا خلف البار منذ عشرين عامًا. يفتح حتى الرابعة فجرًا في عطلة نهاية الأسبوع.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (119,'japan','Tableaux Lounge — Daikanyama','Tokyo — Daikanyama, Shibuya-ku','Cigar Bar & Live Jazz','+81 3 5489 2201','€€€€','Salon international à Daikanyama. Jazz live de musiciens de passage, vaste cave humidifiée, cocktails soignés. Lustres, parquet poli, fauteuils de cuir.','cigarjournal.com, flavoredtimes.com',1,'2026-03-18 09:43:40','2026-08-26 11:06:16',NULL,'https://www.google.com/maps/search/?api=1&query=Tableaux%20Lounge%20%28Daikanyama%29%2C%20Tokyo%2C%20Japan',NULL,NULL,NULL,0,'An international lounge in Daikanyama. Live jazz from visiting musicians, an extensive humidified cellar, carefully made cocktails. Chandeliers, polished parquet, leather armchairs.','Salón internacional en Daikanyama. Jazz en directo con músicos de paso, amplia bodega humidificada y cócteles cuidados. Lámparas de araña, parqué pulido y sillones de cuero.','Eine internationale Lounge in Daikanyama. Live-Jazz durchreisender Musiker, ein großer Humidorraum und sorgfältig gemixte Cocktails. Kronleuchter, poliertes Parkett, Ledersessel.','位于代官山的国际风格休息室。有客座乐手的现场爵士乐、宽敞的恒湿雪茄库与精心调制的鸡尾酒。水晶吊灯、抛光木地板与皮质扶手椅。','صالة ذات طابع دولي في دايكانياما. جاز حيّ بعزف موسيقيين زائرين، ومخزن ترطيب واسع، وكوكتيلات متقنة. ثريّات، وأرضية باركيه مصقولة، وأرائك جلدية.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (120,'japan','R261 Cigar & Rock (Cerulean Tower Tokyu Hotel)','Tokyo — Cerulean Tower, 26-1 Sakuragaokacho, Shibuya','Hotel Cigar Bar','+81 3 3476 3000','€€€€','Bar cigares rock au Cerulean Tower Hotel. 270 cigares de 45 variétés (Cuba, Rep. Dom.). Davidoff, Cohiba, Montecristo, Partagas. Whiskys japonais single malt, cognacs. Ouvert 16h-minuit.','tokyuhotels.co.jp officiel',1,'2026-03-18 09:43:40','2026-03-22 15:18:20',NULL,'https://www.google.com/maps/search/?api=1&query=R261%20Cigar%20%26%20Rock%20%28Cerulean%20Tower%20Tokyu%20Hotel%29%2C%20Tokyo%2C%20Japan',NULL,NULL,NULL,0,'Bar cigares rock au Cerulean Tower Hotel. 270 cigares de 45 variétés (Cuba, Rep. Dom.). Davidoff, Cohiba, Montecristo, Partagas. Whiskys japonais single malt, cognacs. Open 16h-minuit.','Bar cigares rock au Cerulean Tower Hotel. 270 cigares de 45 variétés (Cuba, Rep. Dom.). Davidoff, Cohiba, Montecristo, Partagas. Whiskys japonais single malt, cognacs. Abierto 16h-minuit.','Bar cigares rock au Cerulean Tower Hotel. 270 cigares de 45 variétés (Cuba, Rep. Dom.). Davidoff, Cohiba, Montecristo, Partagas. Whiskys japonais single malt, cognacs. Geöffnund 16h-minuit.','雪茄吧 cigares rock 在Cerulean Tower Hotel. 270 cigares de 45 variétés (Cuba, Rep. Dom.). Davidoff, Cohiba, Montecristo, Partagas. Whiskys japonais single malt, 干邑. Ouvert 16h-minuit.','بار السيجار cigares rock في Cerulean Tower Hotel. 270 cigares de 45 variétés (Cuba, Rep. Dom.). Davidoff, Cohiba, Montecristo, Partagas. Whiskys japonais single malt, كونياك. Ouvert 16h-minuit.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (121,'japan','Ritz-Carlton Tokyo — Lobby Lounge','Tokyo — Midtown 9-7-1, Akasaka, Minato-ku (45e étage)','Hotel Cigar Lounge','+81 3 6434 8711','€€€€','Salon cigares au 45e étage de la tour Tokyo Midtown. Vue panoramique sur la ville, cave humidifiée soignée.','flavoredtimes.com',1,'2026-03-18 09:43:40','2026-08-26 10:38:34',NULL,'https://www.google.com/maps/search/?api=1&query=Ritz-Carlton%20Tokyo%20%28Lobby%20Lounge%29%2C%20Tokyo%2C%20Japan',NULL,NULL,NULL,0,'Cigar lounge on the 45th floor of the Tokyo Midtown tower. Panoramic views over the city and a well-kept humidified cellar.','Salón de puros en la planta 45 de la torre Tokyo Midtown. Vistas panorámicas de la ciudad y bodega humidificada cuidada.','Zigarrenlounge im 45. Stock des Tokyo-Midtown-Turms. Panoramablick über die Stadt und ein sorgfältig gepflegter Humidorraum.','位于东京中城大厦 45 层的雪茄休息室。可全景俯瞰城市，恒湿雪茄库打理得当。','صالة سيجار في الطابق الخامس والأربعين من برج «طوكيو ميدتاون». إطلالة بانورامية على المدينة، ومخزن ترطيب مُعتنى به.',NULL,NULL,NULL);
