INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (140,'vietnam','La Casa del Habano — Ho Chi Minh City','Ho Chi Minh-Ville — 74b Hai Ba Trung St., D1','La Casa del Habano Officielle','+84 28 3823 0000','€€€€','Première et seule La Casa del Habano du Vietnam, inaugurée le 1er août 2021. Architecture inspirée du patrimoine colonial saïgonnais.','habanos.com officiel 2021',1,'2026-03-18 09:43:40','2026-08-26 10:42:48',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%20%28Ho%20Chi%20Minh%20City%29%2C%20Ho%20Chi%20Minh-Ville%2C%20Vietnam',NULL,NULL,NULL,0,'The first and only La Casa del Habano in Vietnam, opened on 1 August 2021. The architecture draws on Saigon\'s colonial heritage.','La primera y única La Casa del Habano de Vietnam, inaugurada el 1 de agosto de 2021. Arquitectura inspirada en el patrimonio colonial saigonés.','Das erste und einzige La Casa del Habano Vietnams, eröffnet am 1. August 2021. Die Architektur greift das koloniale Erbe Saigons auf.','越南首家也是唯一一家 La Casa del Habano，2021 年 8 月 1 日开业。建筑取材于西贡的殖民时期遗产。','أول وأوحد فرع لـ«لا كازا ديل هابانو» في فيتنام، افتُتح في 1 أغسطس 2021. عمارته مستوحاة من التراث الكولونيالي في سايغون.',NULL,NULL,NULL);
