INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (144,'azerbaijan','La Casa del Habano — Bakou','Bakou — Babek av. 21/99','La Casa del Habano Officielle','+994 12 490 62 97','€€€','La Casa del Habano officielle de Bakou.','PDF officiel Habanos S.A.',1,'2026-03-18 09:43:40','2026-08-05 11:50:50',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%20%28Bakou%29%2C%20Bakou%2C%20Azerbaijan',NULL,NULL,NULL,0,'Official La Casa del Habano in Baku.','La Casa del Habano oficial de Bakú.','Offizielle La Casa del Habano in Baku.','巴库官方 La Casa del Habano。','«لا كاسا ديل هابانو» الرسمي في باكو.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (145,'azerbaijan','La Casa del Habano — Tbilisi (Atoneli Street)','Tbilissi — 21 Atoneli Street','La Casa del Habano Officielle (Géorgie)',NULL,'€€€','Inaugurée le 20 octobre 2025 par Kaliman Caribe (distributeur Habanos pour 13 pays). 5e boutique du réseau Kaliman Caribe.','habanos.com officiel oct. 2025',1,'2026-03-18 09:43:40','2026-08-01 18:11:44',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%20%28Tbilisi%20%28Atoneli%20Street%29%29%2C%20Tbilissi%2C%20Azerbaijan',NULL,NULL,NULL,0,'Opened on 20 October 2025 by Kaliman Caribe, the Habanos distributor for 13 countries. The fifth shop in the Kaliman Caribe network.','Inaugurada el 20 de octubre de 2025 por Kaliman Caribe, distribuidor de Habanos para 13 países. Quinta tienda de la red Kaliman Caribe.','Am 20. Oktober 2025 von Kaliman Caribe eröffnet, dem Habanos-Distributor für 13 Länder. Das fünfte Geschäft des Kaliman-Caribe-Netzes.','2025 年 10 月 20 日由 Kaliman Caribe（13 个国家的 Habanos 经销商）开设。该网络的第 5 家门店。','افتُتح في 20 أكتوبر 2025 على يد «كاليمان كاريبي»، موزّع هابانوس في 13 بلدًا. المتجر الخامس ضمن شبكة كاليمان كاريبي.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (146,'usa','Davidoff of Geneva — New York (535 Madison Ave)','New York — 535 Madison Avenue (East 54th Street)','Davidoff Flagship NYC','+1 212 751 9060','€€€€','Temple mondial Davidoff à New York. Cave 1 500+ références, lounge VIP, cigares sur mesure.','nyc.com, timeout.com',1,'2026-03-18 09:43:40','2026-03-22 15:18:20',NULL,'https://www.google.com/maps/search/?api=1&query=Davidoff%20of%20Geneva%20%28New%20York%20%28535%20Madison%20Ave%29%29%2C%20New%20York%2C%20USA',NULL,NULL,NULL,0,'Temple mondial Davidoff in New York. Cave 1 500+ references, lounge VIP, cigares custom-made.','Temple mondial Davidoff à New York. Cava 1 500+ referencias, lounge VIP, cigares a medida.','Temple mondial Davidoff à New York. Keller 1 500+ Referenzen, lounge VIP, cigares maßgeschneidert.','Temple mondial Davidoff à New York. 雪茄酒窖 1 500+ 款雪茄, 休息室 VIP, cigares sur mesure.','Temple mondial Davidoff à New York. كهف السيجار 1 500+ مرجعًا, الصالة VIP, cigares sur mesure.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (147,'usa','Carnegie Club','New York — 156 West 56th Street, Midtown','Cigar Bar & Jazz Club','+1 212 957 9676','€€€€','Bibliothèques du XVIIIe sculptées, cheminée en pierre, mobilier contemporain. Sélection Cohiba, Davidoff, Partagas, Macanudo. Sinatra Saturdays depuis 15 ans (40$ entrée + orchestre 11 pièces).','cigarworld.com, timeout.com',1,'2026-03-18 09:43:40','2026-08-05 12:34:25',NULL,'https://www.google.com/maps/search/?api=1&query=Carnegie%20Club%2C%20New%20York%2C%20USA',NULL,NULL,NULL,0,'Carved eighteenth-century bookcases, a stone fireplace, contemporary furniture. Cohiba, Davidoff, Partagas and Macanudo. Sinatra Saturdays for the past fifteen years ($40 entry plus an eleven-piece orchestra).','Librerías talladas del siglo XVIII, chimenea de piedra y mobiliario contemporáneo. Cohiba, Davidoff, Partagás y Macanudo. Sinatra Saturdays desde hace quince años (40 $ de entrada más orquesta de once músicos).','Geschnitzte Bücherschränke des 18. Jahrhunderts, Steinkamin, zeitgenössisches Mobiliar. Cohiba, Davidoff, Partagas und Macanudo. Seit fünfzehn Jahren Sinatra Saturdays (40 $ Eintritt plus elfköpfiges Orchester).','18 世纪雕花书柜、石砌壁炉与当代家具。备有高希霸、大卫杜夫、帕特加斯与马卡纽多。已连续十五年举办「辛纳屈周六」（入场 40 美元，十一人乐队伴奏）。','خزائن كتب منحوتة من القرن الثامن عشر، ومدفأة حجرية، وأثاث معاصر. تشكيلة من كوهيبا ودافيدوف وبارتاغاس وماكانودو. أمسيات «سبت سيناترا» منذ خمسة عشر عامًا (الدخول 40 دولارًا مع أوركسترا من أحد عشر عازفًا).',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (148,'usa','Club Macanudo','New York — 26 East 63rd Street, Upper East Side','Cigar Lounge Premium','+1 212 752 8200','€€€€','Le meilleur lounge cigares de New York, selon les habitués. Upper East Side, à l\'angle de la 63e et de Madison. Cocktails, bar premium, sélection Cohiba, Davidoff, Montecristo.','yelp.com avis vérifiés',1,'2026-03-18 09:43:40','2026-08-05 12:51:47',NULL,'https://www.google.com/maps/search/?api=1&query=Club%20Macanudo%2C%20New%20York%2C%20USA',NULL,NULL,NULL,0,'New York\'s premier cigar lounge, according to the regulars. Upper East Side, 63rd and Madison. Cocktails, a premium bar, and a Cohiba, Davidoff and Montecristo selection.','El mejor cigar lounge de Nueva York, según los habituales. Upper East Side, esquina de la 63 con Madison. Cócteles, bar premium y selección Cohiba, Davidoff y Montecristo.','Laut Stammgästen die beste Zigarrenlounge New Yorks. Upper East Side, Ecke 63rd und Madison. Cocktails, Premium-Bar und eine Auswahl an Cohiba, Davidoff und Montecristo.','常客口中纽约最好的雪茄厅。上东区，63 街与麦迪逊大道交口。鸡尾酒、高端酒吧，以及高希霸、大卫杜夫与蒙特克里斯托精选。','أفضل صالة سيجار في نيويورك بشهادة روّادها. أبر إيست سايد، عند تقاطع الشارع 63 وجادة ماديسون. كوكتيلات وبار فاخر وتشكيلة من كوهيبا ودافيدوف ومونتكريستو.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (149,'usa','Hudson Bar and Books','New York — 636 Hudson Street, West Village','Cigar Bar & Whisky Lounge','+1 212 229 2642','€€€','Tons de cuivre, cuir luxueux, quelques célébrités de passage. Sélection de cigares restreinte mais pointue. La carte de whiskys compte parmi les meilleures de New York. Cigare personnel accepté (avec supplément).','cigarworld.com',1,'2026-03-18 09:43:40','2026-08-05 12:07:38',NULL,'https://www.google.com/maps/search/?api=1&query=Hudson%20Bar%20and%20Books%2C%20New%20York%2C%20USA',NULL,NULL,NULL,0,'Copper tones, luxurious leather, the occasional celebrity sighting. A slim but distinctive cigar selection. The whisky list is among the best in New York. Bring your own cigar accepted (fee applies).','Tonos de cobre, cuero lujoso y alguna celebridad de paso. Selección de puros reducida pero distintiva. La carta de whiskies es de las mejores de Nueva York. Se admite traer el propio puro (con recargo).','Kupfertöne, luxuriöses Leder, gelegentlich eine Prominentensichtung. Schmale, aber markante Zigarrenauswahl. Die Whiskykarte zählt zu den besten New Yorks. Eigene Zigarre erlaubt (gegen Gebühr).','铜色调、奢华皮革，偶有名流现身。雪茄阵容不大但极具特色。威士忌酒单跻身纽约最佳之列。可自带雪茄（另收费）。','درجات نحاسية وجلد فاخر، وظهور عابر لبعض المشاهير. تشكيلة سيجار محدودة لكنها مميّزة. قائمة الويسكي من الأفضل في نيويورك. يُسمح بإحضار سيجارك الخاص (مقابل رسوم).',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (150,'usa','SoHo Cigar Bar','New York — 32 Watts Street, SoHo','Cigar Bar Historique','+1 212 431 2020','€€€','Cigar bar de SoHo, au 32 Watts Street, à New York.','cigarworld.com, timeout.com',1,'2026-03-18 09:43:40','2026-08-05 13:44:21',NULL,'https://www.google.com/maps/search/?api=1&query=SoHo%20Cigar%20Bar%2C%20New%20York%2C%20USA',NULL,NULL,NULL,0,'SoHo cigar bar at 32 Watts Street, New York.','Cigar bar del SoHo, en el 32 de Watts Street, Nueva York.','Zigarrenbar in SoHo, 32 Watts Street, New York.','位于纽约苏豪区瓦茨街 32 号的雪茄吧。','بار سيجار في حي سوهو، في 32 واتس ستريت بنيويورك.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (151,'usa','Casa de Montecristo — NYC','New York — 401 Park Avenue South, Gramercy','Cave & Lounge Premium','+1 212 532 6161','€€€€','La plus grande sélection de cigares de NYC. 9 TVs (4 de 54 pouces). Fauteuils luxueux. Staff-sommeliers experts.','finetobacconyc.com',1,'2026-03-18 09:43:40','2026-08-05 12:51:13',NULL,'https://www.google.com/maps/search/?api=1&query=Casa%20de%20Montecristo%20%28NYC%29%2C%20New%20York%2C%20USA',NULL,NULL,NULL,0,'The largest cigar selection in New York City. Nine TVs (four of them 54 inches). Luxurious armchairs. Expert sommelier staff.','La mayor selección de puros de Nueva York. Nueve televisores (cuatro de 54 pulgadas). Sillones lujosos. Personal sumiller experto.','Die größte Zigarrenauswahl New Yorks. Neun Fernseher (vier davon 54 Zoll). Luxuriöse Sessel. Fachkundiges Sommelier-Personal.','纽约最大的雪茄阵容。九台电视（其中四台 54 英寸）。豪华扶手椅。侍茄师级别的专业团队。','أكبر تشكيلة سيجار في نيويورك. تسع شاشات (أربع منها 54 بوصة). كراسي وثيرة فاخرة. فريق من خبراء التذوّق.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (152,'usa','BURN by Rocky Patel — Naples FL','Naples, Florida — 698 4th Avenue South','Chaîne Premium (1re boutique 2010)','+1 239 403 7399','€€€€','1re boutique BURN, ouverte en 2010. Vaste stock, présentation en rayonnages ouverts, et une carte de restauration complète — c\'est un lieu où l\'on passe la soirée, pas seulement l\'achat.','iconiclife.com',1,'2026-03-18 09:43:40','2026-08-25 22:42:29',NULL,'https://www.google.com/maps/search/?api=1&query=BURN%20by%20Rocky%20Patel%20%28Naples%20FL%29%2C%20Naples%2C%20USA',NULL,NULL,NULL,0,'The first BURN store, opened in 2010. A large stock on open shelving, plus a full food menu — a place to spend the evening, not just to buy.','La primera tienda BURN, abierta en 2010. Amplio surtido en estanterías abiertas y una carta de restauración completa: un lugar para pasar la velada, no solo para comprar.','Der erste BURN-Store, 2010 eröffnet. Großes Sortiment in offenen Regalen und eine vollständige Speisekarte — ein Ort für den ganzen Abend, nicht nur zum Einkaufen.','首家 BURN 门店，2010 年开业。开放式货架陈列大量存货，并提供完整餐单——这里适合消磨整晚，而不只是买了就走。','أول متجر لـ«بيرن»، افتُتح عام 2010. مخزون واسع معروض على رفوف مفتوحة، وقائمة طعام كاملة — مكان تُمضى فيه السهرة، لا للشراء فحسب.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (153,'canada','La Casa del Habano — Montréal','Montréal — 1434 Sherbrooke Ouest, rez-de-chaussée, H3g 1K4','La Casa del Habano Officielle','+1 514 849 0037','€€€€','La Casa del Habano officielle de Montréal. Accès légal aux Habanos cubains (contrairement aux USA).','PDF officiel Habanos S.A.',1,'2026-03-18 09:43:40','2026-08-05 12:40:55',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%20%28Montr%C3%A9al%29%2C%20Montr%C3%A9al%2C%20Canada',NULL,NULL,NULL,0,'Montreal\'s official La Casa del Habano. Legal access to Cuban Habanos, unlike in the United States.','La Casa del Habano oficialle de Montréal. Accès légal aux Habanos cubains (contrairement aux USA).','La Casa del Habano offiziellle de Montréal. Accès légal aux Habanos cubains (contrairement aux USA).','官方哈瓦那之家 的Montréal. Accès légal aux Habanos cubains (contrairement aux USA).','لا كاسا ديل هابانو الرسمية من Montréal. Accès légal aux Habanos cubains (contrairement aux USA).',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (154,'canada','La Casa del Habano — Toronto (Yorkville)','Toronto — 113 Yorkville Avenue, M5R 1C1','La Casa del Habano Officielle','+1 416 926 9066','€€€€','La Casa del Habano officielle de Toronto dans le chic quartier Yorkville.','PDF officiel Habanos S.A.',1,'2026-03-18 09:43:40','2026-08-01 18:15:50',NULL,NULL,NULL,NULL,NULL,0,'Toronto\'s official La Casa del Habano, in the chic Yorkville district.','La Casa del Habano oficial de Toronto, en el elegante barrio de Yorkville.','Die offizielle La Casa del Habano in Toronto, im schicken Viertel Yorkville.','多伦多官方 La Casa del Habano，位于时尚的约克维尔区。','«لا كاسا ديل هابانو» الرسمي في تورونتو، بحي يوركفيل الأنيق.',NULL,NULL,NULL);
