INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (196,'philippines','Tabacalera Cigar Boutique — Intramuros','Manille — Intramuros (ville fortifiée historique)','Boutique Historique (fondée 1782)','+63 2 527 4444','€€€','La marque nationale philippine de cigares la plus ancienne (1782). Éditions collector des centenaires dans la ville coloniale espagnole classée.','cigarjournal.com',1,'2026-03-18 09:43:40','2026-08-05 12:51:13',NULL,'https://www.google.com/maps/search/?api=1&query=Tabacalera%20Cigar%20Boutique%20%28Intramuros%29%2C%20Manille%2C%20Philippines',NULL,NULL,NULL,0,'The oldest Philippine national cigar brand (1782). Centenary collector\'s editions, in the listed Spanish colonial city.','La marca nacional filipina de puros más antigua (1782). Ediciones de coleccionista de los centenarios, en la ciudad colonial española declarada patrimonio.','Die älteste philippinische Nationalmarke für Zigarren (1782). Sammler-Jubiläumsausgaben, in der denkmalgeschützten spanischen Kolonialstadt.','La marque nationale philippine de cigares la 最古老的 (1782). Éditions collector des centenaires 位于ville coloniale espagnole classée.','La marque nationale philippine de cigares la الأقدم (1782). Éditions collector des centenaires في ville coloniale espagnole classée.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (197,'australia','La Casa del Habano — Melbourne (Grand Hyatt)','Melbourne — Ground Floor, Grand Hyatt, 123 Collins Street','La Casa del Habano Officielle (seule d\'Australie)','+61 3 9650 0800','€€€€','Seule La Casa del Habano officielle d\'Australie, dans le Grand Hyatt Melbourne sur Collins Street.','PDF officiel Habanos S.A.',1,'2026-03-18 09:43:40','2026-08-01 18:19:56',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%20%28Melbourne%20%28Grand%20Hyatt%29%29%2C%20Melbourne%2C%20Australia',NULL,NULL,NULL,0,'Australia\'s only official La Casa del Habano, in the Grand Hyatt Melbourne on Collins Street.','La única La Casa del Habano oficial de Australia, en el Grand Hyatt Melbourne de Collins Street.','Die einzige offizielle La Casa del Habano Australiens, im Grand Hyatt Melbourne an der Collins Street.','澳大利亚唯一的官方 La Casa del Habano，位于柯林斯街的墨尔本君悦酒店内。','«لا كاسا ديل هابانو» الرسمي الوحيد في أستراليا، داخل فندق غراند حياة ملبورن في شارع كولينز.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (198,'australia','Davidoff — Sydney','Sydney, NSW','Davidoff Appointed Merchant','+61 2 9232 5454','€€€€','La boutique Davidoff officielle de Sydney, dans le CBD. Gamme Davidoff complète, cave humidifiée où l\'on entre, lounge cigares premium — l\'adresse Davidoff de référence en Australie.','cigarjournal.com',1,'2026-03-18 09:43:40','2026-08-25 02:40:14',NULL,'https://www.google.com/maps/search/?api=1&query=Davidoff%20%28Sydney%29%2C%20Sydney%2C%20Australia',NULL,NULL,NULL,0,'Davidoff\'s official Sydney boutique in the CBD. Complete Davidoff range, walk-in humidor, premium cigar lounge — Australia\'s flagship Davidoff address.','Boutique Davidoff oficialle de Sydney. Cava premium, lounge de dégustation.','Boutique Davidoff offiziellle de Sydney. Keller premium, lounge de dégustation.','大卫杜夫精品店 （官方） 的Sydney. 雪茄酒窖 精品, 休息室 de dégustation.','بوتيك ديفيدوف الرسمية من Sydney. كهف السيجار متميز, الصالة de dégustation.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (228,'france','Habanos House Paris — Hôtel de Vendôme','Paris 1er — 1 Place Vendôme','Habanos Lounge Officiel','+33 1 55 04 55 00','€€€€','Lounge Habanos officiel dans le palace Place Vendôme, cave voutée extraordinaire.','habanos.com',1,'2026-03-18 23:04:48','2026-08-05 12:51:13',NULL,'https://www.google.com/maps/search/?api=1&query=Habanos%20House%20Paris%20%28H%C3%B4tel%20de%20Vend%C3%B4me%29%2C%20Paris%201er%2C%20France',NULL,NULL,NULL,0,'Official Habanos lounge in the Place Vendôme palace hotel, with an extraordinary vaulted cellar.','Lounge Habanos oficial en el palacio de la Place Vendôme, con una bodega abovedada extraordinaria.','Offizielle Habanos-Lounge im Grandhotel an der Place Vendôme, mit außergewöhnlichem Gewölbekeller.','休息室 Habanos officiel 位于palace Place Vendôme, 雪茄酒窖 voutée extraordinaire.','الصالة Habanos officiel في palace Place Vendôme, كهف السيجار voutée extraordinaire.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (229,'france','Davidoff — Rue de Rivoli','Paris 1er — 234 Rue de Rivoli','Davidoff Flagship','+33 1 42 60 73 25','€€€€','Flagship Davidoff de Paris face aux Tuileries — service expert, humidor climatisé 2000 références.','davidoff.com',1,'2026-03-18 23:04:48','2026-08-05 14:03:25',NULL,'https://www.google.com/maps/search/?api=1&query=Davidoff%2C%20Paris%201er%2C%20France',NULL,NULL,NULL,0,'Davidoff\'s Paris flagship facing the Tuileries — expert service, a climate-controlled humidor holding 2,000 references.','Flagship Davidoff de Paris face aux Tuileries — service expert, humidor climatisé 2000 referencias.','Flagship Davidoff de Paris face aux Tuileries — service expert, Humidor climatisé 2000 Referenzen.','大卫杜夫旗舰店 的Paris face aux Tuileries — service expert, 雪茄保湿箱 climatisé 2000 款雪茄.','متجر ديفيدوف الرائد من Paris face aux Tuileries — service expert, الهيوميدور climatisé 2000 مرجعًا.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (230,'france','SEITA — Musée du Tabac','Paris 9e — 12 Rue Surcouf','Musée & Boutique Historique','+33 1 45 56 60 17','€€','Musée du tabac avec boutique de cigares — expérience culturelle unique.','altadis.com',1,'2026-03-18 23:04:48','2026-08-05 12:02:56',NULL,'https://www.google.com/maps/search/?api=1&query=SEITA%20%28Mus%C3%A9e%20du%20Tabac%29%2C%20Paris%209e%2C%20France',NULL,NULL,NULL,0,'Tobacco museum with a cigar shop — a unique cultural experience.','Museo del tabaco con estanco: una experiencia cultural única.','Tabakmuseum mit Zigarrenladen — ein einzigartiges kulturelles Erlebnis.','设有雪茄专卖店的烟草博物馆——独特的文化体验。','متحف للتبغ مع متجر سيجار — تجربة ثقافية فريدة.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (231,'france','Maison de la Truffe et du Cigare','Paris 8e — 97 Rue du Faubourg Saint-Honoré','Cave Premium','+33 1 42 65 53 22','€€€€','Alliance rare entre la gastronomie de la truffe du Périgord et les cigares premium, dans le triangle d\'or parisien. Dîners d\'accords réguliers, où les grandes truffes rencontrent les grands havanes.','maisondelatruffe.com',1,'2026-03-18 23:04:48','2026-08-05 12:07:38',NULL,'https://www.google.com/maps/search/?api=1&query=Maison%20de%20la%20Truffe%20et%20du%20Cigare%2C%20Paris%208e%2C%20France',NULL,NULL,NULL,0,'Rare combination of Périgord truffle gastronomy and premium cigars in Paris\'s golden triangle. Regular pairing dinners where great truffles meet grand Habanos.','Combinación poco común de gastronomía de la trufa del Périgord y puros premium, en el triángulo de oro parisino. Cenas de maridaje periódicas donde las grandes trufas se encuentran con los grandes habanos.','Seltene Verbindung von Périgord-Trüffelküche und Premium-Zigarren im Pariser Goldenen Dreieck. Regelmäßige Pairing-Dinner, bei denen große Trüffel auf große Havannas treffen.','巴黎黄金三角地带罕见的组合：佩里戈尔松露美食与高端雪茄。定期举办搭配晚宴，让顶级松露与顶级哈瓦那相遇。','مزيج نادر بين مطبخ كمأة البيريغور والسيجار الفاخر، في المثلّث الذهبي بباريس. عشاءات مزاوجة دورية تلتقي فيها الكمأة الفاخرة بسيجار هافانا الكبير.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (232,'france','Viñales Lounge — Le Royal Monceau','Paris 8e — 37 avenue Hoche, 75008','Palace Cigar Lounge','+33 1 42 99 88 00','€€€€','Salon cigares du Royal Monceau, ouvert en 2018. Fauteuils club en cuir, ouvrages d\'art et terrasse donnant sur une cour privée de l\'hôtel. Accès à la journée, payant, pour les clients de l\'hôtel comme pour les visiteurs.','raffles.com',1,'2026-03-18 23:04:48','2026-09-04 17:20:49',NULL,'https://www.google.com/maps/search/?api=1&query=Le%20Bar%20Long%20%28H%C3%B4tel%20Le%20Royal%20Monceau%29%2C%20Paris%208e%2C%20France','https://www.raffles.com/paris/dining/vinales-lounge/',NULL,NULL,0,'Cigar lounge of Le Royal Monceau, opened in 2018. Leather club armchairs, art books and a terrace opening onto one of the hotel\'s private courtyards. Paid day access, for hotel guests and outside visitors alike.','Salón de puros de Le Royal Monceau, abierto en 2018. Sillones club de cuero, libros de arte y una terraza que da a uno de los patios privados del hotel. Acceso de día, de pago, tanto para huéspedes como para visitantes externos.','Zigarrenlounge des Royal Monceau, eröffnet 2018. Lederne Clubsessel, Kunstbände und eine Terrasse zu einem der privaten Innenhöfe des Hauses. Kostenpflichtiger Tageszugang, für Hotelgäste wie für externe Besucher.','皇家蒙梭酒店的雪茄吧，2018 年开设。皮质俱乐部扶手椅、艺术书籍，以及一处朝向酒店私人庭院的露台。提供日间付费入场，酒店住客与外来访客均可。','صالة السيجار في فندق لو رويال مونسو، افتُتحت عام 2018. مقاعد نادٍ جلدية، وكتب فنية، وشرفة تطلّ على أحد الأفنية الخاصة بالفندق. دخول يومي مدفوع، لنزلاء الفندق وللزوار من الخارج على السواء.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (233,'france','Davidoff — Bordeaux','Bordeaux — 20 Place Gambetta','Davidoff Appointed Merchant','+33 5 56 48 15 97','€€€','Revendeur agréé Davidoff dans le centre historique de Bordeaux.','davidoff.com',1,'2026-03-18 23:04:48','2026-08-05 12:02:57',NULL,'https://www.google.com/maps/search/?api=1&query=Davidoff%20%28Bordeaux%29%2C%20Bordeaux%2C%20France',NULL,NULL,NULL,0,'Davidoff appointed merchant in Bordeaux\'s historic centre.','Distribuidor autorizado Davidoff en el centro histórico de Burdeos.','Autorisierter Davidoff-Händler im historischen Zentrum von Bordeaux.','波尔多历史城区的大卫杜夫特许经销商。','وكيل دافيدوف المعتمد في وسط بوردو التاريخي.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (234,'france','La Casa del Habano — Lyon','Lyon 6e — 54 Rue de la Bourse','La Casa del Habano Officielle','+33 4 78 24 88 24','€€€','La Casa del Habano officielle de Lyon, première boutique de la région Rhône-Alpes.','à vérifier — réseau La Casa del Habano, liste officielle non recoupée',1,'2026-03-18 23:04:48','2026-09-02 22:27:26',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%20%28Lyon%29%2C%20Lyon%206e%2C%20France',NULL,NULL,NULL,0,'Lyon\'s official La Casa del Habano, the first shop in the Rhône-Alpes region.','La Casa del Habano oficialle de Lyon, primera boutique de la région Rhône-Alpes.','La Casa del Habano offiziellle de Lyon, erste boutique de la région Rhône-Alpes.','官方哈瓦那之家 的Lyon, première 精品店 de la région Rhône-Alpes.','لا كاسا ديل هابانو الرسمية من Lyon, première بوتيك de la région Rhône-Alpes.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (235,'france','La Cave du Cigare — Cannes','Cannes — 20 Rue d\'Antibes','Cave Premium','+33 4 93 39 32 54','€€€€','Cave premium sur la rue commerçante de Cannes, clientèle yacht et festival.','RETIRÉ — aucune trace de cet établissement, et le domaine cité n\'existe pas',0,'2026-03-18 23:04:48','2026-09-04 17:20:49',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Cave%20du%20Cigare%20%28Cannes%29%2C%20Cannes%2C%20France',NULL,NULL,NULL,0,'Premium cigar shop on Cannes\'s main shopping street, serving the yachting and festival crowd.','Estanco premium en la calle comercial de Cannes, con clientela de yates y festival.','Premium-Zigarrenladen in der Einkaufsstraße von Cannes, mit Publikum aus Yacht- und Festivalwelt.','位于戛纳商业街的高端雪茄行，客群来自游艇圈与电影节。','متجر سيجار فاخر في شارع التسوّق بمدينة كان، يقصده روّاد اليخوت والمهرجان.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (236,'france','Cigare Attitude — Nice','Nice — 22 Rue de la Liberté','Cave & Lounge','+33 4 93 88 43 14','€€€','La boutique cigare de référence de la Côte d\'Azur depuis 2003. Équipe experte au niveau d\'un sommelier, catalogue Habanos complet, clientèle fidèle de Monaco à Cannes.','RETIRÉ — aucune trace de cet établissement, et le domaine cité n\'existe pas',0,'2026-03-18 23:04:48','2026-09-04 17:20:49',NULL,'https://www.google.com/maps/search/?api=1&query=Cigare%20Attitude%20%28Nice%29%2C%20Nice%2C%20France',NULL,NULL,NULL,0,'The Côte d\'Azur\'s reference cigar boutique since 2003. Expert team with sommelier-level knowledge, full Habanos catalog, devoted clientele from Monaco to Cannes.','La boutique cigarrera de referencia de la Costa Azul desde 2003. Equipo experto con conocimiento de sumiller, catálogo Habanos completo y clientela fiel de Mónaco a Cannes.','Seit 2003 die maßgebliche Zigarrenboutique der Côte d\'Azur. Fachteam auf Sommelier-Niveau, kompletter Habanos-Katalog, treue Kundschaft von Monaco bis Cannes.','自 2003 年起蔚蓝海岸的标杆雪茄店。团队具备侍酒师级别的专业知识，哈瓦那雪茄目录齐全，客群从摩纳哥延伸至戛纳。','متجر السيجار المرجعي على الريفييرا الفرنسية منذ 2003. فريق بخبرة تضاهي خبرة السوميليه، وكتالوج هابانوس كامل، وزبائن أوفياء من موناكو إلى كان.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (237,'france','Au Régal du Palais — Strasbourg','Strasbourg — 11 Place de la Cathédrale','Cave Premium','+33 3 88 22 62 46','€€€','Civette historique à deux pas de la cathédrale gothique de Strasbourg, classée à l\'UNESCO. Hospitalité alsacienne, sélection européenne et cubaine.','TripAdvisor',1,'2026-03-18 23:04:48','2026-08-05 12:51:47',NULL,'https://www.google.com/maps/search/?api=1&query=Au%20R%C3%A9gal%20du%20Palais%20%28Strasbourg%29%2C%20Strasbourg%2C%20France',NULL,NULL,NULL,0,'Historic tobacconist steps from Strasbourg\'s UNESCO-listed Gothic cathedral. Alsatian hospitality, European and Cuban selection.','Estanquería histórica a pocos pasos de la catedral gótica de Estrasburgo, Patrimonio de la Humanidad. Hospitalidad alsaciana, selección europea y cubana.','Historischer Tabakladen wenige Schritte vom UNESCO-gelisteten gotischen Straßburger Münster. Elsässische Gastfreundschaft, europäische und kubanische Auswahl.','位于联合国教科文组织所列的斯特拉斯堡哥特式大教堂旁的老牌烟草行。阿尔萨斯式款待，欧洲与古巴雪茄精选。','متجر تبغ عريق على بُعد خطوات من كاتدرائية ستراسبورغ القوطية المدرجة على قائمة اليونسكو. ضيافة ألزاسية وتشكيلة أوروبية وكوبية.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (238,'france','Tabacs Petitjean — Nancy','Nancy — 24 Place Stanislas','Civette Historique','+33 3 83 32 44 10','€€€','Civette historique sur la magnifique place Stanislas, la place baroque de Nancy classée à l\'UNESCO. L\'une des adresses à cigares les mieux situées de France.','Google Maps',1,'2026-03-18 23:04:48','2026-08-30 15:06:29',NULL,'https://www.google.com/maps/search/?api=1&query=Tabacs%20Petitjean%20%28Nancy%29%2C%20Nancy%2C%20France',NULL,NULL,NULL,0,'Historic tobacconist on the magnificent Place Stanislas, Nancy\'s UNESCO-listed baroque square. One of France\'s most beautifully located cigar addresses.','Estanco histórico en la magnífica plaza Stanislas, la plaza barroca de Nancy declarada Patrimonio de la Humanidad por la UNESCO. Una de las direcciones cigarreras mejor situadas de Francia.','Historischer Tabakladen an der prächtigen Place Stanislas, dem UNESCO-gelisteten Barockplatz von Nancy. Eine der am schönsten gelegenen Zigarrenadressen Frankreichs.','位于宏伟的斯坦尼斯拉斯广场上的老字号烟草店——这座南锡的巴洛克广场已列入联合国教科文组织名录。它是法国选址最美的雪茄地址之一。','متجر تبغ عريق في ساحة ستانيسلاس الفخمة، ساحة نانسي الباروكية المدرجة على قائمة اليونسكو. من أجمل عناوين السيجار موقعًا في فرنسا.',NULL,NULL,NULL);
