INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (240,'france','Davidoff — Marseille (Vieux-Port)','Marseille 1er — 56 La Canebière','Davidoff Appointed Merchant','+33 4 91 54 78 90','€€€','Revendeur agréé Davidoff sur la Canebière, vue sur le Vieux-Port.','davidoff.com',1,'2026-03-18 23:04:48','2026-08-05 13:44:22',NULL,'https://www.google.com/maps/search/?api=1&query=Davidoff%20%28Marseille%20%28Vieux-Port%29%29%2C%20Marseille%201er%2C%20France',NULL,NULL,NULL,0,'Davidoff appointed merchant on the Canebière, overlooking the Vieux-Port.','Distribuidor autorizado Davidoff en la Canebière, con vistas al Puerto Viejo.','Autorisierter Davidoff-Händler an der Canebière, mit Blick auf den Alten Hafen.','位于卡纳比埃大道的大卫杜夫特许经销商，可望旧港。','وكيل دافيدوف المعتمد في جادة الكانبيير، بإطلالة على الميناء القديم.',NULL,NULL,NULL);
