INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (277,'uk','Sautter of Mayfair','London — 106 Mount Street, Mayfair, W1K 2TW','Cave Premium','+44 20 7499 4866','€€€€','Maison de Mount Street fondée il y a plus de cinquante ans, installée à cette adresse depuis plus de trente. Havanes vieillis et millésimes anciens. Une seconde adresse à Knightsbridge, 8 Raphael Street.','sauttercigars.com',1,'2026-03-18 23:04:48','2026-09-04 17:20:49',NULL,'https://www.google.com/maps/search/?api=1&query=Sautter%20of%20Mayfair%2C%20London%2C%20United%20Kingdom','https://www.sauttercigars.com/',NULL,NULL,0,'Mount Street house founded over fifty years ago, at this address for more than thirty. Aged Havanas and old vintages. A second address in Knightsbridge, 8 Raphael Street.','Casa de Mount Street fundada hace más de cincuenta años, en esta dirección desde hace más de treinta. Habanos envejecidos y añadas antiguas. Una segunda dirección en Knightsbridge, 8 Raphael Street.','Haus in der Mount Street, vor über fünfzig Jahren gegründet, seit mehr als dreißig Jahren an dieser Adresse. Gereifte Havannas und alte Jahrgänge. Eine zweite Adresse in Knightsbridge, 8 Raphael Street.','芒特街的老字号，创立逾五十年，在此地址经营超过三十年。以陈年哈瓦那雪茄与旧年份存货见长。另于骑士桥 8 Raphael Street 设有第二家门店。','دار في شارع ماونت تأسست قبل أكثر من خمسين عامًا، وفي هذا العنوان منذ أكثر من ثلاثين. سيجار هافانا معتّق وسنوات إنتاج قديمة. ولها عنوان ثانٍ في نايتسبريدج، 8 Raphael Street.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (278,'uk','The Ritz — Cigar Terrace','London — 150 Piccadilly, Mayfair, W1J 9BR','Palace Cigar Lounge','+44 20 7493 8181','€€€€','La terrasse cigare privée du Ritz London, au 150 Piccadilly. Accessible aux membres et aux clients de l\'hôtel ; cocktails signature, et une adresse qui sert la royauté depuis plus d\'un siècle.','theritzlondon.com',1,'2026-03-18 23:04:48','2026-08-05 12:07:38',NULL,'https://www.google.com/maps/search/?api=1&query=The%20Ritz%20%28Cigar%20Terrace%29%2C%20London%2C%20United%20Kingdom',NULL,NULL,NULL,0,'The Ritz London\'s private cigar terrace at 150 Piccadilly. Accessible to members and hotel guests; signature cocktails and an address that has served royalty for over a century.','La terraza de puros privada del Ritz London, en el 150 de Piccadilly. Accesible a socios y huéspedes del hotel; cócteles de autor y una dirección que sirve a la realeza desde hace más de un siglo.','Die private Zigarrenterrasse des Ritz London, 150 Piccadilly. Zugänglich für Mitglieder und Hotelgäste; Signature-Cocktails und eine Adresse, die seit über einem Jahrhundert Könige bedient.','Terrasse cigare privée 的','Terrasse cigare privée من',NULL,NULL,NULL);
