INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (281,'uk','Turmeaus — Liverpool','Liverpool — 11 Castle Street, L2 4XB','La Casa del Habano Officielle','+44 151 236 4237','€€€','La Casa del Habano de C.Gars Ltd à Liverpool. Gamme Habanos complète, cave humidifiée où l\'on entre, bar à whisky — l\'adresse cigare qui fait autorité dans le nord de l\'Angleterre.','cgars.co.uk',1,'2026-03-18 23:04:48','2026-08-25 02:40:14',NULL,'https://www.google.com/maps/search/?api=1&query=Turmeaus%20%28Liverpool%29%2C%20Liverpool%2C%20United%20Kingdom',NULL,NULL,NULL,0,'C.Gars Ltd\'s La Casa del Habano in Liverpool. Complete Habanos range, walk-in humidor, whisky bar — the North of England\'s most authoritative cigar address.','La Casa del Habano de C.Gars Ltd en Liverpool. Gama Habanos completa, humidor walk-in y bar de whisky: la dirección cigarrera de referencia en el norte de Inglaterra.','Die La Casa del Habano von C.Gars Ltd in Liverpool. Komplettes Habanos-Sortiment, begehbarer Humidor, Whiskybar — die maßgebliche Zigarrenadresse Nordenglands.','哈瓦那之家 的Liverpool, référence 的Nord 的','لا كاسا ديل هابانو من Liverpool, référence في Nord من',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (282,'uk','Turmeaus — Edinburgh','Edinburgh — 35 Frederick Street, EH2 1EP','La Casa del Habano Officielle','+44 131 225 4064','€€€','La Casa del Habano de C.Gars Ltd, dans la New Town d\'Édimbourg. Le premier spécialiste écossais des Habanos, doublé d\'une sélection remarquable de single malts.','cgars.co.uk',1,'2026-03-18 23:04:48','2026-08-05 12:07:38',NULL,'https://www.google.com/maps/search/?api=1&query=Turmeaus%20%28Edinburgh%29%2C%20Edinburgh%2C%20United%20Kingdom',NULL,NULL,NULL,0,'C.Gars Ltd\'s La Casa del Habano in Edinburgh\'s New Town. Scotland\'s foremost Habanos specialist, paired with an outstanding single malt selection.','La Casa del Habano de C.Gars Ltd en la New Town de Edimburgo. El principal especialista escocés en Habanos, con una notable selección de single malts.','Die La Casa del Habano von C.Gars Ltd in Edinburghs New Town. Schottlands führender Habanos-Spezialist, ergänzt um eine herausragende Single-Malt-Auswahl.','C.Gars Ltd 旗下的 La Casa del Habano，位于爱丁堡新城。苏格兰首屈一指的哈瓦那雪茄专家，辅以出色的单一麦芽威士忌阵容。','«لا كاسا ديل هابانو» التابع لشركة C.Gars في نيو تاون بإدنبرة. أبرز متخصّص اسكتلندي في سيجار هابانوس، مع تشكيلة لافتة من المولت المفرد.',NULL,NULL,NULL);
