INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1189,'ivorycoast','Le Radisson Blu — Sky Bar Cigares','Abidjan, Plateau — Radisson Blu Hotel, Avenue Franchet d\'Esperey','Rooftop Bar','+225 27 20 20 90 00','€€€€','Rooftop panoramique de l\'hôtel Radisson Blu Abidjan Plateau. Espace cigares en soirée avec vue sur la lagune Ébrié et les gratte-ciels du Plateau.','radissonblu.com',1,'2026-03-21 10:30:53','2026-08-01 18:19:56',NULL,NULL,NULL,NULL,NULL,0,'Panoramic rooftop of the Radisson Blu Abidjan Plateau. Evening cigar area overlooking the Ébrié Lagoon and the Plateau skyline.','Azotea panorámica del hotel Radisson Blu Abidjan Plateau. Espacio de puros por la noche con vistas a la laguna Ébrié y a los rascacielos del Plateau.','Panorama-Dachterrasse des Radisson Blu Abidjan Plateau. Abendlicher Zigarrenbereich mit Blick auf die Ébrié-Lagune und die Hochhäuser des Plateau.','阿比让高原丽笙酒店的全景顶层。夜间雪茄区可俯瞰埃布里耶潟湖与高原区摩天楼群。','سطح بانورامي في فندق راديسون بلو أبيدجان بلاتو. ركن للسيجار في المساء يطلّ على بحيرة إيبريي وناطحات سحاب حي بلاتو.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1190,'ivorycoast','Golf Club d\'Abidjan — Club House Cigares','Abidjan, Bingerville — BP 1216, Bingerville','Club de Golf','+225 27 22 40 07 07','€€€€','Le plus ancien et prestigious golf club d\'Abidjan, fondé en 1953. Club house avec espace cigares après le parcours, clientèle expatriée et élite ivoirienne.','RETIRÉ — aucune trace de cet établissement, et le domaine cité n\'existe pas',0,'2026-03-21 10:30:53','2026-09-04 17:37:41',NULL,NULL,NULL,NULL,NULL,0,'Abidjan\'s oldest and most prestigious golf club, founded in 1953. Clubhouse with a cigar area for after the round, serving expatriates and the Ivorian elite.','El club de golf más antiguo y prestigioso de Abiyán, fundado en 1953. Casa club con espacio de puros tras la vuelta; clientela expatriada y élite marfileña.','Der älteste und prestigeträchtigste Golfclub Abidjans, gegründet 1953. Clubhaus mit Zigarrenbereich für nach der Runde, Publikum aus Expats und ivorischer Elite.','阿比让最古老、最负盛名的高尔夫俱乐部，创立于 1953 年。会所设球后雪茄区，客群为外派人士与科特迪瓦精英。','أقدم وأعرق نادي غولف في أبيدجان، تأسّس عام 1953. مبنى النادي بركن للسيجار بعد الجولة، يقصده المغتربون والنخبة الإيفوارية.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1191,'ivorycoast','Sofitel Abidjan Hotel Ivoire — Fumoir','Abidjan, Cocody — Boulevard Hassan II','Palace Cigar Lounge','+225 27 22 40 26 26','€€€€','Icône de l\'hôtellerie ouest-africaine depuis 1963. Fumoir avec sélection de cigares cubains et dominicains, clientèle diplomatique et hommes d\'affaires de passage.','sofitel.com',1,'2026-03-21 10:30:53','2026-08-01 18:11:43',NULL,NULL,NULL,NULL,NULL,0,'An icon of West African hospitality since 1963. Smoking room with a selection of Cuban and Dominican cigars, serving diplomats and visiting business travellers.','Icono de la hostelería de África Occidental desde 1963. Fumador con selección de puros cubanos y dominicanos; clientela diplomática y de negocios de paso.','Eine Ikone der westafrikanischen Hotellerie seit 1963. Rauchsalon mit kubanischen und dominikanischen Zigarren, Publikum aus Diplomatie und durchreisender Geschäftswelt.','自 1963 年起的西非酒店业标志。吸烟室备有古巴与多米尼加雪茄精选，客群为外交人士与过境商务旅客。','أيقونة الضيافة في غرب أفريقيا منذ 1963. صالة تدخين بتشكيلة من السيجار الكوبي والدومينيكي، يقصدها الدبلوماسيون ورجال الأعمال العابرون.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1201,'morocco','La Mamounia — Fumoir Churchill','Marrakech — Avenue Bab Jdid, 40040','Palace Cigar Bar Historique','+212 524 38 86 00','€€€€','Palace légendaire de Marrakech (1923), préféré de Winston Churchill qui y séjournait régulièrement. Fumoir Churchill avec cigares Cohiba et Romeo y Julieta, décor Art Déco.','mamounia.com',1,'2026-03-21 10:30:53','2026-08-01 18:19:56',NULL,NULL,NULL,NULL,NULL,0,'Legendary Marrakech palace hotel (1923), a favourite of Winston Churchill, who stayed here regularly. Churchill smoking room with Cohiba and Romeo y Julieta cigars, in Art Deco surroundings.','Palacio legendario de Marrakech (1923), preferido de Winston Churchill, que se alojaba allí con regularidad. Fumador Churchill con puros Cohiba y Romeo y Julieta, en decoración art déco.','Legendäres Grandhotel in Marrakesch (1923), Lieblingsort Winston Churchills, der hier regelmäßig wohnte. Churchill-Rauchsalon mit Cohiba- und Romeo-y-Julieta-Zigarren, im Art-déco-Dekor.','马拉喀什的传奇宫殿酒店（1923 年），温斯顿·丘吉尔的心头好，他曾多次下榻于此。丘吉尔吸烟室供应高希霸与罗密欧与朱丽叶，装饰艺术风格。','فندق قصر أسطوري في مراكش (1923)، كان مقصد ونستون تشرشل المفضّل وأقام فيه مرارًا. صالة تدخين تشرشل بسيجار كوهيبا وروميو إي جولييتا، بديكور آرت ديكو.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1202,'morocco','Royal Golf Marrakech — Club House Cigares','Marrakech — Av. de la Menara, Hivernage','Club de Golf','+212 524 40 98 28','€€€€','Golf royal fondé par le Roi Mohammed V en 1923. Club house marocain avec espace cigares et thé à la menthe, terrasse face à l\'Atlas enneigé.','royalgolfmarrakech.com',1,'2026-03-21 10:30:53','2026-08-01 18:11:43',NULL,NULL,NULL,NULL,NULL,0,'Royal golf course founded by King Mohammed V in 1923. Moroccan clubhouse with a cigar area and mint tea, and a terrace facing the snow-capped Atlas.','Golf real fundado por el rey Mohamed V en 1923. Casa club marroquí con espacio de puros y té a la menta, y terraza frente al Atlas nevado.','Königlicher Golfplatz, 1923 von König Mohammed V. gegründet. Marokkanisches Clubhaus mit Zigarrenbereich und Minztee, Terrasse mit Blick auf den verschneiten Atlas.','1923 年由穆罕默德五世国王创建的皇家高尔夫球场。摩洛哥式会所设雪茄区并供应薄荷茶，露台正对积雪的阿特拉斯山。','ملعب غولف ملكي أسّسه الملك محمد الخامس عام 1923. مبنى نادٍ مغربي بركن للسيجار وشاي بالنعناع، وتراس يطلّ على أطلس المكلّلة بالثلوج.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1208,'southafrica','One&Only Cape Town — Cigar Lounge','Cape Town — Dock Road, V&A Waterfront, 8001','Palace Cigar Lounge','+27 21 431 5888','€€€€','Palace 5 étoiles au bord du V&A Waterfront. Cigar lounge avec vue sur la Montagne de la Table, sélection premium, clientèle business internationale.','oneandonlyresorts.com',1,'2026-03-21 10:30:53','2026-08-01 18:19:56',NULL,NULL,NULL,NULL,NULL,0,'Five-star palace hotel on the V&A Waterfront. Cigar lounge with a view of Table Mountain, a premium selection, and an international business clientele.','Palacio de cinco estrellas junto al V&A Waterfront. Cigar lounge con vistas a la Montaña de la Mesa, selección premium y clientela de negocios internacional.','Fünf-Sterne-Grandhotel an der V&A Waterfront. Zigarrenlounge mit Blick auf den Tafelberg, Premium-Auswahl, internationales Geschäftspublikum.','维多利亚阿尔弗雷德海滨的五星级宫殿酒店。雪茄厅可望桌山，备有高端精选，客群为国际商务人士。','فندق قصر من فئة الخمس نجوم على واجهة V&A البحرية. صالة سيجار بإطلالة على جبل الطاولة، وتشكيلة فاخرة، وروّاد من أوساط الأعمال الدولية.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1209,'southafrica','Steenberg Golf Estate — Catharina\'s Cigar Lounge','Cape Town — Steenberg Road, Tokai, 7945','Club de Golf','+27 21 713 2222','€€€€','Domaine viticole et golf au pied des montagnes du Cap. Cigar lounge Catharina\'s avec accords cigares-vins du domaine, dans un cadre de fynbos exceptionnel.','steenberghotel.com',1,'2026-03-21 10:30:53','2026-08-01 18:08:34',NULL,NULL,NULL,NULL,NULL,0,'Wine estate and golf course at the foot of the Cape mountains. Catharina\'s cigar lounge pairs cigars with the estate\'s wines, in an exceptional fynbos setting.','Finca vinícola y golf al pie de las montañas del Cabo. El cigar lounge Catharina\'s marida puros con los vinos de la finca, en un entorno de fynbos excepcional.','Weingut und Golfplatz am Fuß der Kapberge. Die Zigarrenlounge Catharina\'s kombiniert Zigarren mit den Weinen des Guts, in einer außergewöhnlichen Fynbos-Landschaft.','开普山脚下的葡萄酒庄园与高尔夫球场。Catharina\'s 雪茄厅提供雪茄与庄园葡萄酒的搭配，置身独特的凡波斯灌丛景致中。','مزرعة نبيذ وملعب غولف عند سفح جبال الكاب. صالة السيجار «كاتارينا» تقدّم مزاوجات بين السيجار ونبيذ المزرعة، في محيط استثنائي من نبات الفينبوس.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1244,'france','Taillevent — Fumoir','Paris 8e — 15 Rue Lamennais','Restaurant Gastronomique','+33 1 44 95 15 01','€€€€','Institution gastronomique parisienne fondée en 1946. Chariot à cigares en fin de repas, sélection Davidoff et Cohiba, cave à vins exceptionnelle.','taillevent.com',1,'2026-03-21 10:30:53','2026-08-01 18:11:44',NULL,NULL,NULL,NULL,NULL,0,'Parisian gastronomic institution founded in 1946. Cigar trolley at the end of the meal, a Davidoff and Cohiba selection, and an exceptional wine cellar.','Institución gastronómica parisina fundada en 1946. Carro de puros al final de la comida, selección Davidoff y Cohiba, y bodega excepcional.','Pariser Gastronomie-Institution, gegründet 1946. Zigarrenwagen zum Abschluss des Menüs, Davidoff- und Cohiba-Auswahl, außergewöhnlicher Weinkeller.','1946 年创立的巴黎美食殿堂。餐后推出雪茄车，备有大卫杜夫与高希霸精选，酒窖出众。','مؤسسة باريسية عريقة في فنّ الطهو تأسّست عام 1946. عربة سيجار في ختام الوجبة، وتشكيلة من دافيدوف وكوهيبا، وقبو نبيذ استثنائي.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1245,'france','Le Grand Véfour — Fumoir','Paris 1er — 17 Rue de Beaujolais, Palais-Royal','Restaurant Gastronomique Historique','+33 1 42 96 56 27','€€€€','Restaurant du Palais-Royal fondé en 1784, 2 étoiles Michelin. Cigares servis en terrasse couverte. Décor Empire classé monument historique.','grand-vefour.com',1,'2026-03-21 10:30:53','2026-08-01 18:19:56',NULL,NULL,NULL,NULL,NULL,0,'Palais-Royal restaurant founded in 1784, with two Michelin stars. Cigars served on the covered terrace. Empire interior listed as a historic monument.','Restaurante del Palais-Royal fundado en 1784, con dos estrellas Michelin. Puros servidos en la terraza cubierta. Decoración Imperio declarada monumento histórico.','Restaurant im Palais-Royal, 1784 gegründet, zwei Michelin-Sterne. Zigarren auf der überdachten Terrasse. Empire-Interieur unter Denkmalschutz.','1784 年创立的皇家宫殿餐厅，米其林二星。有顶露台可享用雪茄。帝政风格装潢已列为历史建筑。','مطعم في البالي رويال تأسّس عام 1784، وحائز على نجمتَي ميشلان. يُقدَّم السيجار في التراس المسقوف. ديكور بطراز الإمبراطورية مصنّف معلمًا تاريخيًا.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1246,'france','Cercle de l\'Union Interalliée — Fumoir','Paris 8e — 33 Faubourg Saint-Honoré','Club Privé','+33 1 42 65 96 00','€€€€','Club privé franco-britannique fondé en 1917. Fumoir au rez-de-chaussée, sélection de havanes, membres du Tout-Paris diplomatique et financier.','union-interalliee.fr',1,'2026-03-21 10:30:53','2026-08-01 18:06:15',NULL,NULL,NULL,NULL,NULL,0,'Franco-British private club founded in 1917. Ground-floor smoking room, a selection of Havanas, and members drawn from diplomatic and financial Paris.','Club privado franco-británico fundado en 1917. Fumador en la planta baja, selección de habanos y socios del París diplomático y financiero.','Franko-britischer Privatclub, gegründet 1917. Rauchsalon im Erdgeschoss, Auswahl an Havannas, Mitglieder aus dem diplomatischen und finanziellen Paris.','1917 年创立的法英私人俱乐部。一楼设吸烟室，备有哈瓦那雪茄精选，会员来自巴黎外交与金融界。','نادٍ خاص فرنسي بريطاني تأسّس عام 1917. صالة تدخين في الطابق الأرضي، وتشكيلة من سيجار هافانا، وأعضاء من أوساط باريس الدبلوماسية والمالية.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1247,'france','Golf National — Club House Cigares','Saint-Quentin-en-Yvelines — 2 Ave du Golf, 78280','Club de Golf','+33 1 30 43 36 00','€€€','Club house du Golf National (Ryder Cup 2018). Espace cigares sur la terrasse panoramique face au green de l\'Albatros.','golf-national.com',1,'2026-03-21 10:30:53','2026-08-01 18:06:15',NULL,NULL,NULL,NULL,NULL,0,'Clubhouse of Le Golf National (2018 Ryder Cup). Cigar area on the panoramic terrace facing the Albatros green.','Casa club del Golf National (Ryder Cup 2018). Espacio de puros en la terraza panorámica frente al green del Albatros.','Clubhaus des Golf National (Ryder Cup 2018). Zigarrenbereich auf der Panoramaterrasse gegenüber dem Albatros-Grün.','法国国家高尔夫球场会所（2018 年莱德杯）。全景露台上的雪茄区，正对信天翁球场果岭。','مبنى نادي «غولف ناسيونال» (كأس رايدر 2018). ركن للسيجار على التراس البانورامي المقابل لغرين ألباتروس.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1248,'france','Paris Yacht Marina — Espace Cigares','Paris 15e — Port de Javel Bas','Marina & Yacht Club','+33 1 45 77 20 20','€€€','Marina privée en plein Paris. Dégustation de cigares sur les pontons, en bord de Seine, face à la Tour Eiffel.','parisyachtmarina.fr',1,'2026-03-21 10:30:53','2026-08-01 18:15:51',NULL,NULL,NULL,NULL,NULL,0,'A private marina in the heart of Paris. Cigar tasting on the pontoons, on the Seine, facing the Eiffel Tower.','Marina privada en pleno París. Degustación de puros en los pontones, a orillas del Sena, frente a la Torre Eiffel.','Private Marina mitten in Paris. Zigarrenverkostung auf den Stegen, an der Seine, mit Blick auf den Eiffelturm.','巴黎市中心的私人码头。可在塞纳河畔的浮桥上品鉴雪茄，正对埃菲尔铁塔。','مرسى خاص في قلب باريس. تذوّق السيجار على الأرصفة العائمة على ضفاف السين، أمام برج إيفل.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1265,'spain','El Bulli Foundation — Cigar Experience','Roses, Costa Brava — Cala Montjoi','Restaurant Gastronomique','+34 972 15 04 57','€€€€','Site mythique de Ferran Adrià reconverti en fondation gastronomique. Dégustations cigares sur la terrasse face à la Méditerranée lors des événements.','elbulli.com',1,'2026-03-21 10:30:53','2026-08-01 18:19:56',NULL,NULL,NULL,NULL,NULL,0,'Ferran Adrià\'s legendary site, now a gastronomic foundation. Cigar tastings on the terrace facing the Mediterranean during events.','El mítico local de Ferran Adrià, reconvertido en fundación gastronómica. Degustaciones de puros en la terraza frente al Mediterráneo durante los eventos.','Der legendäre Ort von Ferran Adrià, heute gastronomische Stiftung. Zigarrenverkostungen bei Veranstaltungen auf der Terrasse zum Mittelmeer.','费兰·阿德里亚的传奇场所，现已转型为美食基金会。举办活动时可在面朝地中海的露台品鉴雪茄。','الموقع الأسطوري لفيران أدريا، تحوّل إلى مؤسسة لفنّ الطهو. جلسات تذوّق للسيجار على التراس المطلّ على المتوسط خلال الفعاليات.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1266,'spain','Real Club de Golf de Pedreña — Cigar Room','Pedreña, Cantabria — 39130','Club de Golf','+34 942 50 00 01','€€€€','Club de golf historique de Seve Ballesteros. Salle de cigares dans le club house avec vue sur la baie de Santander.','RETIRÉ — le club de golf existe, sa salle de cigares n\'est attestée nulle part',0,'2026-03-21 10:30:53','2026-09-04 17:20:49',NULL,NULL,NULL,NULL,NULL,0,'Historic golf club of Seve Ballesteros. Cigar room in the clubhouse overlooking the Bay of Santander.','Club de golf histórico de Seve Ballesteros. Sala de puros en la casa club con vistas a la bahía de Santander.','Historischer Golfclub von Seve Ballesteros. Zigarrenraum im Clubhaus mit Blick auf die Bucht von Santander.','塞维·巴列斯特罗斯的历史悠久高尔夫俱乐部。会所内设雪茄室，可俯瞰桑坦德湾。','نادي غولف تاريخي مرتبط بسيفي بايستيروس. غرفة سيجار في مبنى النادي تطلّ على خليج سانتاندير.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1267,'spain','Puerto Banús Marina — Cigar Lounge','Marbella — Puerto Banús, 29660','Marina & Yacht Club','+34 952 76 95 26','€€€€','La marina la plus glamour d\'Europe. Espace cigares face aux superyachts, fréquenté par l\'élite internationale estivale.','puertobanus.com',1,'2026-03-21 10:30:53','2026-08-01 18:15:50',NULL,NULL,NULL,NULL,NULL,0,'Europe\'s most glamorous marina. Cigar area facing the superyachts, drawing the international summer set.','La marina más glamurosa de Europa. Espacio de puros frente a los superyates, frecuentado por la élite internacional del verano.','Die glamouröseste Marina Europas. Zigarrenbereich mit Blick auf die Superyachten, Treffpunkt der internationalen Sommerelite.','欧洲最耀眼的码头。雪茄区正对超级游艇，夏季国际名流云集。','أكثر مراسي أوروبا بريقًا. ركن للسيجار أمام اليخوت الفاخرة، تقصده النخبة الدولية في الصيف.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1268,'spain','Casino de Madrid — Fumoir Gran Peña','Madrid — Calle de Alcalá 15','Club Privé Historique','+34 91 521 87 00','€€€€','Casino fondé en 1836, l\'un des plus anciens d\'Europe. Fumoir monumental avec plafond à caissons, sélection de havanes et cohiba.','casinomadrid.es',1,'2026-03-21 10:30:53','2026-08-01 18:06:14',NULL,NULL,NULL,NULL,NULL,0,'Casino founded in 1836, one of Europe\'s oldest. Monumental smoking room with a coffered ceiling, and a selection of Havanas and Cohiba.','Casino fundado en 1836, uno de los más antiguos de Europa. Fumador monumental con techo artesonado, selección de habanos y Cohiba.','1836 gegründetes Casino, eines der ältesten Europas. Monumentaler Rauchsalon mit Kassettendecke, Auswahl an Havannas und Cohiba.','1836 年创立的赌场，欧洲最古老者之一。宏伟吸烟室配格状藻井天花板，供应哈瓦那雪茄与高希霸。','كازينو تأسّس عام 1836، من أقدم كازينوهات أوروبا. صالة تدخين فخمة بسقف مقسّم إلى حشوات، وتشكيلة من سيجار هافانا وكوهيبا.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1277,'germany','Brenners Park-Hotel — Cigar Lounge','Baden-Baden — Schillerstrasse 4-6, 76530','Palace Cigar Lounge','+49 7221 9000','€€€€','Palace légendaire de Baden-Baden. Cigar lounge dans les sous-sols voûtés, sélection de 200+ références, clientèle casino et cure thermale.','oetkercollection.com',1,'2026-03-21 10:30:53','2026-08-01 18:19:56',NULL,NULL,NULL,NULL,NULL,0,'Legendary palace hotel in Baden-Baden. Cigar lounge in the vaulted basement, with over 200 references, serving casino guests and spa visitors.','Palacio legendario de Baden-Baden. Cigar lounge en los sótanos abovedados, con más de 200 referencias; clientela de casino y de balneario.','Legendäres Grandhotel in Baden-Baden. Zigarrenlounge in den gewölbten Kellern mit über 200 Referenzen, Publikum aus Casino und Kurbetrieb.','巴登-巴登的传奇宫殿酒店。雪茄厅设于拱顶地下层，藏有 200 余款雪茄，客群来自赌场与温泉疗养。','فندق قصر أسطوري في بادن بادن. صالة سيجار في الأقبية المعقودة بأكثر من 200 صنف، يقصدها روّاد الكازينو والمنتجع الحراري.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1278,'germany','Golf Club München Eichenried — Kaminzimmer','Eichenried — Am Golfplatz 1, 85452','Club de Golf','+49 8123 1006','€€€€','Club de golf hôte du BMW International Open. Kaminzimmer (salon cheminée) avec cigares après le parcours, ambiance feutrée bavaroise.','gc-eichenried.de',1,'2026-03-21 10:30:53','2026-08-01 18:06:14',NULL,NULL,NULL,NULL,NULL,0,'Golf club that hosts the BMW International Open. Kaminzimmer (fireplace lounge) for cigars after the round, in a hushed Bavarian setting.','Club de golf anfitrión del BMW International Open. Kaminzimmer (salón con chimenea) para puros tras la vuelta, en un ambiente bávaro recogido.','Golfclub und Austragungsort der BMW International Open. Kaminzimmer für die Zigarre nach der Runde, in gedämpfter bayerischer Atmosphäre.','宝马国际公开赛的主办高尔夫俱乐部。设 Kaminzimmer（壁炉厅），可在球局后享用雪茄，巴伐利亚式静谧氛围。','نادي غولف يستضيف بطولة BMW الدولية المفتوحة. صالة المدفأة (Kaminzimmer) لتدخين السيجار بعد الجولة، بأجواء بافارية هادئة.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1279,'germany','Hamburg Yacht Club — Hafenterrasse','Hamburg — Van-der-Smissen-Str 9, 22767','Marina & Yacht Club','+49 40 389 0690','€€€€','Club nautique historique de Hambourg fondé en 1855. Terrasse sur l\'Elbe avec sélection de cigares, vue sur les grues de Speicherstadt.','RETIRÉ — aucune trace de cet établissement, et le domaine cité n\'existe pas',0,'2026-03-21 10:30:53','2026-09-04 17:20:49',NULL,NULL,NULL,NULL,NULL,0,'Historic Hamburg yacht club founded in 1855. Terrace on the Elbe with a cigar selection and a view of the Speicherstadt cranes.','Club náutico histórico de Hamburgo fundado en 1855. Terraza sobre el Elba con selección de puros y vistas a las grúas de la Speicherstadt.','Historischer Hamburger Segelclub, gegründet 1855. Terrasse an der Elbe mit Zigarrenauswahl und Blick auf die Kräne der Speicherstadt.','1855 年创立的汉堡历史帆船俱乐部。易北河畔露台备有雪茄精选，可眺望仓库城的吊车。','نادٍ بحري تاريخي في هامبورغ تأسّس عام 1855. تراس على نهر الإلبه مع تشكيلة سيجار وإطلالة على رافعات مدينة المستودعات.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1300,'uk','Boodle\'s Club — Smoking Room','London — 28 St James\'s Street, SW1A 1HJ','Club Privé Historique','+44 20 7930 7166','€€€€','Gentleman\'s club fondé en 1762, l\'un des plus anciens de Londres. Smoking room au 1er étage, sélection Cohiba et Montecristo.','boodles.org',1,'2026-03-21 10:30:53','2026-08-01 18:08:35',NULL,NULL,NULL,NULL,NULL,0,'Gentlemen\'s club founded in 1762, one of London\'s oldest. First-floor smoking room, with a Cohiba and Montecristo selection.','Club de caballeros fundado en 1762, uno de los más antiguos de Londres. Sala de fumadores en la primera planta, con selección Cohiba y Montecristo.','1762 gegründeter Gentlemen\'s Club, einer der ältesten Londons. Rauchsalon im ersten Stock, mit Cohiba- und Montecristo-Auswahl.','1762 年创立的绅士俱乐部，伦敦最古老者之一。二楼设吸烟室，供应高希霸与蒙特克里斯托。','نادي سادة تأسّس عام 1762، من أقدم نوادي لندن. صالة تدخين في الطابق الأول، مع تشكيلة من كوهيبا ومونتكريستو.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1301,'uk','The Savoy — American Bar Cigars','London — Strand, WC2R 0EU','Hotel Cigar Bar Historique','+44 20 7836 4343','€€€€','Bar légendaire du Savoy Hotel (1889). Sélection de cigares cubains proposée avec les cocktails signature. Churchill y fumait ses Romeo y Julieta.','thesavoylondon.com',1,'2026-03-21 10:30:53','2026-08-01 18:06:14',NULL,NULL,NULL,NULL,NULL,0,'Legendary bar at the Savoy Hotel (1889). A selection of Cuban cigars served with the signature cocktails. Churchill smoked his Romeo y Julieta here.','Bar legendario del Savoy Hotel (1889). Selección de puros cubanos servida con los cócteles de la casa. Churchill fumaba aquí sus Romeo y Julieta.','Legendäre Bar im Savoy Hotel (1889). Eine Auswahl kubanischer Zigarren zu den Signature-Cocktails. Churchill rauchte hier seine Romeo y Julieta.','萨伏依酒店（1889 年）的传奇酒吧。古巴雪茄精选，佐以招牌鸡尾酒。丘吉尔曾在此抽他的罗密欧与朱丽叶。','بار أسطوري في فندق سافوي (1889). تشكيلة من السيجار الكوبي تُقدَّم مع كوكتيلات البار المميّزة. هنا كان تشرشل يدخّن سيجاره روميو إي جولييتا.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1302,'uk','Wentworth Club — Cigar Terrace','Virginia Water — Wentworth Drive, GU25 4LS','Club de Golf','+44 1344 842201','€€€€','L\'un des clubs de golf les plus prestigieux d\'Europe. Terrasse cigares avec vue sur le parcours Burma Road. Clientèle CEO et royauté.','wentworthclub.com',1,'2026-03-21 10:30:53','2026-08-01 18:11:44',NULL,NULL,NULL,NULL,NULL,0,'One of Europe\'s most prestigious golf clubs. Cigar terrace overlooking the Burma Road course. A clientele of CEOs and royalty.','Uno de los clubes de golf más prestigiosos de Europa. Terraza de puros con vistas al recorrido Burma Road. Clientela de altos directivos y realeza.','Einer der prestigeträchtigsten Golfclubs Europas. Zigarrenterrasse mit Blick auf den Burma-Road-Kurs. Publikum aus Konzernchefs und Königshäusern.','欧洲最负盛名的高尔夫俱乐部之一。雪茄露台可俯瞰缅甸路球场。客群为企业首脑与王室成员。','من أعرق نوادي الغولف في أوروبا. تراس للسيجار يطلّ على ملعب «بورما رود». يقصده كبار المديرين وأفراد العائلات المالكة.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1303,'uk','Port of Southampton — Ocean Terminal Cigars','Southampton — Town Quay, SO14 2AQ','Airport VIP Lounge','+44 23 8033 4488','€€€€','Terminal des grands paquebots de croisière. Espace cigares dans le salon VIP d\'embarquement — Queen Mary 2, Symphony of the Seas.','abports.co.uk',1,'2026-03-21 10:30:53','2026-08-01 18:19:56',NULL,NULL,NULL,NULL,NULL,0,'Terminal for the great cruise liners. Cigar area in the VIP boarding lounge — Queen Mary 2, Symphony of the Seas.','Terminal de los grandes cruceros. Espacio de puros en el salón VIP de embarque: Queen Mary 2, Symphony of the Seas.','Terminal der großen Kreuzfahrtschiffe. Zigarrenbereich in der VIP-Boarding-Lounge — Queen Mary 2, Symphony of the Seas.','大型邮轮码头。贵宾登船厅设雪茄区——玛丽皇后二号、海洋交响号。','محطة السفن السياحية الكبرى. ركن للسيجار في صالة الصعود لكبار الزوّار — كوين ماري 2، وسيمفوني أوف ذا سيز.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1367,'italy','Caffè Florian — Terrasse Cigares','Venezia — Piazza San Marco 57','Café Historique','+39 041 520 5641','€€€€','Café fondé en 1720, le plus ancien d\'Europe encore en activité. Dégustation de cigares en terrasse sous les arcades de la Piazza San Marco.','caffeflorian.com',1,'2026-03-21 10:30:53','2026-08-01 18:06:14',NULL,NULL,NULL,NULL,NULL,0,'Café founded in 1720, the oldest still operating in Europe. Cigar tasting on the terrace under the arcades of Piazza San Marco.','Café fundado en 1720, el más antiguo de Europa aún en activo. Degustación de puros en la terraza bajo los soportales de la Piazza San Marco.','1720 gegründetes Café, das älteste noch bestehende Europas. Zigarrenverkostung auf der Terrasse unter den Arkaden der Piazza San Marco.','1720 年创立的咖啡馆，欧洲现存最古老的一家。可在圣马可广场拱廊下的露台品鉴雪茄。','مقهى تأسّس عام 1720، أقدم مقهى ما زال يعمل في أوروبا. تذوّق السيجار في التراس تحت أروقة ساحة سان ماركو.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1368,'italy','Circolo dell\'Unione — Sala Fumatori','Torino — Via Carlo Alberto 45','Club Privé Historique','+39 011 546 999','€€€€','Le club le plus exclusif de Turin, fondé en 1840. Sala fumatori avec fresques d\'époque, collection de Toscani et havanes.','circolodellunione.it',1,'2026-03-21 10:30:53','2026-08-01 18:15:50',NULL,NULL,NULL,NULL,NULL,0,'Turin\'s most exclusive club, founded in 1840. Sala fumatori with period frescoes and a collection of Toscani and Havanas.','El club más exclusivo de Turín, fundado en 1840. Sala fumatori con frescos de época y colección de Toscani y habanos.','Der exklusivste Club Turins, gegründet 1840. Sala fumatori mit zeitgenössischen Fresken und einer Sammlung von Toscani und Havannas.','都灵最尊贵的会所，创立于 1840 年。Sala fumatori 保留时代湿壁画，藏有托斯卡尼雪茄与哈瓦那雪茄。','أعرق نادٍ في تورينو، تأسّس عام 1840. صالة التدخين بجداريات من العصر، ومجموعة من سيجار توسكاني وهافانا.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1369,'italy','Olivos Golf Club — Cigar Terrace','Milano — Via Linate al Campo 20, Segrate','Club de Golf','+39 02 703 9019','€€€€','Golf club de la haute bourgeoisie milanaise. Terrasse avec humidor partagé, cigares servis après le parcours.','RETIRÉ — nom d\'un club de Buenos Aires posé sur une adresse de Milan',0,'2026-03-21 10:30:53','2026-09-04 09:03:46',NULL,NULL,NULL,NULL,NULL,0,'Golf club of Milan\'s upper bourgeoisie. Terrace with a shared humidor, cigars served after the round.','Club de golf de la alta burguesía milanesa. Terraza con humidor compartido y puros servidos tras la vuelta.','Golfclub des Mailänder Großbürgertums. Terrasse mit gemeinschaftlichem Humidor, Zigarren nach der Runde.','米兰上层社会的高尔夫俱乐部。露台设共用雪茄柜，球局结束后供应雪茄。','نادي غولف لأوساط ميلانو الراقية. تراس بمرطّبة سيجار مشتركة، ويُقدَّم السيجار بعد الجولة.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1370,'italy','Porto Cervo Marina — La Piazzetta Cigars','Porto Cervo, Costa Smeralda — 07021','Marina & Yacht Club','+39 0789 931411','€€€€','La marina la plus exclusive de Méditerranée, créée par l\'Aga Khan. Cigares en soirée face aux super-yachts.','RETIRÉ — aucune trace de cet établissement, et le domaine cité n\'existe pas',0,'2026-03-21 10:30:53','2026-09-04 17:20:49',NULL,NULL,NULL,NULL,NULL,0,'The Mediterranean\'s most exclusive marina, created by the Aga Khan. Evening cigars facing the superyachts.','La marina más exclusiva del Mediterráneo, creada por el Aga Khan. Puros al atardecer frente a los superyates.','Die exklusivste Marina des Mittelmeers, geschaffen vom Aga Khan. Abendliche Zigarren mit Blick auf die Superyachten.','地中海最尊贵的码头，由阿迦汗创建。夜晚可面朝超级游艇享用雪茄。','أرقى مرسى في البحر المتوسط، أنشأه الأغا خان. سيجار في المساء أمام اليخوت الفاخرة.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1390,'uae','Burj Al Arab — Skyview Bar Cigars','Dubai — Jumeirah Beach Road, Dubai','Palace Cigar Bar','+971 4 301 7777','€€€€','Hôtel emblématique de Dubaï, sur son île artificielle. Skyview Bar au 27e étage : sélection de habanos, vue à 360° sur la ville et la mer.','jumeirah.com',1,'2026-03-21 10:30:53','2026-08-26 10:38:34',NULL,NULL,NULL,NULL,NULL,0,'Dubai\'s landmark hotel, on its own artificial island. The Skyview Bar on the 27th floor: a selection of Habanos and 360° views over the city and the sea.','Hotel emblemático de Dubái, sobre su isla artificial. Skyview Bar en la planta 27: selección de habanos y vistas de 360° a la ciudad y al mar.','Dubais Wahrzeichen-Hotel auf seiner künstlichen Insel. Die Skyview Bar im 27. Stock: eine Auswahl an Habanos und 360°-Blick über Stadt und Meer.','迪拜的地标酒店，建于人工岛上。27 层 Skyview 酒吧备有哈瓦那雪茄精选，可 360 度俯瞰城市与海景。','فندق دبي الأيقوني القائم على جزيرته الاصطناعية. بار «سكاي فيو» في الطابق السابع والعشرين: تشكيلة من سيجار هابانوس وإطلالة بزاوية 360 درجة على المدينة والبحر.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1391,'uae','Dubai Creek Golf & Yacht Club — Cigar Terrace','Dubai — Al Garhoud, Dubai','Club de Golf','+971 4 295 6000','€€€€','Club de golf iconique sur le Creek de Dubaï. Terrasse cigares au coucher du soleil face aux dhows traditionnels et au skyline de Deira.','RETIRÉ — le lieu existe, le salon que la fiche nomme n\'y figure pas',0,'2026-03-21 10:30:53','2026-09-04 17:37:41',NULL,NULL,NULL,NULL,NULL,0,'Iconic golf club on Dubai Creek. Cigar terrace at sunset facing the traditional dhows and the Deira skyline.','Club de golf icónico en el Creek de Dubái. Terraza de puros al atardecer frente a los dhows tradicionales y el skyline de Deira.','Ikonischer Golfclub am Dubai Creek. Zigarrenterrasse bei Sonnenuntergang mit Blick auf traditionelle Dhaus und die Skyline von Deira.','迪拜河畔的标志性高尔夫俱乐部。日落时分的雪茄露台，正对传统单桅帆船与德拉天际线。','نادي غولف أيقوني على خور دبي. تراس للسيجار عند الغروب يطلّ على مراكب الداو التقليدية وأفق ديرة.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1392,'uae','One&Only Royal Mirage — Cigar Lounge','Dubai — Al Sufouh Road, Dubai Marina','Palace Cigar Lounge',NULL,'€€€€','Resort palatial de style arabo-andalou. Cigar lounge dans les jardins avec fontaines, sélection de 200 références, ambiance 1001 nuits.','oneandonlyresorts.com',1,'2026-03-21 10:30:53','2026-09-03 12:11:42',NULL,NULL,NULL,NULL,NULL,0,'Palatial resort in Arab-Andalusian style. Cigar lounge in the fountain gardens, with 200 references and an Arabian Nights atmosphere.','Resort palaciego de estilo árabe-andalusí. Cigar lounge en los jardines con fuentes, 200 referencias y ambiente de las mil y una noches.','Palastartiges Resort im arabisch-andalusischen Stil. Zigarrenlounge in den Brunnengärten, 200 Referenzen, Atmosphäre aus Tausendundeiner Nacht.','阿拉伯-安达卢斯风格的宫殿式度假村。雪茄厅设于喷泉花园中，藏有 200 款雪茄，一千零一夜般的氛围。','منتجع قصري بالطراز العربي الأندلسي. صالة سيجار في حدائق النافورات، بمائتَي صنف وأجواء من ألف ليلة وليلة.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1393,'uae','Abu Dhabi EDITION — Rooftop Cigar Bar','Abu Dhabi — Al Bateen Marina','Rooftop Bar','+971 2 208 0000','€€€€','Hôtel design d\'Al Bateen Marina. Rooftop bar avec espace fumeurs autorisé, cigares nicaraguayens et dominicains, vue sur la marina et la mer d\'Arabie.','marriott.com',1,'2026-03-21 10:30:53','2026-08-01 18:11:43',NULL,NULL,NULL,NULL,NULL,0,'Design hotel at Al Bateen Marina. Rooftop bar with a designated smoking area, Nicaraguan and Dominican cigars, and views over the marina and the Arabian Sea.','Hotel de diseño en Al Bateen Marina. Bar en la azotea con zona de fumadores autorizada, puros nicaragüenses y dominicanos, y vistas a la marina y al mar Arábigo.','Designhotel an der Al Bateen Marina. Rooftop-Bar mit ausgewiesenem Raucherbereich, nicaraguanischen und dominikanischen Zigarren sowie Blick auf Marina und Arabisches Meer.','位于阿尔巴廷码头的设计酒店。顶层酒吧设有允许吸烟的区域，供应尼加拉瓜与多米尼加雪茄，可眺望码头与阿拉伯海。','فندق تصميمي في مرسى البطين. بار على السطح بمنطقة تدخين مخصّصة، وسيجار نيكاراغوي ودومينيكي، وإطلالة على المرسى وبحر العرب.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1426,'japan','Sukiyabashi Jiro — Fumoir','Tokyo — 2-15 Nagatacho, Chiyoda-ku (Capitol Hotel)','Restaurant Gastronomique','+81 3 3503 7670','€€€€','Référence gastronomique mondiale, 3 étoiles Michelin. Cigares proposés en fin de repas dans le salon privé du Capitol Hotel.','sushi-jiro.jp',1,'2026-03-21 10:30:53','2026-08-01 18:19:56',NULL,NULL,NULL,NULL,NULL,0,'A global gastronomic reference with three Michelin stars. Cigars offered at the end of the meal in the Capitol Hotel\'s private room.','Referencia gastronómica mundial con tres estrellas Michelin. Puros al final de la comida en el salón privado del Capitol Hotel.','Weltweite gastronomische Referenz mit drei Michelin-Sternen. Zigarren zum Abschluss des Menüs im Privatsalon des Capitol Hotel.','享誉全球的米其林三星美食殿堂。可在 Capitol Hotel 的私人厅于餐后享用雪茄。','مرجع عالمي في فنّ الطهو حائز على ثلاث نجوم ميشلان. يُقدَّم السيجار في ختام الوجبة بالصالة الخاصة في فندق كابيتول.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1427,'japan','Tokyo American Club — Cigar Bar','Tokyo — 2-1-2 Azabudai, Minato-ku','Members Club','+81 3 4588 0366','€€€€','Club privé américain de Tokyo fondé en 1928. Cigar bar au 3e étage avec sélection de 100+ références, membres expatriés et élite japonaise.','tokyoamericanclub.org',1,'2026-03-21 10:30:53','2026-08-01 18:06:15',NULL,NULL,NULL,NULL,NULL,0,'American private club in Tokyo, founded in 1928. Third-floor cigar bar with over 100 references, drawing expatriate members and the Japanese elite.','Club privado estadounidense de Tokio, fundado en 1928. Cigar bar en la 3.ª planta con más de 100 referencias; socios expatriados y élite japonesa.','Amerikanischer Privatclub in Tokio, gegründet 1928. Zigarrenbar im 3. Stock mit über 100 Referenzen, Mitglieder aus Expat-Kreisen und der japanischen Elite.','1928 年创立的东京美国私人俱乐部。三楼雪茄吧藏有 100 余款雪茄，会员为外派人士与日本精英。','نادٍ أمريكي خاص في طوكيو تأسّس عام 1928. بار سيجار في الطابق الثالث بأكثر من 100 صنف، يرتاده الأعضاء المغتربون والنخبة اليابانية.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1428,'japan','Abeno Harukas — Sky Lounge Cigars','Osaka — 1-1-43 Abenosuji, Abeno-ku, 545-6060','Rooftop Bar','+81 6 6621 0300','€€€€','Plus haute tour d\'Osaka (300m). Sky lounge au 60e étage avec espace fumeurs autorisé, vue sur le Kansai, cigares dominicains et nicaraguayens.','RETIRÉ — le lieu existe, le salon que la fiche nomme n\'y figure pas',0,'2026-03-21 10:30:53','2026-09-04 17:37:41',NULL,NULL,NULL,NULL,NULL,0,'Osaka\'s tallest tower (300 m). Sky lounge on the 60th floor with a designated smoking area, views over Kansai, and Dominican and Nicaraguan cigars.','La torre más alta de Osaka (300 m). Sky lounge en la planta 60 con zona de fumadores autorizada, vistas a Kansai y puros dominicanos y nicaragüenses.','Der höchste Turm Osakas (300 m). Sky Lounge im 60. Stock mit ausgewiesenem Raucherbereich, Blick über Kansai und dominikanischen sowie nicaraguanischen Zigarren.','大阪最高塔（300 米）。60 层空中休息厅设有允许吸烟的区域，可俯瞰关西，供应多米尼加与尼加拉瓜雪茄。','أعلى برج في أوساكا (300 متر). صالة سماوية في الطابق الستين بمنطقة تدخين مخصّصة، وإطلالة على كانساي، وسيجار دومينيكي ونيكاراغوي.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1429,'japan','Kansai Golf Club — Cigar Terrace','Osaka — 201 Shijimi, Ibaraki-shi, 567-0068','Club de Golf','+81 72 643 1111','€€€€','Golf club historique du Kansai, fondé en 1920. Terrasse cigares après le parcours, tradition de dégustation de havanes avec whisky japonais.','kgc.jp',1,'2026-03-21 10:30:53','2026-08-01 18:11:43',NULL,NULL,NULL,NULL,NULL,0,'Historic Kansai golf club, founded in 1920. Cigar terrace after the round, with a tradition of tasting Havanas alongside Japanese whisky.','Club de golf histórico de Kansai, fundado en 1920. Terraza de puros tras la vuelta, con la tradición de degustar habanos con whisky japonés.','Historischer Golfclub in Kansai, gegründet 1920. Zigarrenterrasse nach der Runde, mit der Tradition, Havannas zu japanischem Whisky zu genießen.','1920 年创立的关西老牌高尔夫俱乐部。球局后可上雪茄露台，素有以日本威士忌佐哈瓦那雪茄的传统。','نادي غولف عريق في كانساي تأسّس عام 1920. تراس للسيجار بعد الجولة، وتقليد راسخ في تذوّق سيجار هافانا مع الويسكي الياباني.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1448,'hongkong','Hong Kong Club — Smoking Room','Hong Kong — 1 Jackson Road, Central','Club Privé Historique',NULL,'€€€€','Le club le plus exclusif de HK fondé en 1846. Smoking room avec vue sur le Victoria Harbour, collection de havanes vieillissants, membres tycoons et banquiers.','hkclub.com',1,'2026-03-21 10:30:53','2026-09-03 12:11:42',NULL,NULL,NULL,NULL,NULL,0,'Hong Kong\'s most exclusive club, founded in 1846. Smoking room overlooking Victoria Harbour, a collection of ageing Havanas, and members drawn from tycoons and bankers.','El club más exclusivo de Hong Kong, fundado en 1846. Sala de fumadores con vistas al puerto Victoria, colección de habanos en envejecimiento y socios magnates y banqueros.','Der exklusivste Club Hongkongs, gegründet 1846. Rauchsalon mit Blick auf den Victoria Harbour, eine Sammlung reifender Havannas, Mitglieder aus Tycoon- und Bankierskreisen.','香港最尊贵的会所，创立于 1846 年。吸烟室可俯瞰维多利亚港，藏有陈化中的哈瓦那雪茄，会员为巨贾与银行家。','أعرق نادٍ خاص في هونغ كونغ، تأسّس عام 1846. صالة تدخين تطلّ على ميناء فيكتوريا، ومجموعة من سيجار هافانا في مرحلة التعتيق، وأعضاء من كبار رجال الأعمال والمصرفيين.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1449,'macau','Restaurant Robuchon au Dôme — Cigars','Macau — Grand Lisboa, Avenida de Lisboa','Restaurant Gastronomique','+853 8803 7878','€€€€','Restaurant 3 étoiles Michelin au sommet du Grand Lisboa de Macao. Dégustation de cigares sur la terrasse panoramique après le repas.','grandlisboa.com',1,'2026-03-21 10:30:53','2026-09-03 12:11:42',NULL,NULL,NULL,NULL,NULL,0,'Three-Michelin-star restaurant at the top of Macau\'s Grand Lisboa. Cigar tasting on the panoramic terrace after the meal.','Restaurante con tres estrellas Michelin en lo alto del Grand Lisboa de Macao. Degustación de puros en la terraza panorámica tras la comida.','Drei-Sterne-Restaurant an der Spitze des Grand Lisboa in Macau. Zigarrenverkostung auf der Panoramaterrasse nach dem Essen.','澳门新葡京顶层的米其林三星餐厅。餐后可在全景露台品鉴雪茄。','مطعم حائز على ثلاث نجوم ميشلان في أعلى فندق غراند ليسبوا بماكاو. تذوّق السيجار على التراس البانورامي بعد الوجبة.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1450,'hongkong','Aberdeen Marina Club — Cigar Deck','Hong Kong — 8 Shum Wan Road, Aberdeen','Marina & Yacht Club','+852 2555 8321','€€€€','Marina club premium d\'Aberdeen, havre des grandes fortunes hongkongaises. Cigar deck face aux jonques et aux superyachts.','aberdeenmarinaclub.com',1,'2026-03-21 10:30:53','2026-08-01 18:15:51',NULL,NULL,NULL,NULL,NULL,0,'Premium marina club in Aberdeen, a haven for Hong Kong\'s great fortunes. Cigar deck facing the junks and the superyachts.','Club náutico premium de Aberdeen, refugio de las grandes fortunas hongkonesas. Cubierta de puros frente a los juncos y los superyates.','Premium-Marinaclub in Aberdeen, Refugium der großen Hongkonger Vermögen. Zigarrendeck mit Blick auf Dschunken und Superyachten.','香港仔的高端码头会所，香港巨富的栖身之所。雪茄甲板正对帆船与超级游艇。','نادي مرسى فاخر في أبردين، ملاذ كبرى ثروات هونغ كونغ. سطح للسيجار يطلّ على المراكب الشراعية واليخوت الفاخرة.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1463,'singapore','Raffles Hotel — Long Bar Cigars','Singapore — 1 Beach Road, 189673','Hotel Cigar Bar Historique','+65 6337 1886','€€€€','Hôtel mythique de 1887 où fut inventé le Singapore Sling. Long Bar avec sélection de cigares cubains et dominicains, terrasse coloniale.','raffles.com',1,'2026-03-21 10:30:53','2026-08-01 18:11:43',NULL,NULL,NULL,NULL,NULL,0,'Legendary 1887 hotel where the Singapore Sling was invented. Long Bar with a selection of Cuban and Dominican cigars, and a colonial terrace.','Hotel mítico de 1887 donde se inventó el Singapore Sling. Long Bar con selección de puros cubanos y dominicanos, y terraza colonial.','Mythisches Hotel von 1887, in dem der Singapore Sling erfunden wurde. Long Bar mit kubanischen und dominikanischen Zigarren und einer Kolonialterrasse.','1887 年落成的传奇酒店，新加坡司令鸡尾酒诞生于此。Long Bar 备有古巴与多米尼加雪茄精选，并设殖民风格露台。','فندق أسطوري يعود إلى 1887، حيث ابتُكر كوكتيل «سنغافورة سلينغ». بار «لونغ بار» بتشكيلة من السيجار الكوبي والدومينيكي، وتراس بطراز استعماري.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1464,'singapore','One°15 Marina Club — Cigar Lounge','Singapore — 11 Cove Drive, Sentosa, 098497','Marina & Yacht Club','+65 6305 6988','€€€€','Marina club 5 étoiles de Sentosa Island. Cigar lounge privé avec humidor dédié, vue sur 300 berths de yachts de luxe.','one15marina.com',1,'2026-03-21 10:30:53','2026-08-01 18:15:51',NULL,NULL,NULL,NULL,NULL,0,'Five-star marina club on Sentosa Island. Private cigar lounge with a dedicated humidor and a view over 300 luxury yacht berths.','Club náutico de cinco estrellas en Sentosa Island. Cigar lounge privado con humidor propio y vistas a 300 amarres de yates de lujo.','Fünf-Sterne-Marinaclub auf Sentosa Island. Private Zigarrenlounge mit eigenem Humidor und Blick auf 300 Luxusyacht-Liegeplätze.','圣淘沙岛的五星级码头会所。私人雪茄厅配专属雪茄柜，可俯瞰 300 个豪华游艇泊位。','نادي مرسى من فئة الخمس نجوم في جزيرة سنتوسا. صالة سيجار خاصة بمرطّبة مخصّصة، وإطلالة على 300 مرسى لليخوت الفاخرة.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1465,'singapore','Tippling Club — Cigar Pairing Menu','Singapore — 38 Tanjong Pagar Road, 088461','Restaurant Gastronomique','+65 6475 2217','€€€€','Restaurant étoilé Michelin spécialisé dans les accords mets-cocktails. Propose un menu de dégustation avec accord cigares nicaraguayens.','tipplingclub.com',1,'2026-03-21 10:30:53','2026-08-01 18:19:56',NULL,NULL,NULL,NULL,NULL,0,'Michelin-starred restaurant specialising in food-and-cocktail pairings. Offers a tasting menu paired with Nicaraguan cigars.','Restaurante con estrella Michelin especializado en maridajes de platos y cócteles. Ofrece un menú degustación maridado con puros nicaragüenses.','Sterne-Restaurant mit Schwerpunkt auf Speisen-Cocktail-Pairings. Bietet ein Degustationsmenü mit nicaraguanischen Zigarren.','专攻菜品与鸡尾酒搭配的米其林星级餐厅。提供搭配尼加拉瓜雪茄的品鉴菜单。','مطعم حائز على نجمة ميشلان متخصّص في مزاوجة الأطباق مع الكوكتيلات. يقدّم قائمة تذوّق مصحوبة بسيجار نيكاراغوي.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1466,'singapore','Sentosa Golf Club — Members Cigar Bar','Singapore — 27 Bukit Manis Road, Sentosa, 099892','Club de Golf','+65 6275 0022','€€€€','Le seul club de golf à Sentosa, hôte du SMBC Singapore Open. Members bar avec espace cigares, vue sur le port de Singapour.','sentosagolf.com',1,'2026-03-21 10:30:53','2026-08-01 18:15:50',NULL,NULL,NULL,NULL,NULL,0,'Sentosa\'s only golf club, host of the SMBC Singapore Open. Members\' bar with a cigar area and a view of Singapore\'s harbour.','El único club de golf de Sentosa, anfitrión del SMBC Singapore Open. Bar de socios con espacio de puros y vistas al puerto de Singapur.','Der einzige Golfclub auf Sentosa, Austragungsort der SMBC Singapore Open. Members\' Bar mit Zigarrenbereich und Blick auf den Hafen von Singapur.','圣淘沙唯一的高尔夫俱乐部，SMBC 新加坡公开赛主办地。会员酒吧设雪茄区，可眺望新加坡港。','نادي الغولف الوحيد في سنتوسا، ومستضيف بطولة SMBC سنغافورة المفتوحة. بار الأعضاء بركن للسيجار وإطلالة على ميناء سنغافورة.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1504,'usa','21 Club — Cigar Room','New York — 21 West 52nd Street, Midtown','Restaurant Gastronomique Historique','+1 212 582 7200','€€€€','Institution new-yorkaise fondée en 1930 (ex-speakeasy). Cigar room au sous-sol, collection de havanes d\'exception, fréquenté par présidents et célébrités.','21club.com',1,'2026-03-21 10:30:53','2026-08-01 18:11:44',NULL,NULL,NULL,NULL,NULL,0,'New York institution founded in 1930, a former speakeasy. Basement cigar room with an exceptional collection of Havanas, frequented by presidents and celebrities.','Institución neoyorquina fundada en 1930 (antiguo speakeasy). Cigar room en el sótano, colección excepcional de habanos, frecuentada por presidentes y celebridades.','New Yorker Institution von 1930, ein ehemaliger Speakeasy. Zigarrenraum im Untergeschoss mit außergewöhnlicher Havanna-Sammlung, besucht von Präsidenten und Prominenten.','1930 年创立的纽约名所，前身为禁酒时期地下酒吧。地下层设雪茄室，藏有出众的哈瓦那雪茄，总统与名流常客。','مؤسسة نيويوركية تأسّست عام 1930 (كانت حانة سرّية). غرفة سيجار في الطابق السفلي بمجموعة استثنائية من سيجار هافانا، يرتادها رؤساء ومشاهير.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1505,'usa','Burning Tree Country Club — Cigar Bar','Bethesda, MD — 10901 Bradley Blvd, 20817','Club de Golf','+1 301 365 0080','€€€€','Le club de golf le plus exclusif de Washington DC — pas de femmes membres, pas de téléphones. Cigar bar où se retrouvent sénateurs et lobbyistes.','RETIRÉ — le lieu existe, le salon que la fiche nomme n\'y figure pas',0,'2026-03-21 10:30:53','2026-09-04 17:37:41',NULL,NULL,NULL,NULL,NULL,0,'Washington DC\'s most exclusive golf club — no women members, no phones. A cigar bar where senators and lobbyists meet.','El club de golf más exclusivo de Washington D.C.: sin socias, sin teléfonos. Un cigar bar donde se reúnen senadores y lobistas.','Der exklusivste Golfclub Washingtons — keine weiblichen Mitglieder, keine Telefone. Eine Zigarrenbar, in der Senatoren und Lobbyisten zusammenkommen.','华盛顿特区最排外的高尔夫俱乐部——不接纳女性会员，禁用手机。参议员与游说人士常聚于此雪茄吧。','أكثر نوادي الغولف انغلاقًا في واشنطن العاصمة — لا عضوات ولا هواتف. بار سيجار يلتقي فيه أعضاء مجلس الشيوخ وجماعات الضغط.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1506,'usa','Breakers Palm Beach — Cigar & Spirits Lounge','Palm Beach, FL — 1 South County Road','Palace Cigar Lounge','+1 561 655 6611','€€€€','Palace historique de Palm Beach ouvert en 1896. Cigar & Spirits Lounge avec sélection premium, clientèle vieille richesse américaine.','thebreakers.com',1,'2026-03-21 10:30:53','2026-08-01 18:19:56',NULL,NULL,NULL,NULL,NULL,0,'Historic Palm Beach palace hotel, opened in 1896. Cigar & Spirits Lounge with a premium selection, serving American old money.','Palacio histórico de Palm Beach, inaugurado en 1896. Cigar & Spirits Lounge con selección premium y clientela de la vieja fortuna estadounidense.','Historisches Grandhotel in Palm Beach, eröffnet 1896. Cigar & Spirits Lounge mit Premium-Auswahl, Publikum aus amerikanischem Altgeld.','1896 年开业的棕榈滩历史宫殿酒店。Cigar & Spirits Lounge 备有高端精选，客群为美国老牌富裕阶层。','فندق قصر تاريخي في بالم بيتش افتُتح عام 1896. صالة «سيجار آند سبيريتس» بتشكيلة فاخرة، يقصدها أصحاب الثروات الأمريكية العريقة.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1507,'usa','Augusta National Golf Club — Members Lounge','Augusta, GA — 2604 Washington Road, 30904','Members Club','+1 706 667 6000','€€€€','Club de golf d\'Augusta, hôte du Masters. Salon des membres où l\'on fume traditionnellement après le parcours — accès sur invitation uniquement.','masters.com',1,'2026-03-21 10:30:53','2026-08-26 10:38:34',NULL,NULL,NULL,NULL,5.0,1,'The Augusta golf club, host of the Masters. A members\' lounge where a cigar after the round is tradition — access by invitation only.','Club de golf de Augusta, sede del Masters. Salón de socios donde el puro tras la vuelta es tradición; acceso solo por invitación.','Der Golfclub von Augusta, Austragungsort des Masters. Members\' Lounge, in der die Zigarre nach der Runde Tradition hat — Zutritt nur auf Einladung.','奥古斯塔高尔夫俱乐部，美国大师赛主办场地。会员厅中，球局后点一支雪茄是传统——仅限受邀者进入。','نادي أوغستا للغولف، مضيف بطولة الماسترز. صالة الأعضاء حيث تدخين السيجار بعد الجولة تقليد راسخ — الدخول بدعوة فقط.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1508,'usa','Cigar City Brewing — Cigar Bar','Tampa, FL — 3924 West Spruce Street','Cigar Bar & Brasserie','+1 813 348 6363','€€€','Brasserie artisanale qui associe ses bières à des cigares locaux. Terrasse, cave humidifiée où l\'on entre, accords bières-cigares honduriens et nicaraguayens.','cigarcitybrewing.com',1,'2026-03-21 10:30:53','2026-08-26 17:26:06',NULL,NULL,NULL,NULL,NULL,0,'A craft brewery pairing its own beers with local cigars. Terrace, walk-in humidified cellar, and beer pairings for Honduran and Nicaraguan cigars.','Cervecería artesanal que combina sus cervezas con puros locales. Terraza, bodega humidificada por la que se entra y maridajes de cerveza con puros hondureños y nicaragüenses.','Craft-Brauerei, die ihre Biere mit lokalen Zigarren verbindet. Terrasse, begehbarer Humidorraum und Bier-Zigarren-Pairings aus Honduras und Nicaragua.','精酿酒厂，将自酿啤酒与本地雪茄相搭配。设露台与可步入的恒湿雪茄库，提供啤酒与洪都拉斯、尼加拉瓜雪茄的搭配。','مصنع جعة حرفي يجمع بين بيرته والسيجار المحلي. تراس، ومخزن ترطيب يُدخل إليه، ومزاوجات بين البيرة والسيجار الهندوراسي والنيكاراغوي.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1509,'usa','Pebble Beach Golf Links — Tap Room Cigars','Pebble Beach, CA — 1700 17-Mile Drive','Club de Golf','+1 831 574 5609','€€€€','Parcours de bord de mer face à l\'océan Pacifique. Tap Room et sa sélection de cigares, dégustation au coucher du soleil sur le green du 18.','pebblebeach.com',1,'2026-03-21 10:30:53','2026-08-26 10:38:34',NULL,NULL,NULL,NULL,NULL,0,'A links course on the Pacific shore. The Tap Room and its cigar selection, with sunset tastings on the 18th green.','Campo costero frente al océano Pacífico. El Tap Room y su selección de puros, con degustación al atardecer en el green del 18.','Küstenplatz direkt am Pazifik. Der Tap Room mit seiner Zigarrenauswahl und Verkostung bei Sonnenuntergang auf dem 18. Grün.','正对太平洋的海滨球场。Tap Room 备有雪茄精选，可在第 18 洞果岭上迎着落日品鉴。','ملعب ساحلي يطلّ على المحيط الهادئ. صالة «تاب روم» بتشكيلتها من السيجار، وتذوّق عند الغروب على غرين الحفرة الثامنة عشرة.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1563,'cuba','Real Fábrica de Tabacos Partagás — Showroom','La Havane — Calle Industria 520, Centro Habana','Manufacture Historique','+53 7 862 4604','€€€','Manufacture fondée en 1845, la plus ancienne de Cuba encore en activité. Showroom de dégustation au 3e étage, visite guidée et vente directe manufacture.','habanos.com',1,'2026-03-21 10:30:53','2026-08-01 18:15:51',NULL,NULL,NULL,NULL,NULL,0,'Factory founded in 1845, the oldest still operating in Cuba. Third-floor tasting showroom, guided tour and direct factory sales.','Fábrica fundada en 1845, la más antigua de Cuba aún en activo. Showroom de degustación en la tercera planta, visita guiada y venta directa de fábrica.','1845 gegründete Manufaktur, die älteste noch arbeitende Kubas. Verkostungsshowroom im dritten Stock, Führung und Direktverkauf ab Werk.','1845 年创建的制造厂，古巴现存最古老者。三楼设品鉴陈列室，提供导览参观与工厂直销。','مصنع تأسّس عام 1845، أقدم مصنع ما زال يعمل في كوبا. صالة عرض للتذوّق في الطابق الثالث، وجولة مرشدة، وبيع مباشر من المصنع.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1564,'cuba','Hotel Nacional de Cuba — Bar Vista al Golfo','La Havane — Calle O y 21, Vedado','Hotel Cigar Bar Historique','+53 7 836 3564','€€€','Monument historique de 1930, espace de rencontre des grandes figures du XXe siècle. Bar avec vue sur le Golfe du Mexique, humidor de référence à La Havane.','hotelnacionaldecuba.com',1,'2026-03-21 10:30:53','2026-08-01 18:19:55',NULL,NULL,NULL,NULL,NULL,0,'A historic 1930 landmark, meeting place of the great figures of the twentieth century. Bar overlooking the Gulf of Mexico, and a benchmark humidor in Havana.','Monumento histórico de 1930, punto de encuentro de las grandes figuras del siglo XX. Bar con vistas al golfo de México y humidor de referencia en La Habana.','Historisches Baudenkmal von 1930, Treffpunkt der großen Persönlichkeiten des 20. Jahrhunderts. Bar mit Blick auf den Golf von Mexiko und maßgeblicher Humidor in Havanna.','1930 年落成的历史建筑，20 世纪诸多名流的聚会之所。酒吧可眺望墨西哥湾，雪茄柜为哈瓦那标杆。','معلم تاريخي يعود إلى 1930، وملتقى كبار شخصيات القرن العشرين. بار يطلّ على خليج المكسيك، ومرطّبة سيجار مرجعية في هافانا.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1565,'cuba','La Bodeguita del Medio — Terrasse Cigares','La Havane — Empedrado 207, Habana Vieja','Bar Historique','+53 7 867 1374','€€€','Bar mythique de La Havane fréquenté par Hemingway. Terrasse avec dégustation de cigares artisanaux, Mojitos et musique live son cubain.','labodeguita.com',1,'2026-03-21 10:30:53','2026-08-01 18:06:14',NULL,NULL,NULL,NULL,NULL,0,'Legendary Havana bar frequented by Hemingway. Terrace for tasting hand-rolled cigars, with mojitos and live Cuban son.','Bar mítico de La Habana frecuentado por Hemingway. Terraza con degustación de puros artesanales, mojitos y son cubano en vivo.','Mythische Bar in Havanna, Stammlokal Hemingways. Terrasse mit Verkostung handgerollter Zigarren, Mojitos und Live-Son-Cubano.','海明威常去的哈瓦那传奇酒吧。露台可品鉴手工雪茄，佐以莫希托与古巴颂乐现场演奏。','بار هافانا الأسطوري الذي كان يرتاده همنغواي. تراس لتذوّق السيجار المصنوع يدويًا، مع الموخيتو وموسيقى السون الكوبية الحيّة.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1566,'cuba','Festival del Habano — Palacio de Convenciones','La Havane — Calle 146, Playa (chaque février)','Festival International Annuel','+53 7 204 0310','€€€€','Rendez-vous annuel organisé par Habanos S.A. depuis 1999. Galas, dégustations de vitoles exclusives, enchères de caves d\'exception.','habanos.com/festival',1,'2026-03-21 10:30:53','2026-08-26 11:06:15',NULL,NULL,NULL,NULL,NULL,0,'The annual gathering organised by Habanos S.A. since 1999. Galas, tastings of exclusive vitolas, and auctions of exceptional humidors.','Cita anual organizada por Habanos S.A. desde 1999. Galas, degustación de vitolas exclusivas y subastas de humidores excepcionales.','Das jährliche Treffen, seit 1999 von Habanos S.A. veranstaltet. Galas, Verkostungen exklusiver Vitolas und Auktionen außergewöhnlicher Humidore.','由 Habanos S.A. 自 1999 年起举办的年度盛会。设晚宴、独家规格品鉴与珍稀雪茄柜拍卖。','الملتقى السنوي الذي تنظّمه هابانوس ش.م. منذ 1999. حفلات، وتذوّق لمقاسات حصرية، ومزادات لمرطّبات استثنائية.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1570,'nicaragua','Drew Estate Factory — Lounge & Tour','Estelí — Km 148 Carretera Panamericana Norte','Manufacture Historique','+1 800 373 9388','€€€','Manufacture de Drew Estate à Estelí (Liga Privada, Undercrown) : plus de mille ouvriers. Visite d\'usine avec salon de dégustation et vente directe.','drewestate.com',1,'2026-03-21 10:30:53','2026-08-26 11:06:16',NULL,NULL,NULL,NULL,NULL,0,'Drew Estate\'s factory in Estelí (Liga Privada, Undercrown): over a thousand workers. Factory tour with a tasting lounge and direct sales.','Fábrica de Drew Estate en Estelí (Liga Privada, Undercrown): más de mil trabajadores. Visita a la fábrica con lounge de degustación y venta directa.','Die Manufaktur von Drew Estate in Estelí (Liga Privada, Undercrown): über tausend Beschäftigte. Werksführung mit Verkostungslounge und Direktverkauf.','德鲁庄园位于埃斯特利的制造厂（Liga Privada、Undercrown），员工逾千人。设参观导览与品鉴厅，可直接选购。','مصنع «درو إستيت» في إستيلي (ليغا بريفادا، أندركراون): أكثر من ألف عامل. جولة في المصنع مع صالة تذوّق وبيع مباشر.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1571,'nicaragua','Padrón Cigars Factory — Sala VIP','Estelí — Barrio Sandino, Estelí','Manufacture Historique','+1 305 649 4982','€€€€','Manufacture de la famille Padrón depuis 1964 (Padrón 1964, Serie 80). Sala VIP avec dégustation des millésimes rares, visite sur rendez-vous.','padron.com',1,'2026-03-21 10:30:53','2026-08-01 18:15:50',NULL,NULL,NULL,NULL,NULL,0,'The Padrón family\'s factory since 1964 (Padrón 1964, Serie 80). VIP room for tasting the rare vintages; visits by appointment.','Fábrica de la familia Padrón desde 1964 (Padrón 1964, Serie 80). Sala VIP con degustación de las añadas raras; visita con cita previa.','Manufaktur der Familie Padrón seit 1964 (Padrón 1964, Serie 80). VIP-Raum zur Verkostung der seltenen Jahrgänge; Besuch nach Vereinbarung.','帕德龙家族自 1964 年经营的制造厂（Padrón 1964、Serie 80）。贵宾室可品鉴稀有年份，参观需预约。','مصنع عائلة بادرون منذ 1964 (بادرون 1964، سيري 80). قاعة كبار الزوّار لتذوّق الإصدارات النادرة، والزيارة بموعد مسبق.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1572,'dominican','ProCigar Festival — Santiago & La Romana','Santiago de los Caballeros et La Romana (chaque février)','Festival International Annuel','+1 809 530 8100','€€€€','Festival annuel de l\'association des fabricants dominicains (Procigar), en février. Visites de manufactures et de champs de tabac entre Santiago de los Caballeros et La Romana, dégustations et rencontres avec les torcedores.','procigar.com',1,'2026-03-21 10:30:53','2026-09-03 12:39:18',NULL,NULL,NULL,NULL,NULL,0,'Annual festival of the Dominican cigar manufacturers\' association (Procigar), held in February. Factory and tobacco-field visits between Santiago de los Caballeros and La Romana, tastings and encounters with the rollers.','Festival anual de la asociación de fabricantes dominicanos (Procigar), en febrero. Visitas a fábricas y a campos de tabaco entre Santiago de los Caballeros y La Romana, catas y encuentros con los torcedores.','Jährliches Festival des dominikanischen Herstellerverbands (Procigar), im Februar. Besuche von Manufakturen und Tabakfeldern zwischen Santiago de los Caballeros und La Romana, Verkostungen und Begegnungen mit den Torcedores.','多米尼加雪茄制造商协会（Procigar）的年度节庆，每年二月举行。在圣地亚哥－德洛斯卡瓦耶罗斯与拉罗马纳之间参观制造厂与烟田，品鉴雪茄并与卷制师傅见面。','مهرجان سنويّ تقيمه جمعية صنّاع السيجار الدومينيكيين (بروسيغار) في شباط/فبراير. زيارات للمصانع وحقول التبغ بين سانتياغو دي لوس كاباييروس ولا رومانا، وجلسات تذوّق ولقاءات مع اللافّين.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1575,'dominican','Altadis General Cigar — Casa de Campo','La Romana — Calle Central, Casa de Campo Resort','Manufacture & Resort',NULL,'€€€€','Complexe luxueux intégrant resort, golf et manufacture de cigares. Dégustation sur place, salon de cigares face au terrain de polo.','casadecampo.com.do',1,'2026-03-21 10:30:53','2026-09-03 12:11:42',NULL,NULL,NULL,NULL,NULL,0,'Luxury complex combining resort, golf course and cigar factory. On-site tasting and a cigar lounge facing the polo field.','Complejo de lujo que integra resort, golf y fábrica de puros. Degustación in situ y salón de puros frente al campo de polo.','Luxuskomplex aus Resort, Golfplatz und Zigarrenmanufaktur. Verkostung vor Ort und Zigarrenlounge mit Blick auf das Polofeld.','集度假村、高尔夫与雪茄制造厂于一体的豪华综合体。现场品鉴，雪茄厅正对马球场。','مجمّع فاخر يضم منتجعًا وملعب غولف ومصنع سيجار. تذوّق في الموقع وصالة سيجار تطلّ على ملعب البولو.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1576,'dominican','Cigar Museum Santiago — Sala Degustación','Santiago de los Caballeros — Av. Estrella Sadhalá','Manufacture Historique','+1 809 971 2000','€€€','Musée du cigare de la capitale cigar de la RD. Salle de dégustation avec les meilleures vitolas dominicaines, histoire et artisanat.','RETIRÉ — aucune trace de cet établissement, et le domaine cité n\'existe pas',0,'2026-03-21 10:30:53','2026-09-04 17:37:41',NULL,NULL,NULL,NULL,NULL,0,'Cigar museum in the Dominican Republic\'s cigar capital. Tasting room featuring the finest Dominican vitolas, plus history and craft.','Museo del puro en la capital cigarrera de la República Dominicana. Sala de degustación con las mejores vitolas dominicanas, historia y artesanía.','Zigarrenmuseum in der Zigarrenhauptstadt der Dominikanischen Republik. Verkostungsraum mit den besten dominikanischen Vitolas, Geschichte und Handwerk.','多米尼加雪茄之都的雪茄博物馆。品鉴室汇集多米尼加最佳规格，并展示历史与工艺。','متحف السيجار في عاصمة السيجار الدومينيكية. قاعة تذوّق تضم أفضل المقاسات الدومينيكية، إلى جانب التاريخ والحرفة.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1611,'australia','The Establishment Hotel — Hemmes Cigar Lounge','Sydney — 252 George Street, CBD, NSW 2000','Hotel Cigar Bar','+61 2 9240 3000','€€€€','Hôtel boutique de prestige dans le CBD de Sydney. Cigar lounge au bar Tank, sélection de 80+ références, clientèle finance et media australiens.','merivale.com/the-establishment',1,'2026-03-21 10:30:53','2026-08-01 18:11:43',NULL,NULL,NULL,NULL,NULL,0,'Prestigious boutique hotel in Sydney\'s CBD. Cigar lounge at the Tank bar, with over 80 references, drawing Australian finance and media.','Hotel boutique de prestigio en el CBD de Sídney. Cigar lounge en el bar Tank, con más de 80 referencias; clientela de las finanzas y los medios australianos.','Prestigeträchtiges Boutiquehotel im CBD von Sydney. Zigarrenlounge in der Tank-Bar mit über 80 Referenzen, Publikum aus australischer Finanz- und Medienwelt.','位于悉尼中央商务区的高端精品酒店。Tank 酒吧内设雪茄厅，藏有 80 余款雪茄，客群来自澳大利亚金融与传媒界。','فندق بوتيك مرموق في وسط أعمال سيدني. صالة سيجار في بار «تانك» بأكثر من 80 صنفًا، يقصدها روّاد من أوساط المال والإعلام الأسترالية.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1612,'australia','Royal Melbourne Golf Club — Spike Bar Cigars','Melbourne — Cheltenham Road, Black Rock, VIC 3193','Club de Golf','+61 3 9598 6755','€€€€','Parcours du sandbelt de Melbourne, dans la brousse australienne. Spike Bar, où l\'on fume traditionnellement après le parcours.','royalmelbourne.com.au',1,'2026-03-21 10:30:53','2026-08-26 10:38:34',NULL,NULL,NULL,NULL,NULL,0,'A Melbourne Sandbelt course, set in the Australian bush. The Spike Bar, where a cigar after the round is tradition.','Campo del Sandbelt de Melbourne, en pleno bush australiano. Spike Bar, donde el puro tras la vuelta es tradición.','Ein Platz im Melbourne Sandbelt, im australischen Buschland. Die Spike Bar, in der die Zigarre nach der Runde Tradition hat.','位于墨尔本沙带的球场，坐落在澳洲丛林之中。Spike Bar 中，球局后点一支雪茄是传统。','ملعب في «الحزام الرملي» بملبورن، وسط الأدغال الأسترالية. صالة «سبايك بار» حيث تدخين السيجار بعد الجولة تقليد.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1613,'monaco','Hôtel de Paris — Bar Américain Cigars','Monaco — Place du Casino, MC 98000','Palace Cigar Bar','+377 98 06 30 00','€€€€','Le palace le plus célèbre de la Côte d\'Azur (1864). Bar américain avec sélection de cigares cubains, cave à vins légendaire, vue sur le Casino de Monte-Carlo.','montecarlosbm.com',1,'2026-03-21 10:30:53','2026-08-01 18:15:50',NULL,NULL,NULL,NULL,NULL,0,'The Riviera\'s most famous palace hotel (1864). American bar with a Cuban cigar selection, a legendary wine cellar, and a view of the Monte-Carlo Casino.','El palacio más famoso de la Costa Azul (1864). Bar americano con selección de puros cubanos, bodega legendaria y vistas al Casino de Montecarlo.','Das berühmteste Grandhotel der Côte d\'Azur (1864). American Bar mit kubanischer Zigarrenauswahl, legendärem Weinkeller und Blick auf das Casino von Monte-Carlo.','蔚蓝海岸最著名的宫殿酒店（1864 年）。美式酒吧备有古巴雪茄精选，酒窖传奇，可望见蒙特卡洛赌场。','أشهر فندق قصر على الريفييرا الفرنسية (1864). بار أمريكي بتشكيلة من السيجار الكوبي، وقبو نبيذ أسطوري، وإطلالة على كازينو مونت كارلو.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1614,'monaco','Yacht Club de Monaco — Fumoir','Monaco — Quai Louis II, MC 98000','Marina & Yacht Club','+377 93 10 63 00','€€€€','Club nautique fondé par HSH Prince Rainier III. Fumoir panoramique avec vue sur le port Hercule et les superyachts. Cigares servis lors des événements Grand Prix.','ycm.org',1,'2026-03-21 10:30:53','2026-08-01 18:06:15',NULL,NULL,NULL,NULL,NULL,0,'Yacht club founded by HSH Prince Rainier III. Panoramic smoking room overlooking Port Hercule and the superyachts. Cigars served during Grand Prix events.','Club náutico fundado por S.A.S. el príncipe Rainiero III. Fumador panorámico con vistas al puerto Hércules y a los superyates. Puros servidos durante los eventos del Gran Premio.','Yachtclub, gegründet von S.D. Fürst Rainier III. Panorama-Rauchsalon mit Blick auf Port Hercule und die Superyachten. Zigarren bei den Grand-Prix-Veranstaltungen.','由雷尼尔三世亲王创立的游艇俱乐部。全景吸烟室俯瞰赫拉克勒斯港与超级游艇。大奖赛期间供应雪茄。','نادٍ بحري أسّسه الأمير رينييه الثالث. صالة تدخين بانورامية تطلّ على ميناء هرقل واليخوت الفاخرة. يُقدَّم السيجار خلال فعاليات الجائزة الكبرى.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1615,'monaco','Casino de Monte-Carlo — Salle Fumoir','Monaco — Place du Casino, MC 98000','Club Privé Historique','+377 98 06 21 21','€€€€','Casino fondé en 1863 par Charles III. Salle fumoir historique avec plafonds à fresques, jeux privés et cigares cubains servis aux joueurs VIP.','casinomontecarlo.com',1,'2026-03-21 10:30:53','2026-08-01 18:06:14',NULL,NULL,NULL,NULL,NULL,0,'Casino founded in 1863 by Charles III. Historic smoking room with frescoed ceilings, private gaming, and Cuban cigars served to VIP players.','Casino fundado en 1863 por Carlos III. Sala de fumadores histórica con techos al fresco, juego privado y puros cubanos servidos a los jugadores VIP.','1863 von Charles III. gegründetes Casino. Historischer Rauchsalon mit Freskendecken, Privatspiel und kubanischen Zigarren für VIP-Spieler.','1863 年由查理三世创立的赌场。历史悠久的吸烟厅配湿壁画天花板，设私人牌局，为贵宾牌手供应古巴雪茄。','كازينو أسّسه شارل الثالث عام 1863. قاعة تدخين تاريخية بأسقف مزيّنة بالجداريات، وطاولات لعب خاصة، وسيجار كوبي يُقدَّم لكبار اللاعبين.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (1616,'monaco','La Terrasse — Métropole Hotel','Monaco — 4 Avenue de la Madone, MC 98000','Rooftop Bar','+377 93 15 15 15','€€€€','Rooftop du Metropole Monte-Carlo avec piscine et espace cigares en soirée. Vue 360° sur Monaco, cigares proposés au coucher du soleil.','metropole.com',1,'2026-03-21 10:30:53','2026-08-01 18:19:56',NULL,NULL,NULL,NULL,NULL,0,'Rooftop of the Metropole Monte-Carlo, with a pool and an evening cigar area. 360° views over Monaco, cigars served at sunset.','Azotea del Metropole Montecarlo, con piscina y espacio de puros por la noche. Vistas de 360° sobre Mónaco; puros servidos al atardecer.','Dachterrasse des Metropole Monte-Carlo mit Pool und abendlichem Zigarrenbereich. 360°-Blick über Monaco, Zigarren bei Sonnenuntergang.','蒙特卡洛大都会酒店顶层，设泳池与夜间雪茄区。360 度俯瞰摩纳哥，日落时分供应雪茄。','سطح فندق ميتروبول مونت كارلو، بمسبح وركن للسيجار في المساء. إطلالة بزاوية 360 درجة على موناكو، ويُقدَّم السيجار عند الغروب.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2497,'thailand','La Casa del Habano — Chiang Mai','Chiang Mai — Nimman Road, Maya Lifestyle Shopping Center','La Casa del Habano Officielle','+66 53 215 988','€€€','La Casa del Habano officielle de Chiang Mai, capitale culturelle du nord de la Thaïlande. Catalogue Habanos complet sur Nimman Road, l\'axe le plus cosmopolite de la ville, fréquenté par les expatriés et les milieux créatifs.','à vérifier — affiliation officielle affirmée sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%2C%20Chiang%20Mai%20%E2%80%94%20Nimman%20Road%2C%20Thailand',NULL,NULL,NULL,0,'Official La Casa del Habano in Chiang Mai, northern Thailand\'s cultural capital. Full Habanos catalog on Nimman Road — the city\'s most cosmopolitan axis, frequented by expats and the creative community.','La Casa del Habano oficial de Chiang Mai, capital cultural del norte de Tailandia. Catálogo Habanos completo en Nimman Road, el eje más cosmopolita de la ciudad, frecuentado por expatriados y la comunidad creativa.','Offizielle La Casa del Habano in Chiang Mai, der Kulturhauptstadt Nordthailands. Kompletter Habanos-Katalog an der Nimman Road, der weltoffensten Achse der Stadt, besucht von Expats und der Kreativszene.','清迈官方 La Casa del Habano——泰国北部的文化之都。完整的哈瓦那雪茄目录，位于宁曼路这条全城最国际化的轴线上，外派人士与创意圈常客。','«لا كاسا ديل هابانو» الرسمي في شيانغ ماي، العاصمة الثقافية لشمال تايلاند. كتالوج هابانوس الكامل في شارع نيمان، أكثر محاور المدينة انفتاحًا، ويقصده المغتربون والأوساط الإبداعية.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2498,'thailand','InterContinental Bangkok — Cigar Lounge','Bangkok — InterContinental Bangkok, 973 Ploenchit Rd','Hotel Cigar Lounge','+66 2 656 0444','€€€€','Lounge cigares intimiste de l\'InterContinental Bangkok, sur Ploenchit Road. Sélection d\'Habanos premium, bibliothèque de single malts, atmosphère discrète prisée des milieux diplomatiques et financiers de Bangkok.','sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=InterContinental%20Bangkok%2C%20Bangkok%20%E2%80%94%20InterContinental%20Bangkok%2C%20Thailand',NULL,NULL,NULL,0,'Intimate cigar lounge at the InterContinental Bangkok on Ploenchit Road. Premium Habanos selection, single malt whisky library, discreet atmosphere favored by Bangkok\'s diplomatic and financial community.','Cigar lounge íntimo del InterContinental Bangkok, en Ploenchit Road. Selección de Habanos premium, biblioteca de single malts y ambiente discreto apreciado por los círculos diplomáticos y financieros de Bangkok.','Intime Zigarrenlounge im InterContinental Bangkok an der Ploenchit Road. Auswahl an Premium-Habanos, Single-Malt-Bibliothek, diskrete Atmosphäre, geschätzt von Bangkoks diplomatischen und finanziellen Kreisen.','曼谷洲际酒店（Ploenchit 路）内私密的雪茄厅。精选高端哈瓦那雪茄、单一麦芽威士忌藏酒，低调氛围深受曼谷外交与金融界青睐。','صالة سيجار حميمة في فندق إنتركونتيننتال بانكوك بشارع بلوينشيت. تشكيلة من سيجار هابانوس الفاخر، ومكتبة من المولت المفرد، وأجواء هادئة تفضّلها الأوساط الدبلوماسية والمالية في بانكوك.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2499,'thailand','Davidoff — Phuket (Central Festival)','Phuket — Central Festival Phuket, 74/75 Moo 5 Vichitsongkram Rd','Davidoff Appointed Merchant','+66 76 291 111','€€€','Revendeur agréé Davidoff au Central Festival Mall de Phuket. Gamme Davidoff complète et accessoires premium, au service de la clientèle des resorts de luxe de l\'île toute l\'année.','à vérifier — affiliation officielle affirmée sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=Davidoff%2C%20Phuket%20%E2%80%94%20Central%20Festival%20Phuket%2C%20Thailand',NULL,NULL,NULL,0,'Davidoff appointed merchant in Phuket\'s Central Festival Mall. Full Davidoff range and premium accessories serving the island\'s luxury resort clientele year-round.','Distribuidor autorizado Davidoff en el Central Festival Mall de Phuket. Gama Davidoff completa y accesorios premium para la clientela de los resorts de lujo de la isla durante todo el año.','Autorisierter Davidoff-Händler in der Central Festival Mall auf Phuket. Komplettes Davidoff-Sortiment und Premium-Zubehör, ganzjährig für das Publikum der Luxusresorts der Insel.','普吉岛尚泰节庆购物中心的大卫杜夫特许经销商。全年为岛上豪华度假村客群提供完整的大卫杜夫系列与高端配件。','وكيل دافيدوف المعتمد في مركز سنترال فيستيفال بجزيرة بوكيت. تشكيلة دافيدوف الكاملة وملحقات فاخرة، تخدم نزلاء منتجعات الجزيرة الفاخرة طوال العام.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2500,'thailand','The Dome at State Tower — Cigar Terrace','Bangkok — State Tower, 1055 Silom Road','Rooftop Cigar Terrace','+66 2 624 9555','€€€€','Terrasse cigares du Dome, le rooftop le plus spectaculaire de Bangkok, à 247 mètres au-dessus du fleuve Chao Phraya. Habanos premium sur l\'une des toiles de fond urbaines les plus saisissantes d\'Asie du Sud-Est.','sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=The%20Dome%20at%20State%20Tower%2C%20Bangkok%20%E2%80%94%20State%20Tower%2C%20Thailand',NULL,NULL,NULL,0,'Cigar terrace at The Dome, Bangkok\'s most spectacular rooftop venue at 247 meters above the Chao Phraya River. Premium Habanos with one of Southeast Asia\'s most dramatic skyline backdrops.','Terraza de puros de The Dome, la azotea más espectacular de Bangkok, a 247 metros sobre el río Chao Phraya. Habanos premium ante uno de los telones de fondo urbanos más impresionantes del Sudeste Asiático.','Zigarrenterrasse im The Dome, Bangkoks spektakulärstem Rooftop auf 247 Metern über dem Chao Phraya. Premium-Habanos vor einer der eindrucksvollsten Skyline-Kulissen Südostasiens.','The Dome 的雪茄露台——曼谷最震撼的顶层场所，高踞湄南河上方 247 米。在东南亚最壮观的天际线背景中享用高端哈瓦那雪茄。','تراس السيجار في «ذا دوم»، أكثر أسطح بانكوك إبهارًا على ارتفاع 247 مترًا فوق نهر تشاو فرايا. سيجار هابانوس فاخر أمام واحدة من أروع خلفيات الأفق في جنوب شرق آسيا.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2501,'thailand','Mandarin Oriental Bangkok — Authors Lounge Cigars','Bangkok — Mandarin Oriental, 48 Oriental Ave','Hotel Cigar Bar Historique','+66 2 659 9000','€€€€','Coin cigares du Mandarin Oriental Bangkok, l\'un des plus anciens hôtels d\'Asie (fondé en 1876). Joseph Conrad, Somerset Maugham et Noel Coward y avaient leurs habitudes. Habanos premium dans un cadre d\'une élégance coloniale exceptionnelle.','sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=Mandarin%20Oriental%20Bangkok%2C%20Bangkok%20%E2%80%94%20Mandarin%20Oriental%2C%20Thailand',NULL,NULL,NULL,0,'Cigar corner at the Mandarin Oriental Bangkok, one of Asia\'s oldest hotels (founded 1876). Joseph Conrad, Somerset Maugham, and Noel Coward were regulars. Premium Habanos in a setting of extraordinary colonial elegance.','Rincón de puros del Mandarin Oriental Bangkok, uno de los hoteles más antiguos de Asia (fundado en 1876). Joseph Conrad, Somerset Maugham y Noel Coward eran habituales. Habanos premium en un entorno de elegancia colonial excepcional.','Zigarrenecke im Mandarin Oriental Bangkok, einem der ältesten Hotels Asiens (gegründet 1876). Joseph Conrad, Somerset Maugham und Noel Coward waren Stammgäste. Premium-Habanos in einem Rahmen außergewöhnlicher kolonialer Eleganz.','曼谷文华东方酒店的雪茄角——亚洲最古老的酒店之一（创立于 1876 年）。约瑟夫·康拉德、萨默塞特·毛姆与诺埃尔·科沃德均为常客。在极致殖民风优雅氛围中享用高端哈瓦那雪茄。','ركن السيجار في فندق ماندارين أورينتال بانكوك، أحد أقدم فنادق آسيا (تأسّس عام 1876). كان جوزيف كونراد وسومرست موم ونويل كوارد من روّاده. سيجار هابانوس فاخر في محيط من الأناقة الاستعمارية الاستثنائية.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2502,'thailand','La Casa del Habano — Pattaya','Pattaya — Royal Garden Plaza, 218 Beach Road','La Casa del Habano Officielle','+66 38 710 294','€€€','La Casa del Habano officielle de Pattaya, première station balnéaire de Thaïlande. Catalogue Habanos complet sur Beach Road, au service des visiteurs internationaux et de la communauté d\'affaires expatriée de la côte est.','à vérifier — affiliation officielle affirmée sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%2C%20Pattaya%20%E2%80%94%20Royal%20Garden%20Plaza%2C%20Thailand',NULL,NULL,NULL,0,'Official La Casa del Habano in Pattaya, Thailand\'s premier beach resort city. Full Habanos catalog on Beach Road, serving international visitors and the Eastern Seaboard expat business community.','La Casa del Habano oficial de Pattaya, principal ciudad balnearia de Tailandia. Catálogo Habanos completo en Beach Road, al servicio de los visitantes internacionales y de la comunidad de negocios expatriada de la costa oriental.','Offizielle La Casa del Habano in Pattaya, Thailands führendem Badeort. Kompletter Habanos-Katalog an der Beach Road, für internationale Besucher und die Expat-Geschäftswelt des Eastern Seaboard.','芭堤雅官方 La Casa del Habano——泰国首屈一指的海滨度假城市。完整的哈瓦那雪茄目录，位于海滩路，服务于国际访客与东部沿海地区的外派商务人士。','«لا كاسا ديل هابانو» الرسمي في باتايا، أبرز مدن تايلاند الشاطئية. كتالوج هابانوس الكامل في شارع البيتش، لخدمة الزوّار الدوليين وأوساط الأعمال المغتربة في الساحل الشرقي.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2503,'vietnam','La Casa del Habano — Hanoi (Sofitel Metropole)','Hanoi — 15 Ngo Quyen Street, Hoan Kiem District','La Casa del Habano Officielle','+84 24 3826 6919','€€€','La Casa del Habano officielle du légendaire Sofitel Legend Metropole Hanoi (1901). Charlie Chaplin et Graham Greene y ont séjourné. Catalogue Habanos complet dans le quartier français, à deux pas du lac Hoan Kiem.','à vérifier — affiliation officielle affirmée sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%2C%20Hanoi%20%E2%80%94%2015%20Ngo%20Quyen%20Street%2C%20Vietnam',NULL,NULL,NULL,0,'Official La Casa del Habano inside the legendary Sofitel Legend Metropole Hanoi (1901). Charlie Chaplin and Graham Greene stayed here. Full Habanos catalog in the French Quarter steps from Hoan Kiem Lake.','La Casa del Habano oficial del legendario Sofitel Legend Metropole Hanói (1901). Charlie Chaplin y Graham Greene se alojaron allí. Catálogo Habanos completo en el barrio francés, a pocos pasos del lago Hoan Kiem.','Offizielle La Casa del Habano im legendären Sofitel Legend Metropole Hanoi (1901). Charlie Chaplin und Graham Greene wohnten hier. Kompletter Habanos-Katalog im französischen Viertel, wenige Schritte vom Hoan-Kiem-See.','传奇的河内索菲特传奇大都会酒店（1901 年）内的官方 La Casa del Habano。查理·卓别林与格雷厄姆·格林曾下榻于此。完整的哈瓦那雪茄目录，位于法国区，距还剑湖仅数步之遥。','«لا كاسا ديل هابانو» الرسمي داخل فندق سوفيتيل ليجند متروبول هانوي الأسطوري (1901). أقام فيه تشارلي تشابلن وغراهام غرين. كتالوج هابانوس الكامل في الحي الفرنسي، على بُعد خطوات من بحيرة هوان كيم.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2504,'vietnam','Park Hyatt Saigon — Cigar Lounge','Ho Chi Minh-Ville — Park Hyatt Saigon, 2 Lam Son Square','Hotel Cigar Lounge',NULL,'€€€€','Lounge cigares raffiné du Park Hyatt Saigon, dominant la place historique de l\'Opéra. Habanos sélectionnés, cognacs vieillis, whiskys premium. L\'adresse cigare la plus élégante de Hô Chi Minh-Ville.','sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=Park%20Hyatt%20Saigon%2C%20Ho%20Chi%20Minh-Ville%20%E2%80%94%20Park%20Hyatt%20Saigon%2C%20Vietnam',NULL,NULL,NULL,0,'Refined cigar lounge at the Park Hyatt Saigon, overlooking the historic Opera House square. Curated Habanos, aged cognacs, premium whisky. The most elegant cigar address in Ho Chi Minh City.','Cigar lounge refinado del Park Hyatt Saigón, con vistas a la histórica plaza de la Ópera. Habanos seleccionados, coñacs envejecidos y whiskies premium. La dirección cigarrera más elegante de Ciudad Ho Chi Minh.','Raffinierte Zigarrenlounge im Park Hyatt Saigon mit Blick auf den historischen Opernplatz. Ausgewählte Habanos, gereifte Cognacs, Premium-Whiskys. Die eleganteste Zigarrenadresse in Ho-Chi-Minh-Stadt.','西贡柏悦酒店内精致的雪茄厅，俯瞰历史悠久的歌剧院广场。精选哈瓦那雪茄、陈年干邑与高端威士忌。胡志明市最优雅的雪茄之所。','صالة سيجار أنيقة في فندق بارك حياة سايغون، تطلّ على ساحة الأوبرا التاريخية. سيجار هابانوس منتقى، وكونياك معتّق، وويسكي فاخر. أرقى عناوين السيجار في مدينة هوشي منه.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2505,'vietnam','Caravelle Saigon — Rooftop Cigar Bar','Ho Chi Minh-Ville — Caravelle Saigon, 19-23 Lam Son Square','Rooftop Cigar Bar','+84 28 3823 4999','€€€€','Coin cigares du Saigon Saigon Bar, sur le toit du légendaire hôtel Caravelle. Les correspondants de guerre envoyaient leurs dépêches depuis cette terrasse pendant la guerre du Viêt Nam. Habanos premium et vue panoramique sur les toits de Saïgon.','sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=Caravelle%20Saigon%2C%20Ho%20Chi%20Minh-Ville%20%E2%80%94%20Caravelle%20Saigon%2C%20Vietnam',NULL,NULL,NULL,0,'Cigar corner at the rooftop Saigon Saigon Bar of the legendary Caravelle Hotel. Foreign correspondents filed war reports from this terrace during the Vietnam War. Premium Habanos with panoramic Saigon skyline views.','Rincón de puros del Saigon Saigon Bar, en la azotea del legendario hotel Caravelle. Los corresponsales de guerra enviaban sus crónicas desde esta terraza durante la guerra de Vietnam. Habanos premium y vistas panorámicas al skyline de Saigón.','Zigarrenecke in der Saigon Saigon Bar auf dem Dach des legendären Caravelle Hotel. Von dieser Terrasse aus schickten Kriegskorrespondenten während des Vietnamkriegs ihre Berichte. Premium-Habanos mit Panoramablick über Saigons Skyline.','传奇的卡拉维尔酒店顶层 Saigon Saigon Bar 的雪茄角。越战期间，外国记者曾在这处露台发出战地报道。高端哈瓦那雪茄，可全景俯瞰西贡天际线。','ركن السيجار في بار «سايغون سايغون» على سطح فندق كارافيل الأسطوري. من هذا التراس كان المراسلون الأجانب يرسلون تقاريرهم أثناء حرب فيتنام. سيجار هابانوس فاخر مع إطلالة بانورامية على أفق سايغون.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2506,'vietnam','La Casa del Habano — Da Nang','Da Nang — Pullman Da Nang Beach Resort, Vo Nguyen Giap','La Casa del Habano Officielle','+84 236 395 8888','€€€','La Casa del Habano officielle du Pullman Da Nang, entre Hoi An et les montagnes de Marbre. Catalogue Habanos complet, au service du marché en plein essor des resorts internationaux de Da Nang.','à vérifier — affiliation officielle affirmée sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%2C%20Da%20Nang%20%E2%80%94%20Pullman%20Da%20Nang%20Beach%20Resort%2C%20Vietnam',NULL,NULL,NULL,0,'Official La Casa del Habano at Pullman Da Nang, between Hoi An and the Marble Mountains. Full Habanos catalog serving Da Nang\'s booming international resort market.','La Casa del Habano oficial del Pullman Da Nang, entre Hoi An y las Montañas de Mármol. Catálogo Habanos completo al servicio del pujante mercado de resorts internacionales de Da Nang.','Offizielle La Casa del Habano im Pullman Da Nang, zwischen Hoi An und den Marmorbergen. Kompletter Habanos-Katalog für den boomenden internationalen Resortmarkt von Da Nang.','岘港铂尔曼酒店的官方 La Casa del Habano，位于会安与五行山之间。完整的哈瓦那雪茄目录，服务于岘港蓬勃发展的国际度假市场。','«لا كاسا ديل هابانو» الرسمي في فندق بولمان دا نانغ، بين هوي آن وجبال الرخام. كتالوج هابانوس الكامل لخدمة سوق المنتجعات الدولية المزدهر في دا نانغ.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2507,'vietnam','InterContinental Hanoi Westlake — Cigar Bar','Hanoi — InterContinental Hanoi Westlake, 1A Nghi Tam','Hotel Cigar Bar','+84 24 6270 8888','€€€€','Bar à cigares de l\'InterContinental Hanoi Westlake, bâti sur pilotis au-dessus du lac de l\'Ouest. Vue panoramique sur le lac, gamme complète de cigares premium, bibliothèque de whiskys et de cognacs. Fréquenté par la communauté diplomatique de Hanoï et les voyageurs d\'affaires internationaux.','sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=InterContinental%20Hanoi%20Westlake%2C%20Hanoi%20%E2%80%94%20InterContinental%20Hanoi%20Westlake%2C%20Vietnam',NULL,NULL,NULL,0,'Cigar bar at the InterContinental Hanoi Westlake, built on stilts over West Lake. Panoramic lake views, full premium cigar selection, whisky and cognac library. Serves Hanoi\'s diplomatic community and international business visitors.','Cigar bar del InterContinental Hanoi Westlake, construido sobre pilotes en el lago del Oeste. Vistas panorámicas al lago, gama completa de puros premium y biblioteca de whiskies y coñacs. Frecuentado por la comunidad diplomática de Hanói y los viajeros de negocios internacionales.','Zigarrenbar im InterContinental Hanoi Westlake, auf Stelzen über dem Westsee erbaut. Panoramablick auf den See, vollständige Premium-Zigarrenauswahl, Whisky- und Cognac-Bibliothek. Publikum aus Hanois Diplomatengemeinde und internationalen Geschäftsreisenden.','河内西湖洲际酒店的雪茄吧，以桩基架设于西湖之上。可全景眺望湖景，备有完整的高端雪茄阵容以及威士忌与干邑藏酒。客群为河内外交圈与国际商旅人士。','بار سيجار في فندق إنتركونتيننتال هانوي ويستليك، المبني على ركائز فوق البحيرة الغربية. إطلالة بانورامية على البحيرة، وتشكيلة كاملة من السيجار الفاخر، ومكتبة من الويسكي والكونياك. يقصده السلك الدبلوماسي في هانوي وزوّار الأعمال الدوليون.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2508,'malaysia','La Casa del Habano — Kuala Lumpur (Pavilion KL)','Kuala Lumpur — Pavilion KL, 168 Jalan Bukit Bintang','La Casa del Habano Officielle','+60 3 2141 8833','€€€','Deuxième La Casa del Habano de Kuala Lumpur, au Pavilion KL, le centre commercial de luxe au cœur de Bukit Bintang. Portefeuille Habanos complet, fumoir dédié, accessoires premium.','RETIRÉ — doublon de la seule La Casa del Habano du pays, à une adresse qui n\'est pas la sienne',0,'2026-03-22 18:57:48','2026-09-04 22:58:09',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%2C%20Kuala%20Lumpur%20%E2%80%94%20Pavilion%20KL%2C%20Malaysia',NULL,NULL,NULL,0,'Second La Casa del Habano in Kuala Lumpur at Pavilion KL, the luxury mall at the heart of Bukit Bintang. Full Habanos portfolio, dedicated smoking room, premium accessories.','Segunda La Casa del Habano de Kuala Lumpur, en Pavilion KL, el centro comercial de lujo en el corazón de Bukit Bintang. Portafolio completo de Habanos, sala de fumadores propia y accesorios premium.','Zweite La Casa del Habano in Kuala Lumpur, im Pavilion KL, dem Luxus-Einkaufszentrum im Herzen von Bukit Bintang. Komplettes Habanos-Portfolio, eigener Rauchsalon, Premium-Zubehör.','吉隆坡第二家 La Casa del Habano，位于武吉免登核心地带的奢华商场 Pavilion KL。完整的哈瓦那雪茄产品线、专属吸烟室与高端配件。','ثاني «لا كاسا ديل هابانو» في كوالالمبور، في مركز بافيليون KL الفاخر بقلب بوكيت بينتانغ. تشكيلة هابانوس الكاملة، وصالة تدخين مخصّصة، وملحقات فاخرة.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2509,'malaysia','Davidoff — Kuala Lumpur (Pavilion KL)','Kuala Lumpur — Pavilion KL, Lot 2.33.02, niveau 2, Couture Pavilion, 168 Jalan Bukit Bintang','Davidoff Flagship','+60 3 2141 1466','€€€€','Magasin phare Davidoff de Kuala Lumpur, au deuxième niveau du Pavilion, dans l\'aile Couture. Quarante-deux mètres carrés au concept « Davidoff of Geneva – since 1911 ».','pavilion-kl.com',1,'2026-03-22 18:57:48','2026-09-04 22:58:09','10h–22h','https://www.google.com/maps/search/?api=1&query=Davidoff%2C%20Kuala%20Lumpur%20%E2%80%94%20Suria%20KLCC%2C%20Malaysia','https://www.pavilion-kl.com/store/davidoff/',NULL,NULL,0,'Davidoff flagship store in Kuala Lumpur, on level two of Pavilion, in the Couture wing. Forty-two square metres built to the \"Davidoff of Geneva – since 1911\" concept.','Tienda insignia de Davidoff en Kuala Lumpur, en el segundo nivel de Pavilion, en el ala Couture. Cuarenta y dos metros cuadrados con el concepto «Davidoff of Geneva – since 1911».','Davidoff-Flagshipstore in Kuala Lumpur, auf Ebene zwei des Pavilion, im Couture-Flügel. Zweiundvierzig Quadratmeter nach dem Konzept „Davidoff of Geneva – since 1911\".','大卫杜夫在吉隆坡的旗舰店，位于柏威年广场二层 Couture 区。面积四十二平方米，按「Davidoff of Geneva – since 1911」概念设计。','المتجر الرئيسي لدافيدوف في كوالالمبور، في الطابق الثاني من مركز بافيليون، جناح كوتور. اثنان وأربعون مترًا مربعًا وفق مفهوم «Davidoff of Geneva – since 1911».',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2510,'malaysia','La Casa del Habano — Penang (Gurney Plaza)','Penang — Gurney Plaza, 170 Persiaran Gurney','La Casa del Habano Officielle','+60 4 228 5566','€€€','La Casa del Habano officielle de Penang, ville insulaire malaisienne inscrite à l\'UNESCO. Catalogue Habanos complet dans le quartier commerçant de Gurney Drive, au service du nord de la Malaisie et du centre historique de George Town.','RETIRÉ — l\'exploitant du réseau n\'annonce pas cette adresse',0,'2026-03-22 18:57:48','2026-09-04 22:58:09',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%2C%20Penang%20%E2%80%94%20Gurney%20Plaza%2C%20Malaysia',NULL,NULL,NULL,0,'Official La Casa del Habano in Penang, Malaysia\'s UNESCO-listed island city. Full Habanos catalog in the Gurney Drive retail district, serving northern Malaysia and George Town\'s heritage district.','La Casa del Habano oficial de Penang, ciudad insular malasia declarada Patrimonio de la Humanidad. Catálogo Habanos completo en el distrito comercial de Gurney Drive, al servicio del norte de Malasia y del casco histórico de George Town.','Offizielle La Casa del Habano in Penang, Malaysias UNESCO-gelisteter Inselstadt. Kompletter Habanos-Katalog im Einkaufsviertel Gurney Drive, für Nordmalaysia und die Altstadt von George Town.','槟城官方 La Casa del Habano——马来西亚的联合国教科文组织遗产岛城。完整的哈瓦那雪茄目录，位于葛尼道商圈，服务于马来西亚北部与乔治市古迹区。','«لا كاسا ديل هابانو» الرسمي في بينانغ، المدينة الجزيرة الماليزية المدرجة على قائمة اليونسكو. كتالوج هابانوس الكامل في منطقة غورني درايف التجارية، لخدمة شمال ماليزيا وحيّ جورج تاون التراثي.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2511,'malaysia','The Ruma Hotel — Cigar Bar','Kuala Lumpur — The RuMa Hotel, 7 Jalan Kia Peng','Hotel Cigar Bar','+60 3 2778 0888','€€€€','Bar à cigares intimiste du RuMa, hôtel de luxe de Kuala Lumpur. Habanos et cigares du Nouveau Monde sélectionnés, cocktails d\'auteur, art malaisien contemporain dans tout l\'établissement.','sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=The%20Ruma%20Hotel%2C%20Kuala%20Lumpur%20%E2%80%94%20The%20RuMa%20Hotel%2C%20Malaysia',NULL,NULL,NULL,0,'The RuMa\'s intimate cigar bar, in a Kuala Lumpur luxury hotel. A selection of Habanos and New World cigars, signature cocktails, and contemporary Malaysian art throughout.','Bar de puros íntimo del RuMa, hotel de lujo de Kuala Lumpur. Selección de habanos y puros del Nuevo Mundo, cócteles de autor y arte malasio contemporáneo por todo el hotel.','Die intime Zigarrenbar des RuMa, eines Luxushotels in Kuala Lumpur. Ausgewählte Habanos und New-World-Zigarren, Signature-Cocktails und zeitgenössische malaysische Kunst im ganzen Haus.','The RuMa 内私密的雪茄吧，位于吉隆坡的一家豪华酒店。精选哈瓦那雪茄与新世界雪茄、手作鸡尾酒，全馆陈列马来西亚当代艺术。','بار السيجار الحميم في «الرُّما»، وهو فندق فاخر في كوالالمبور. تشكيلة مختارة من سيجار هابانوس وسيجار العالم الجديد، وكوكتيلات مبتكرة، وفن ماليزي معاصر في أرجاء الفندق.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2512,'malaysia','Mandarin Oriental KL — Cigar Lounge','Kuala Lumpur — Mandarin Oriental, Kuala Lumpur City Centre','Hotel Cigar Lounge','+60 3 2380 8888','€€€€','Lounge cigares discret du Mandarin Oriental Kuala Lumpur, dominant le parc du KLCC et les tours Petronas. Sélection d\'Habanos, service d\'humidor privé, accords cognac et single malt.','RETIRÉ — même lieu que la fiche 134, compté deux fois',0,'2026-03-22 18:57:48','2026-09-04 22:58:09',NULL,'https://www.google.com/maps/search/?api=1&query=Mandarin%20Oriental%20KL%2C%20Kuala%20Lumpur%20%E2%80%94%20Mandarin%20Oriental%2C%20Malaysia',NULL,NULL,NULL,0,'Discreet cigar lounge at the Mandarin Oriental Kuala Lumpur, overlooking KLCC park and the Petronas Towers. Curated Habanos selection, private humidor service, cognac and single malt pairings.','Cigar lounge discreto del Mandarin Oriental Kuala Lumpur, con vistas al parque del KLCC y a las Torres Petronas. Selección de Habanos, servicio de humidor privado y maridajes con coñac y single malt.','Diskrete Zigarrenlounge im Mandarin Oriental Kuala Lumpur mit Blick auf den KLCC-Park und die Petronas Towers. Ausgewählte Habanos, privater Humidor-Service, Cognac- und Single-Malt-Pairings.','吉隆坡文华东方酒店内低调的雪茄厅，俯瞰吉隆坡城中城公园与双子塔。精选哈瓦那雪茄、私人雪茄柜服务，以及干邑与单一麦芽威士忌搭配。','صالة سيجار هادئة في فندق ماندارين أورينتال كوالالمبور، تطلّ على حديقة KLCC وبرجَي بتروناس. تشكيلة منتقاة من هابانوس، وخدمة مرطّبة خاصة، ومزاوجات مع الكونياك والمولت المفرد.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2513,'malaysia','La Casa del Habano — Johor Bahru','Johor Bahru — Paradigm Mall JB, Jalan Skudai','La Casa del Habano Officielle','+60 7 233 8800','€€€','La Casa del Habano officielle de Johor Bahru, ville-porte du sud de la Malaisie. Catalogue Habanos complet, au service du flux considérable de clientèle singapourienne venue faire ses achats de l\'autre côté de la frontière.','RETIRÉ — l\'exploitant du réseau n\'annonce pas cette adresse',0,'2026-03-22 18:57:48','2026-09-04 22:58:09',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%2C%20Johor%20Bahru%20%E2%80%94%20Paradigm%20Mall%20JB%2C%20Malaysia',NULL,NULL,NULL,0,'Official La Casa del Habano in Johor Bahru, Malaysia\'s southern gateway city. Full Habanos catalog serving the substantial Singaporean cross-border shopping traffic.','La Casa del Habano oficial de Johor Bahru, ciudad de entrada al sur de Malasia. Catálogo Habanos completo al servicio del importante flujo de compradores singapurenses que cruzan la frontera.','Offizielle La Casa del Habano in Johor Bahru, Malaysias südlicher Torstadt. Kompletter Habanos-Katalog für den beträchtlichen grenzüberschreitenden Einkaufsverkehr aus Singapur.','新山官方 La Casa del Habano——马来西亚南部门户城市。完整的哈瓦那雪茄目录，服务于大量跨境购物的新加坡客流。','«لا كاسا ديل هابانو» الرسمي في جوهور بهرو، مدينة البوابة الجنوبية لماليزيا. كتالوج هابانوس الكامل لخدمة التدفّق الكبير من المتسوّقين السنغافوريين عبر الحدود.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2514,'singapore','La Casa del Habano — Marina Bay Sands','Singapour — Marina Bay Sands, 10 Bayfront Avenue','La Casa del Habano Officielle','+65 6688 8868','€€€€','La Casa del Habano officielle de l\'emblématique Marina Bay Sands. Portefeuille Habanos complet, cave humidifiée où l\'on entre, accessoires premium. L\'une des destinations cigare les plus fréquentées d\'Asie du Sud-Est.','RETIRÉ — doublon de la seule La Casa del Habano du pays, à une adresse qui n\'est pas la sienne',0,'2026-03-22 18:57:48','2026-09-04 22:58:09',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%2C%20Singapour%20%E2%80%94%20Marina%20Bay%20Sands%2C%20Singapore',NULL,NULL,NULL,0,'Official La Casa del Habano in the iconic Marina Bay Sands. Full Habanos portfolio, walk-in humidor, premium accessories. One of the most visited cigar destinations in Southeast Asia.','La Casa del Habano oficial del icónico Marina Bay Sands. Portafolio completo de Habanos, humidor walk-in y accesorios premium. Uno de los destinos cigarreros más visitados del Sudeste Asiático.','Offizielle La Casa del Habano im ikonischen Marina Bay Sands. Komplettes Habanos-Portfolio, begehbarer Humidor, Premium-Zubehör. Eines der meistbesuchten Zigarrenziele Südostasiens.','标志性的滨海湾金沙内的官方 La Casa del Habano。完整的哈瓦那雪茄产品线、步入式雪茄柜与高端配件。东南亚访客最多的雪茄目的地之一。','«لا كاسا ديل هابانو» الرسمي داخل مارينا باي ساندز الأيقوني. تشكيلة هابانوس الكاملة، ومرطّبة قابلة للدخول، وملحقات فاخرة. من أكثر وجهات السيجار زيارة في جنوب شرق آسيا.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2515,'singapore','Davidoff of Geneva — Marina Bay Sands','Singapour — The Shoppes at Marina Bay Sands, 10 Bayfront Avenue','Davidoff Flagship',NULL,'€€€€','Boutique Davidoff des Shoppes at Marina Bay Sands. Humidor accessible, accessoires et un coin dédié aux spiritueux ; la marque y présente aussi d\'autres cigares premium.','marinabaysands.com',1,'2026-03-22 18:57:48','2026-09-04 22:58:09',NULL,'https://www.google.com/maps/search/?api=1&query=Davidoff%2C%20Singapour%20%E2%80%94%20Ngee%20Ann%20City%2C%20Singapore','https://www.marinabaysands.com/shopping/davidoff-of-geneva.html',NULL,NULL,0,'Davidoff boutique at The Shoppes at Marina Bay Sands. Walk-in humidor, accessories and a dedicated spirits corner; the store also carries other premium cigar brands.','Boutique Davidoff en The Shoppes at Marina Bay Sands. Humidor accesible, accesorios y un rincón dedicado a los destilados; la tienda ofrece también otras marcas de puros premium.','Davidoff-Boutique in The Shoppes at Marina Bay Sands. Begehbarer Humidor, Accessoires und eine eigene Spirituosenecke; das Geschäft führt auch andere Premiumzigarren.','位于滨海湾金沙购物商城的大卫杜夫专门店。设步入式恒湿雪茄柜、配件区与烈酒专区，并陈列其他高端雪茄品牌。','متجر دافيدوف في ذا شوبس بمارينا باي ساندز. مستودع ترطيب يمكن دخوله، وإكسسوارات، وركن مخصّص للمشروبات الروحية؛ ويعرض المتجر أيضًا ماركات سيجار فاخرة أخرى.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2516,'singapore','1-Altitude Gallery & Bar — Cigar Lounge','Singapour — 1 Raffles Place, Level 63','Rooftop Cigar Lounge','+65 6438 0410','€€€€','Lounge cigares du 1-Altitude, le bar en plein air le plus haut de Singapour, à 282 mètres. Vue panoramique sur la ville et le port, Habanos premium sélectionnés, cocktails signature. Le cadre rooftop le plus spectaculaire de Singapour pour un cigare.','sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=1-Altitude%20Gallery%20%26%20Bar%2C%20Singapour%20%E2%80%94%201%20Raffles%20Place%2C%20Singapore',NULL,NULL,NULL,0,'Cigar lounge at 1-Altitude, Singapore\'s highest al-fresco bar at 282 meters. Panoramic city and harbor views, curated premium Habanos, signature cocktails. The most dramatic rooftop cigar setting in Singapore.','Cigar lounge de 1-Altitude, el bar al aire libre más alto de Singapur, a 282 metros. Vistas panorámicas de la ciudad y el puerto, Habanos premium seleccionados y cócteles de autor. El entorno de azotea más espectacular de Singapur para un puro.','Zigarrenlounge im 1-Altitude, Singapurs höchster Open-Air-Bar auf 282 Metern. Panoramablick über Stadt und Hafen, ausgewählte Premium-Habanos, Signature-Cocktails. Die spektakulärste Rooftop-Kulisse Singapurs für eine Zigarre.','1-Altitude 的雪茄厅——新加坡最高的露天酒吧，海拔 282 米。全景俯瞰城市与港口，精选高端哈瓦那雪茄与招牌鸡尾酒。新加坡最震撼的顶层雪茄场所。','صالة السيجار في «وان ألتيتيود»، أعلى بار في الهواء الطلق في سنغافورة على ارتفاع 282 مترًا. إطلالة بانورامية على المدينة والميناء، وسيجار هابانوس فاخر منتقى، وكوكتيلات مميّزة. أكثر أسطح سنغافورة إبهارًا لتدخين السيجار.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2517,'singapore','Capella Singapore — Cigar Lounge','Singapour — Capella Singapore, 1 The Knolls, Sentosa Island','Hotel Cigar Lounge','+65 6377 8888','€€€€','Lounge cigares du Capella Singapore, le resort ultra-luxueux de l\'île de Sentosa. Bâtiments de l\'époque coloniale repensés par Norman Foster. Sélection d\'Habanos, terrasse privée dominant la mer de Chine méridionale.','sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=Capella%20Singapore%2C%20Singapour%20%E2%80%94%20Capella%20Singapore%2C%20Singapore',NULL,NULL,NULL,0,'Cigar lounge at Capella Singapore, the ultra-luxury resort on Sentosa Island. Colonial-era buildings redesigned by Norman Foster. Curated Habanos selection, private terrace overlooking the South China Sea.','Cigar lounge del Capella Singapore, el resort de ultralujo de la isla de Sentosa. Edificios de la época colonial reinterpretados por Norman Foster. Selección de Habanos y terraza privada sobre el mar de China Meridional.','Zigarrenlounge im Capella Singapore, dem Ultraluxus-Resort auf Sentosa Island. Gebäude aus der Kolonialzeit, neu gestaltet von Norman Foster. Ausgewählte Habanos, private Terrasse mit Blick auf das Südchinesische Meer.','圣淘沙岛超奢华度假村 Capella Singapore 的雪茄厅。殖民时期建筑由诺曼·福斯特重新设计。精选哈瓦那雪茄，私人露台俯瞰南海。','صالة السيجار في «كابيلا سنغافورة»، المنتجع فائق الفخامة في جزيرة سنتوسا. مبانٍ من الحقبة الاستعمارية أعاد تصميمها نورمان فوستر. تشكيلة منتقاة من هابانوس، وتراس خاص يطلّ على بحر الصين الجنوبي.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2518,'colombia','La Casa del Habano — Medellín (El Tesoro)','Medellín — Centro Comercial El Tesoro, Calle 10 No. 67-395','La Casa del Habano Officielle','+57 4 311 3990','€€€','La Casa del Habano officielle du quartier premium El Poblado, à Medellín. Catalogue Habanos complet, au service de la ville la plus innovante de Colombie. La transformation de Medellín en capitale du design et de la tech a fait émerger un nouveau public averti.','à vérifier — affiliation officielle affirmée sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%2C%20Medell%C3%ADn%20%E2%80%94%20Centro%20Comercial%20El%20Tesoro%2C%20Colombia',NULL,NULL,NULL,0,'Official La Casa del Habano in Medellín\'s El Poblado premium district. Full Habanos catalog serving Colombia\'s most innovative city. Medellín\'s transformation into a design and tech capital has created a sophisticated new cigar audience.','La Casa del Habano oficial del barrio premium El Poblado, en Medellín. Catálogo Habanos completo al servicio de la ciudad más innovadora de Colombia. La transformación de Medellín en capital del diseño y la tecnología ha creado un nuevo público sofisticado.','Offizielle La Casa del Habano im Premium-Viertel El Poblado in Medellín. Kompletter Habanos-Katalog für Kolumbiens innovativste Stadt. Medellíns Wandel zur Design- und Tech-Hauptstadt hat ein neues, anspruchsvolles Publikum hervorgebracht.','麦德林高端街区 El Poblado 的官方 La Casa del Habano。完整的哈瓦那雪茄目录，服务于哥伦比亚最具创新力的城市。麦德林转型为设计与科技之都，催生出一批品味成熟的新客群。','«لا كاسا ديل هابانو» الرسمي في حي إل بوبلادو الفاخر بمدينة ميديلين. كتالوج هابانوس الكامل لخدمة أكثر مدن كولومبيا ابتكارًا. تحوّل ميديلين إلى عاصمة للتصميم والتقنية صنع جمهورًا جديدًا رفيع الذوق.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2519,'colombia','La Casa del Habano — Barranquilla','Barranquilla — Vía 40 con Calle 74, Centro Empresarial Las Américas','La Casa del Habano Officielle','+57 5 360 8800','€€€','La Casa del Habano officielle de Barranquilla, porte caribéenne de la Colombie et grand port industriel. Portefeuille Habanos complet, au service des milieux commerciaux de la ville.','à vérifier — affiliation officielle affirmée sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%2C%20Barranquilla%20%E2%80%94%20V%C3%ADa%2040%20con%20Calle%2074%2C%20Colombia',NULL,NULL,NULL,0,'Official La Casa del Habano in Barranquilla, Colombia\'s Caribbean gateway and industrial port city. Full Habanos portfolio serving the city\'s commercial community.','La Casa del Habano oficial de Barranquilla, puerta caribeña de Colombia y gran puerto industrial. Portafolio completo de Habanos al servicio de la comunidad comercial de la ciudad.','Offizielle La Casa del Habano in Barranquilla, Kolumbiens karibischem Tor und bedeutender Industriehafen. Komplettes Habanos-Portfolio für die Handelswelt der Stadt.','巴兰基亚官方 La Casa del Habano——哥伦比亚的加勒比门户与工业港城。完整的哈瓦那雪茄产品线，服务于本地商界。','«لا كاسا ديل هابانو» الرسمي في بارانكييا، بوابة كولومبيا الكاريبية ومدينة الميناء الصناعي. تشكيلة هابانوس الكاملة لخدمة الأوساط التجارية في المدينة.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2520,'colombia','Davidoff — Cali (Chipichape)','Cali — Centro Comercial Chipichape, Calle 38 Norte No. 6-35','Davidoff Appointed Merchant','+57 2 661 4433','€€€','Revendeur agréé Davidoff dans le centre commercial premium Chipichape de Cali. Gamme Davidoff complète pour la troisième ville de Colombie.','à vérifier — affiliation officielle affirmée sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=Davidoff%2C%20Cali%20%E2%80%94%20Centro%20Comercial%20Chipichape%2C%20Colombia',NULL,NULL,NULL,0,'Davidoff appointed merchant in Cali\'s Chipichape premium mall. Full Davidoff range for Colombia\'s third city.','Distribuidor autorizado Davidoff en el centro comercial premium Chipichape de Cali. Gama Davidoff completa para la tercera ciudad de Colombia.','Autorisierter Davidoff-Händler im Premium-Einkaufszentrum Chipichape in Cali. Komplettes Davidoff-Sortiment für Kolumbiens drittgrößte Stadt.','卡利 Chipichape 高端购物中心的大卫杜夫特许经销商。为哥伦比亚第三大城市提供完整的大卫杜夫系列。','وكيل دافيدوف المعتمد في مركز تشيبيتشابي الفاخر بمدينة كالي. تشكيلة دافيدوف الكاملة لثالث أكبر مدن كولومبيا.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2521,'colombia','Club Colombia — Bogotá (El Chico)','Bogotá — Carrera 13 No. 85-40, El Chico','Cigar Lounge & Social Club','+57 1 616 5020','€€€€','Club privé de cigares et cercle social du quartier El Chico à Bogotá. Réservé aux membres : collection exceptionnelle d\'Habanos, casiers d\'humidor privés, bibliothèque de cognacs et de whiskys. Adresse discrète de l\'élite politique et économique de Bogotá.','sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=Club%20Colombia%2C%20Bogot%C3%A1%20%E2%80%94%20Carrera%2013%20No.%2085-40%2C%20Colombia',NULL,NULL,NULL,0,'Exclusive cigar and social club in Bogotá\'s El Chico neighborhood. Members-only, exceptional Habanos collection, private humidor storage, cognac and whisky library. Discreet address for Bogotá\'s political and business elite.','Club privado de puros y círculo social en el barrio El Chicó de Bogotá. Solo para socios: colección excepcional de Habanos, casilleros de humidor privados y biblioteca de coñacs y whiskies. Dirección discreta de la élite política y empresarial de Bogotá.','Privater Zigarren- und Gesellschaftsclub im Bogotáer Viertel El Chicó. Nur für Mitglieder: außergewöhnliche Habanos-Sammlung, private Humidorfächer, Cognac- und Whiskybibliothek. Diskrete Adresse der politischen und wirtschaftlichen Elite Bogotás.','波哥大 El Chicó 区的私人雪茄与社交俱乐部。仅限会员：出众的哈瓦那雪茄收藏、私人雪茄储存柜，以及干邑与威士忌藏酒。波哥大政商精英低调的聚会之所。','نادٍ خاص للسيجار والتواصل الاجتماعي في حي «إل تشيكو» ببوغوتا. للأعضاء فقط: مجموعة استثنائية من هابانوس، وخزائن مرطّبة خاصة، ومكتبة من الكونياك والويسكي. عنوان هادئ لنخبة بوغوتا السياسية والاقتصادية.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2522,'colombia','La Casa del Habano — Cartagena (Hotel Charleston)','Cartagena — Hotel Charleston Santa Teresa, Plaza de Santa Teresa','La Casa del Habano Officielle','+57 5 664 9494','€€€€','La Casa del Habano officielle de l\'Hotel Charleston Santa Teresa, dans la vieille ville fortifiée de Carthagène. Habanos au complet dans un couvent du XVIIe siècle. L\'adresse cigare au cadre le plus saisissant de la côte caraïbe.','à vérifier — affiliation officielle affirmée sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%2C%20Cartagena%20%E2%80%94%20Hotel%20Charleston%20Santa%20Teresa%2C%20Colombia',NULL,NULL,NULL,0,'Official La Casa del Habano inside the Hotel Charleston Santa Teresa in Cartagena\'s walled old city. Full Habanos in a 17th-century convent setting. The most atmospherically located cigar address on the Caribbean coast.','La Casa del Habano oficial del Hotel Charleston Santa Teresa, en el casco antiguo amurallado de Cartagena. Habanos al completo en un convento del siglo XVII. La dirección cigarrera con el entorno más evocador de la costa caribeña.','Offizielle La Casa del Habano im Hotel Charleston Santa Teresa in der ummauerten Altstadt von Cartagena. Vollständiges Habanos-Sortiment in einem Kloster des 17. Jahrhunderts. Die atmosphärisch schönste Zigarrenadresse der Karibikküste.','卡塔赫纳古城墙内 Hotel Charleston Santa Teresa 的官方 La Casa del Habano。在 17 世纪修道院中呈现完整的哈瓦那雪茄阵容。加勒比海岸氛围最动人的雪茄之所。','«لا كاسا ديل هابانو» الرسمي داخل فندق تشارلستون سانتا تيريزا في مدينة قرطاجنة القديمة المسوّرة. تشكيلة هابانوس كاملة في دير يعود إلى القرن السابع عشر. أجمل عناوين السيجار أجواءً على ساحل الكاريبي.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2523,'argentina','Faena Hotel — Cigar Lounge','Buenos Aires — Faena Hotel, Martha Salotti 445, Puerto Madero','Hotel Cigar Lounge','+54 11 4010 9000','€€€€','Lounge cigares du légendaire Faena Hotel, sur le front d\'eau de Puerto Madero. Conçu par Philippe Starck. Habanos premium dans l\'un des décors architecturaux les plus extraordinaires d\'Amérique latine.','sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=Faena%20Hotel%2C%20Buenos%20Aires%20%E2%80%94%20Faena%20Hotel%2C%20Argentina',NULL,NULL,NULL,0,'Cigar lounge at the legendary Faena Hotel, Puerto Madero waterfront. Designed by Philippe Starck. Premium Habanos in one of Latin America\'s most extraordinary architectural settings.','Cigar lounge del legendario Faena Hotel, en el frente de agua de Puerto Madero. Diseñado por Philippe Starck. Habanos premium en uno de los entornos arquitectónicos más extraordinarios de América Latina.','Zigarrenlounge im legendären Faena Hotel an der Uferpromenade von Puerto Madero. Gestaltet von Philippe Starck. Premium-Habanos in einer der außergewöhnlichsten Architekturkulissen Lateinamerikas.','传奇的 Faena Hotel 雪茄厅，坐落于马德罗港滨水区。由菲利普·斯塔克设计。在拉丁美洲最非凡的建筑空间之一享用高端哈瓦那雪茄。','صالة السيجار في فندق فاينا الأسطوري على واجهة بويرتو ماديرو المائية. من تصميم فيليب ستارك. سيجار هابانوس فاخر في واحد من أبهى الأطر المعمارية في أمريكا اللاتينية.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2524,'argentina','Alvear Palace — Churchill Cigar Bar','Buenos Aires — Alvear Palace Hotel, Av. Alvear 1891, Recoleta','Hotel Cigar Bar Historique','+54 11 4804 7777','€€€€','Le Churchill Cigar Bar de l\'Alvear Palace, le grand hôtel le plus prestigieux de Buenos Aires depuis 1932. Cadre Belle Époque, Habanos d\'exception, armagnacs millésimés et scotchs vieillis. L\'establishment argentin y fume depuis près d\'un siècle.','sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=Alvear%20Palace%2C%20Buenos%20Aires%20%E2%80%94%20Alvear%20Palace%20Hotel%2C%20Argentina',NULL,NULL,NULL,0,'The Churchill Cigar Bar at the Alvear Palace, Buenos Aires\' most prestigious grand hotel since 1932. Belle Époque setting, exceptional Habanos, vintage Armagnac and aged Scotch. The Argentine establishment has smoked here for nearly a century.','El Churchill Cigar Bar del Alvear Palace, el gran hotel más prestigioso de Buenos Aires desde 1932. Ambiente Belle Époque, Habanos excepcionales, armañacs añejos y escoceses envejecidos. El establishment argentino fuma aquí desde hace casi un siglo.','Die Churchill Cigar Bar im Alvear Palace, seit 1932 dem prestigeträchtigsten Grandhotel von Buenos Aires. Belle-Époque-Ambiente, außergewöhnliche Habanos, Jahrgangs-Armagnacs und gereifte Scotches. Das argentinische Establishment raucht hier seit fast einem Jahrhundert.','Alvear Palace 的丘吉尔雪茄吧——自 1932 年起布宜诺斯艾利斯最负盛名的大酒店。美好年代风格空间、臻选哈瓦那雪茄、年份雅文邑与陈年苏格兰威士忌。阿根廷上流社会在此吸烟已近一个世纪。','بار «تشرشل» للسيجار في فندق ألفيار بالاس، أعرق الفنادق الكبرى في بوينس آيرس منذ 1932. أجواء البيل إيبوك، وسيجار هابانوس استثنائي، وأرماناك بسنوات إنتاج مميّزة، وويسكي اسكتلندي معتّق. تدخّن هنا نخبة الأرجنتين منذ قرن تقريبًا.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2525,'argentina','La Casa del Habano — Rosario','Rosario — Bulevar Oroño 300, Centro','La Casa del Habano Officielle','+54 341 424 6600','€€€','La Casa del Habano officielle de Rosario, troisième ville d\'Argentine sur le Paraná — ville natale du Che Guevara et de Lionel Messi. Portefeuille Habanos complet pour les milieux d\'affaires de la région de la Pampa.','à vérifier — affiliation officielle affirmée sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%2C%20Rosario%20%E2%80%94%20Bulevar%20Oro%C3%B1o%20300%2C%20Argentina',NULL,NULL,NULL,0,'Official La Casa del Habano in Rosario, Argentina\'s third city on the Paraná River — birthplace of Che Guevara and Lionel Messi. Full Habanos portfolio for the Pampas region business community.','La Casa del Habano oficial de Rosario, tercera ciudad de Argentina a orillas del Paraná, cuna del Che Guevara y de Lionel Messi. Portafolio completo de Habanos para la comunidad empresarial de la región pampeana.','Offizielle La Casa del Habano in Rosario, Argentiniens drittgrößter Stadt am Paraná — Geburtsort von Che Guevara und Lionel Messi. Komplettes Habanos-Portfolio für die Geschäftswelt der Pampas-Region.','罗萨里奥官方 La Casa del Habano——阿根廷第三大城市，位于巴拉那河畔，切·格瓦拉与莱昂内尔·梅西的故乡。完整的哈瓦那雪茄产品线，服务于潘帕斯地区商界。','«لا كاسا ديل هابانو» الرسمي في روساريو، ثالث مدن الأرجنتين على نهر بارانا — مسقط رأس تشي غيفارا وليونيل ميسي. تشكيلة هابانوس الكاملة لأوساط الأعمال في منطقة البامباس.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2526,'argentina','La Casa del Habano — Mendoza','Mendoza — Peatonal Sarmiento 262','La Casa del Habano Officielle','+54 261 423 7700','€€€','La Casa del Habano officielle de Mendoza, capitale viticole de l\'Argentine au pied des Andes. La spécialité de la maison : marier les Habanos à des malbecs d\'exception. Catalogue complet, fumoir dédié.','à vérifier — affiliation officielle affirmée sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%2C%20Mendoza%20%E2%80%94%20Peatonal%20Sarmiento%20262%2C%20Argentina',NULL,NULL,NULL,0,'Official La Casa del Habano in Mendoza, Argentina\'s wine capital at the foot of the Andes. Pairing Habanos with exceptional Malbec is the house specialty. Full catalog, dedicated smoking room.','La Casa del Habano oficial de Mendoza, capital vitivinícola de Argentina a los pies de los Andes. La especialidad de la casa es maridar Habanos con malbecs excepcionales. Catálogo completo y sala de fumadores propia.','Offizielle La Casa del Habano in Mendoza, Argentiniens Weinhauptstadt am Fuß der Anden. Die Spezialität des Hauses: Habanos mit außergewöhnlichen Malbecs zu kombinieren. Kompletter Katalog, eigener Rauchsalon.','门多萨官方 La Casa del Habano——阿根廷葡萄酒之都，坐落于安第斯山麓。以哈瓦那雪茄搭配出众的马尔贝克葡萄酒为招牌。完整目录，设专属吸烟室。','«لا كاسا ديل هابانو» الرسمي في مندوزا، عاصمة النبيذ الأرجنتينية عند سفح الأنديز. اختصاص المحل مزاوجة سيجار هابانوس مع نبيذ مالبيك الاستثنائي. كتالوج كامل وصالة تدخين مخصّصة.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2528,'chile','The Ritz-Carlton Santiago — Cigar Lounge','Santiago — Ritz-Carlton Santiago, El Alcalde 15, Las Condes','Hotel Cigar Lounge','+56 2 2470 8500','€€€€','Lounge cigares premium du Ritz-Carlton Santiago, à Las Condes. Habanos sélectionnés, accords whisky et bordeaux, terrasse privée avec vue sur la cordillère des Andes par temps clair.','sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=The%20Ritz-Carlton%20Santiago%2C%20Santiago%20%E2%80%94%20Ritz-Carlton%20Santiago%2C%20Chile',NULL,NULL,NULL,0,'Premium cigar lounge at the Ritz-Carlton Santiago in Las Condes. Curated Habanos, Andean whisky and Bordeaux pairings, private terrace with Andes mountain views on clear days.','Cigar lounge premium del Ritz-Carlton Santiago, en Las Condes. Habanos seleccionados, maridajes con whisky y burdeos, y terraza privada con vistas a la cordillera de los Andes en días despejados.','Premium-Zigarrenlounge im Ritz-Carlton Santiago in Las Condes. Ausgewählte Habanos, Whisky- und Bordeaux-Pairings, private Terrasse mit Andenblick an klaren Tagen.','拉斯孔德斯圣地亚哥丽思卡尔顿酒店的高端雪茄厅。精选哈瓦那雪茄，搭配威士忌与波尔多葡萄酒，私人露台在晴日可远眺安第斯山脉。','صالة سيجار فاخرة في فندق ريتز كارلتون سانتياغو بحي لاس كونديس. سيجار هابانوس منتقى، ومزاوجات مع الويسكي ونبيذ بوردو، وتراس خاص يطلّ على جبال الأنديز في الأيام الصافية.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2529,'chile','La Casa del Habano — Concepción','Concepción — Av. O\'Higgins 940, Centro','La Casa del Habano Officielle','+56 41 223 1200','€€€','La Casa del Habano officielle de Concepción, deuxième ville du Chili. Portefeuille Habanos complet, au service de cette ville universitaire et des milieux d\'affaires de la région du Biobío.','à vérifier — affiliation officielle affirmée sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%2C%20Concepci%C3%B3n%20%E2%80%94%20Av.%20O%27Higgins%20940%2C%20Chile',NULL,NULL,NULL,0,'Official La Casa del Habano in Concepción, Chile\'s second city. Full Habanos portfolio serving the university city and Bio-Bío region\'s business community.','La Casa del Habano oficial de Concepción, segunda ciudad de Chile. Portafolio completo de Habanos al servicio de la ciudad universitaria y de la comunidad empresarial de la región del Biobío.','Offizielle La Casa del Habano in Concepción, Chiles zweitgrößter Stadt. Komplettes Habanos-Portfolio für die Universitätsstadt und die Geschäftswelt der Region Biobío.','康塞普西翁官方 La Casa del Habano——智利第二大城市。完整的哈瓦那雪茄产品线，服务于这座大学城与比奥比奥大区的商界。','«لا كاسا ديل هابانو» الرسمي في كونسبسيون، ثاني مدن تشيلي. تشكيلة هابانوس الكاملة لخدمة المدينة الجامعية وأوساط الأعمال في منطقة بيوبيو.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2530,'chile','La Casa del Habano — Antofagasta','Antofagasta — Mall Plaza Antofagasta, Av. El Ejército 1452','La Casa del Habano Officielle','+56 55 245 0200','€€€','La Casa del Habano officielle d\'Antofagasta, capitale de la région cuprifère du Chili. Catalogue Habanos complet, au service de l\'encadrement minier international.','à vérifier — affiliation officielle affirmée sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%2C%20Antofagasta%20%E2%80%94%20Mall%20Plaza%20Antofagasta%2C%20Chile',NULL,NULL,NULL,0,'Official La Casa del Habano in Antofagasta, capital of Chile\'s copper mining region. Full Habanos catalog serving the international mining management community.','La Casa del Habano oficial de Antofagasta, capital de la región cuprífera de Chile. Catálogo Habanos completo al servicio de los cuadros directivos mineros internacionales.','Offizielle La Casa del Habano in Antofagasta, der Hauptstadt der chilenischen Kupferregion. Kompletter Habanos-Katalog für die internationale Bergbau-Führungsebene.','安托法加斯塔官方 La Casa del Habano——智利铜矿区首府。完整的哈瓦那雪茄目录，服务于国际矿业管理层。','«لا كاسا ديل هابانو» الرسمي في أنتوفاغاستا، عاصمة منطقة النحاس في تشيلي. كتالوج هابانوس الكامل لخدمة كوادر التعدين الدولية.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2532,'peru','La Casa del Habano — Miraflores','Lima — Av. Larco 770, Miraflores','La Casa del Habano Officielle','+51 1 447 0303','€€€','La Casa del Habano officielle de Miraflores, à Lima, dominant le Pacifique. Portefeuille Habanos complet. La scène gastronomique mondialement réputée de Lima a fait naître un public averti en matière de cigare.','à vérifier — affiliation officielle affirmée sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%2C%20Lima%20%E2%80%94%20Av.%20Larco%20770%2C%20Peru',NULL,NULL,NULL,0,'Official La Casa del Habano in Lima\'s Miraflores, overlooking the Pacific. Full Habanos portfolio. Lima\'s world-famous gastronomic scene has built a sophisticated cigar culture audience.','La Casa del Habano oficial de Miraflores, en Lima, con vistas al Pacífico. Portafolio completo de Habanos. La escena gastronómica mundialmente célebre de Lima ha formado un público con una cultura cigarrera sofisticada.','Offizielle La Casa del Habano in Limas Stadtteil Miraflores mit Blick auf den Pazifik. Komplettes Habanos-Portfolio. Limas weltberühmte Gastronomieszene hat ein anspruchsvolles Zigarrenpublikum hervorgebracht.','利马米拉弗洛雷斯区的官方 La Casa del Habano，俯瞰太平洋。完整的哈瓦那雪茄产品线。利马享誉世界的美食风潮，孕育出一批品味成熟的雪茄客群。','«لا كاسا ديل هابانو» الرسمي في حي ميرافلوريس بليما، المطلّ على المحيط الهادئ. تشكيلة هابانوس الكاملة. صنع مشهد ليما الشهير عالميًا في فنّ الطهو جمهورًا رفيع الذوق في ثقافة السيجار.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2533,'peru','Country Club Lima Hotel — Cigar Lounge','Lima — Country Club Lima Hotel, Los Eucaliptos 590, San Isidro','Hotel Cigar Lounge','+51 1 611 9000','€€€€','Lounge cigares du Country Club Lima Hotel, édifice colonial des années 1920 à San Isidro. Habanos d\'exception, accords avec le pisco péruvien. Adresse discrète de l\'establishment liménien, affaires et politique.','sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=Country%20Club%20Lima%20Hotel%2C%20Lima%20%E2%80%94%20Country%20Club%20Lima%20Hotel%2C%20Peru',NULL,NULL,NULL,0,'Cigar lounge at the Country Club Lima Hotel, a 1920s colonial landmark in San Isidro. Exceptional Habanos, Peruvian pisco pairings. Discreet address for Lima\'s business and political establishment.','Cigar lounge del Country Club Lima Hotel, edificio colonial de los años veinte en San Isidro. Habanos excepcionales y maridajes con pisco peruano. Dirección discreta del establishment limeño, empresarial y político.','Zigarrenlounge im Country Club Lima Hotel, einem Kolonialbau der 1920er-Jahre in San Isidro. Außergewöhnliche Habanos, Pairings mit peruanischem Pisco. Diskrete Adresse des Limaer Establishments aus Wirtschaft und Politik.','Country Club Lima Hotel 的雪茄厅，坐落于圣伊西德罗的 1920 年代殖民建筑内。臻选哈瓦那雪茄，搭配秘鲁皮斯科酒。利马商政两界低调的聚会之所。','صالة السيجار في فندق كانتري كلوب ليما، مبنى استعماري من عشرينيات القرن الماضي في سان إيسيدرو. سيجار هابانوس استثنائي ومزاوجات مع البيسكو البيروفي. عنوان هادئ لنخبة ليما في المال والسياسة.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2534,'peru','Davidoff — Lima (Jockey Plaza)','Lima — Jockey Plaza, Av. Javier Prado Este 4200, Surco','Davidoff Appointed Merchant','+51 1 434 3950','€€€','Revendeur agréé Davidoff au Jockey Plaza, le plus grand centre commercial premium de Lima. Gamme Davidoff complète et Habanos sélectionnés pour les quartiers est de Lima.','à vérifier — affiliation officielle affirmée sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=Davidoff%2C%20Lima%20%E2%80%94%20Jockey%20Plaza%2C%20Peru',NULL,NULL,NULL,0,'Davidoff appointed merchant at Jockey Plaza, Lima\'s largest premium mall. Full Davidoff range and select Habanos for Lima\'s eastern districts.','Distribuidor autorizado Davidoff en Jockey Plaza, el mayor centro comercial premium de Lima. Gama Davidoff completa y Habanos seleccionados para los distritos del este de Lima.','Autorisierter Davidoff-Händler im Jockey Plaza, Limas größtem Premium-Einkaufszentrum. Komplettes Davidoff-Sortiment und ausgewählte Habanos für die östlichen Bezirke Limas.','Jockey Plaza 的大卫杜夫特许经销商——利马最大的高端购物中心。为利马东部各区提供完整的大卫杜夫系列与精选哈瓦那雪茄。','وكيل دافيدوف المعتمد في «جوكي بلازا»، أكبر مركز تسوّق فاخر في ليما. تشكيلة دافيدوف الكاملة وسيجار هابانوس منتقى لأحياء ليما الشرقية.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2535,'peru','Hotel Monasterio Cusco — Cigar Terrace','Cusco — Hotel Monasterio, Calle Palacios 136','Hotel Cigar Terrace','+51 84 604 000','€€€€','Terrasse cigares de l\'Hotel Monasterio, installé dans un monastère jésuite du XVIe siècle, à 3 400 mètres d\'altitude. Habanos aux portes du Machu Picchu.','sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=Hotel%20Monasterio%20Cusco%2C%20Cusco%20%E2%80%94%20Hotel%20Monasterio%2C%20Peru',NULL,NULL,NULL,0,'The cigar terrace of the Hotel Monasterio, housed in a 16th-century Jesuit monastery at 3,400 metres. Habanos at the gateway to Machu Picchu.','Terraza de puros del Hotel Monasterio, instalado en un monasterio jesuita del siglo XVI a 3400 metros de altitud. Habanos a las puertas del Machu Picchu.','Die Zigarrenterrasse des Hotel Monasterio in einem Jesuitenkloster des 16. Jahrhunderts auf 3400 Metern Höhe. Habanos am Tor zum Machu Picchu.','Monasterio 酒店的雪茄露台，坐落于海拔 3400 米的 16 世纪耶稣会修道院内。在通往马丘比丘的门户享用哈瓦那雪茄。','تراس السيجار في فندق «موناستيريو»، القائم في دير يسوعي من القرن السادس عشر على ارتفاع 3400 متر. سيجار هابانوس عند بوابة ماتشو بيتشو.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2536,'senegal','El Fumador — Dakar','Dakar — 40 rue Jules Ferry','Habanos Specialist','+221 33 823 9556','€€€','Boutique spécialisée agréée par Habanos, au centre de Dakar : soixante mètres carrés, dont une douzaine de cave accessible. Approvisionnement par Phoenicia Trading, distributeur exclusif pour l\'Afrique.','habanos.com — annonce officielle « Habanos Specialist El Fumador in Senegal »',1,'2026-03-22 18:57:48','2026-09-04 23:07:22',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%2C%20Dakar%20%E2%80%94%20Route%20des%20Almadies%2C%20Senegal',NULL,NULL,NULL,0,'Habanos-approved specialist shop in central Dakar: sixty square metres, of which a dozen are walk-in humidor. Supplied by Phoenicia Trading, the exclusive distributor for Africa.','Tienda especializada autorizada por Habanos, en el centro de Dakar: sesenta metros cuadrados, de los que una docena son humidor accesible. Suministro de Phoenicia Trading, distribuidor exclusivo para África.','Von Habanos autorisiertes Fachgeschäft im Zentrum von Dakar: sechzig Quadratmeter, davon rund zwölf begehbarer Humidor. Beliefert von Phoenicia Trading, dem Exklusivdistributor für Afrika.','哈伯纳斯授权的专门店，位于达喀尔市中心：面积六十平方米，其中约十二平方米为步入式恒湿柜。由非洲独家经销商 Phoenicia Trading 供货。','متجر متخصّص معتمد من هابانوس في وسط داكار: ستّون مترًا مربعًا، منها نحو اثني عشر مستودعَ ترطيب يمكن دخوله. التوريد عبر Phoenicia Trading، الموزّع الحصري لأفريقيا.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2537,'senegal','Radisson Blu Dakar — Cigar Lounge','Dakar — Radisson Blu Hotel, Route de King Fahd, Ngor','Hotel Cigar Lounge','+221 33 869 3333','€€€€','Lounge cigares du Radisson Blu Dakar, face à l\'océan Atlantique dans le quartier de Ngor. Habanos premium pour la communauté d\'affaires internationale de Dakar et le corps diplomatique.','sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=Radisson%20Blu%20Dakar%2C%20Dakar%20%E2%80%94%20Radisson%20Blu%20Hotel%2C%20Senegal',NULL,NULL,NULL,0,'Cigar lounge at the Radisson Blu Dakar, facing the Atlantic Ocean in the Ngor district. Premium Habanos for Dakar\'s international business community and diplomatic corps.','Cigar lounge del Radisson Blu Dakar, frente al océano Atlántico en el barrio de Ngor. Habanos premium para la comunidad de negocios internacional de Dakar y el cuerpo diplomático.','Zigarrenlounge im Radisson Blu Dakar, mit Blick auf den Atlantik im Viertel Ngor. Premium-Habanos für Dakars internationale Geschäftswelt und das diplomatische Korps.','达喀尔丽笙酒店的雪茄厅，位于恩戈尔区，正对大西洋。为达喀尔国际商界与外交使团提供高端哈瓦那雪茄。','صالة السيجار في فندق راديسون بلو داكار، المطلّ على المحيط الأطلسي في حي نغور. سيجار هابانوس فاخر لأوساط الأعمال الدولية في داكار وللسلك الدبلوماسي.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2538,'senegal','King Fahd Palace — VIP Cigar Terrace','Dakar — King Fahd Palace Hotel, Avenue Cheikh Anta Diop','Palace Cigar Terrace','+221 33 869 1900','€€€€','Terrasse cigares VIP du King Fahd Palace, l\'emblématique cinq-étoiles de Dakar depuis 1984. Terrasse sur l\'océan, cigares premium sélectionnés. Fréquentée par les chefs d\'État lors des sommets de la CEDEAO.','sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=King%20Fahd%20Palace%2C%20Dakar%20%E2%80%94%20King%20Fahd%20Palace%20Hotel%2C%20Senegal',NULL,NULL,NULL,0,'VIP cigar terrace at the King Fahd Palace, Dakar\'s iconic five-star landmark since 1984. Ocean terrace, curated premium cigars. Frequented by heads of state during ECOWAS summits.','Terraza de puros VIP del King Fahd Palace, el emblemático cinco estrellas de Dakar desde 1984. Terraza sobre el océano y puros premium seleccionados. Frecuentada por jefes de Estado durante las cumbres de la CEDEAO.','VIP-Zigarrenterrasse im King Fahd Palace, seit 1984 Dakars ikonischem Fünf-Sterne-Haus. Terrasse zum Ozean, ausgewählte Premium-Zigarren. Besucht von Staatschefs während der ECOWAS-Gipfel.','King Fahd Palace 的贵宾雪茄露台——自 1984 年起达喀尔的地标五星级酒店。面朝海洋的露台，精选高端雪茄。西非国家经济共同体峰会期间常有国家元首莅临。','تراس السيجار لكبار الزوّار في فندق قصر الملك فهد، الفندق الأيقوني من فئة الخمس نجوم في داكار منذ 1984. تراس على المحيط وسيجار فاخر منتقى. يرتاده رؤساء الدول خلال قمم المجموعة الاقتصادية لدول غرب أفريقيا.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2539,'senegal','Terrou-Bi — Espace Cigares','Dakar — Hotel Terrou-Bi, Boulevard Martin Luther King','Hotel Cigar Space','+221 33 839 9000','€€€','Coin cigares dédié de l\'Hôtel Terrou-Bi, le plus ancien hôtel de luxe de Dakar, sur la corniche atlantique. Sélection premium en écho aux couchers de soleil légendaires sur l\'océan.','sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=Terrou-Bi%2C%20Dakar%20%E2%80%94%20Hotel%20Terrou-Bi%2C%20Senegal',NULL,NULL,NULL,0,'Dedicated cigar corner at the Hotel Terrou-Bi, Dakar\'s oldest luxury hotel on the Atlantic corniche. Premium selection complementing the legendary sunset ocean views.','Rincón de puros del Hotel Terrou-Bi, el hotel de lujo más antiguo de Dakar, en la corniche atlántica. Selección premium que acompaña las legendarias puestas de sol sobre el océano.','Eigener Zigarrenbereich im Hotel Terrou-Bi, Dakars ältestem Luxushotel an der Atlantikpromenade. Premium-Auswahl als Begleitung zu den legendären Sonnenuntergängen über dem Ozean.','Hôtel Terrou-Bi 专设的雪茄角——达喀尔历史最悠久的豪华酒店，坐落于大西洋滨海大道。高端精选与传奇的海上落日相得益彰。','ركن سيجار مخصّص في فندق تيرو-بي، أقدم فنادق داكار الفاخرة على كورنيش الأطلسي. تشكيلة فاخرة ترافق غروب الشمس الأسطوري على المحيط.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2540,'senegal','Le Lagon I — Fumoir de l\'Atlantique','Dakar — Route de la Corniche-Ouest, Fann','Restaurant Gastronomique & Fumoir','+221 33 821 7951','€€€','Coin cigares du Lagon I, le restaurant de bord de mer le plus renommé de Dakar depuis 1967. Cigares premium en accord avec les produits frais de l\'Atlantique. Adresse incontournable des dîners d\'affaires sénégalais.','sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=Le%20Lagon%20I%2C%20Dakar%20%E2%80%94%20Route%20de%20la%20Corniche-Ouest%2C%20Senegal',NULL,NULL,NULL,0,'Cigar corner at Le Lagon I, Dakar\'s most celebrated seaside restaurant since 1967. Premium cigars paired with fresh Atlantic seafood. Institutional address for Senegalese business dinners.','Rincón de puros de Le Lagon I, el restaurante frente al mar más célebre de Dakar desde 1967. Puros premium maridados con pescados y mariscos frescos del Atlántico. Dirección de referencia para las cenas de negocios senegalesas.','Zigarrenecke im Le Lagon I, seit 1967 Dakars berühmtestem Restaurant am Meer. Premium-Zigarren zu frischen Meeresfrüchten aus dem Atlantik. Feste Adresse senegalesischer Geschäftsessen.','Le Lagon I 的雪茄角——自 1967 年起达喀尔最负盛名的海滨餐厅。高端雪茄佐以大西洋鲜活海产。塞内加尔商务晚宴的经典去处。','ركن السيجار في «لو لاغون 1»، أشهر مطعم على شاطئ داكار منذ 1967. سيجار فاخر يُقدَّم مع مأكولات الأطلسي البحرية الطازجة. عنوان راسخ لعشاءات الأعمال السنغالية.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2541,'senegal','Hôtel des Almadies — Cigar Bar','Dakar — Almadies, Route de Ngor','Hotel Cigar Bar','+221 33 820 6060','€€€','Bar à cigares de l\'Hôtel des Almadies, dans le quartier des ambassades de Dakar. Habanos premium, terrasse sur l\'Atlantique, atmosphère calme prisée de la communauté diplomatique résidente.','sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=H%C3%B4tel%20des%20Almadies%2C%20Dakar%20%E2%80%94%20Almadies%2C%20Senegal',NULL,NULL,NULL,0,'Cigar bar at the Hôtel des Almadies in Dakar\'s embassy district. Premium Habanos, Atlantic terrace, quiet atmosphere favored by the resident diplomatic community.','Cigar bar del Hôtel des Almadies, en el barrio de las embajadas de Dakar. Habanos premium, terraza sobre el Atlántico y ambiente tranquilo apreciado por la comunidad diplomática residente.','Zigarrenbar im Hôtel des Almadies, im Botschaftsviertel von Dakar. Premium-Habanos, Atlantikterrasse, ruhige Atmosphäre, geschätzt von der ansässigen Diplomatengemeinde.','位于达喀尔使馆区 Hôtel des Almadies 的雪茄吧。高端哈瓦那雪茄、面朝大西洋的露台，静谧氛围深受常驻外交圈青睐。','بار سيجار في فندق «ديزالماديه» بحي السفارات في داكار. سيجار هابانوس فاخر، وتراس على الأطلسي، وأجواء هادئة تفضّلها الجالية الدبلوماسية المقيمة.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2542,'togo','La Casa del Habano Togo — The Smoking Gorilla','Lomé — B6 Immeuble Marina, à côté de Total Marina, BP 1003','La Casa del Habano Officielle',NULL,'€€€','Première La Casa del Habano d\'Afrique de l\'Ouest, exploitée par LCDC – LCDT La Casa de Cigares. Cave accessible réunissant le portefeuille Habanos et les séries réservées à la franchise.','habanos.com — annonce officielle « Welcome La Casa del Habano Togo in África »',1,'2026-03-22 18:57:48','2026-09-04 23:07:22','Lun–Sam 9h–0h','https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%2C%20Lom%C3%A9%20%E2%80%94%20Avenue%20du%2024%20Janvier%2C%20Togo',NULL,NULL,NULL,0,'First La Casa del Habano in West Africa, run by LCDC – LCDT La Casa de Cigares. Walk-in humidor carrying the Habanos portfolio and the series reserved for the franchise.','Primera La Casa del Habano de África Occidental, gestionada por LCDC – LCDT La Casa de Cigares. Humidor accesible con la cartera Habanos y las series reservadas a la franquicia.','Erste La Casa del Habano Westafrikas, betrieben von LCDC – LCDT La Casa de Cigares. Begehbarer Humidor mit dem Habanos-Portfolio und den der Franchise vorbehaltenen Serien.','西非首家 La Casa del Habano，由 LCDC – LCDT La Casa de Cigares 经营。设步入式恒湿雪茄柜，陈列哈伯纳斯全系列及franchise专属产品。','أوّل «لا كاسا ديل هابانو» في غرب أفريقيا، تديرها LCDC – LCDT La Casa de Cigares. مستودع ترطيب يمكن دخوله يضمّ تشكيلة هابانوس والسلاسل المخصّصة للامتياز.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2543,'togo','Hôtel Sarakawa — Cigar Bar','Lomé — Hôtel Sarakawa, Boulevard du Mono','Hotel Cigar Bar','+228 22 27 65 65','€€€','Bar à cigares de l\'Hôtel Sarakawa, l\'hôtel de luxe emblématique de Lomé depuis 1975. Adresse historique des sommets de la CEDEAO. Cigares premium, spiritueux locaux, terrasse sur l\'Atlantique.','sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=H%C3%B4tel%20Sarakawa%2C%20Lom%C3%A9%20%E2%80%94%20H%C3%B4tel%20Sarakawa%2C%20Togo',NULL,NULL,NULL,0,'Cigar bar at the Hôtel Sarakawa, Lomé\'s landmark luxury hotel since 1975. Historic address for ECOWAS summits. Premium cigars, local spirits, Atlantic terrace.','Cigar bar del Hôtel Sarakawa, el hotel de lujo emblemático de Lomé desde 1975. Dirección histórica de las cumbres de la CEDEAO. Puros premium, destilados locales y terraza sobre el Atlántico.','Zigarrenbar im Hôtel Sarakawa, seit 1975 Lomés Wahrzeichen der Luxushotellerie. Historische Adresse der ECOWAS-Gipfel. Premium-Zigarren, lokale Spirituosen, Atlantikterrasse.','Hôtel Sarakawa 的雪茄吧——自 1975 年起洛美的地标豪华酒店。西非国家经济共同体历届峰会的举办地。高端雪茄、本地烈酒与面朝大西洋的露台。','بار سيجار في فندق ساراكاوا، الفندق الفاخر الأيقوني في لومي منذ 1975. عنوان تاريخي لقمم المجموعة الاقتصادية لدول غرب أفريقيا. سيجار فاخر ومشروبات محلية وتراس على الأطلسي.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2544,'togo','Hôtel Mercure Lomé — VIP Lounge','Lomé — Avenue du 24 Janvier','Hotel Cigar Lounge','+228 22 27 80 80','€€€','Lounge cigares VIP de l\'Hôtel Mercure Lomé, référence d\'affaires de la diplomatie ouest-africaine francophone. Habanos premium, salle climatisée, clientèle diplomatique.','sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=H%C3%B4tel%20Mercure%20Lom%C3%A9%2C%20Lom%C3%A9%20%E2%80%94%20Avenue%20du%2024%20Janvier%2C%20Togo',NULL,NULL,NULL,0,'VIP cigar lounge at the Hôtel Mercure Lomé, the business reference for francophone West African diplomacy. Premium Habanos, air-conditioned, diplomatic clientele.','Cigar lounge VIP del Hôtel Mercure Lomé, referencia empresarial de la diplomacia francófona de África Occidental. Habanos premium, sala con aire acondicionado y clientela diplomática.','VIP-Zigarrenlounge im Hôtel Mercure Lomé, der Geschäftsadresse der frankofonen westafrikanischen Diplomatie. Premium-Habanos, klimatisierter Raum, diplomatisches Publikum.','Hôtel Mercure Lomé 的贵宾雪茄厅——法语西非外交圈的商务标杆。高端哈瓦那雪茄、恒温空间，客群为外交人士。','صالة سيجار لكبار الزوّار في فندق مركيور لومي، المرجع الأعمالي للدبلوماسية الفرنكوفونية في غرب أفريقيا. سيجار هابانوس فاخر، وقاعة مكيّفة، وروّاد من السلك الدبلوماسي.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2545,'benin','La Casa del Habano — Cotonou','Cotonou — Cadjèhoun, Avenue Jean-Paul II','La Casa del Habano Officielle','+229 21 30 18 00','€€€','La Casa del Habano officielle de Cotonou, capitale économique du Bénin et premier marché de l\'art d\'Afrique de l\'Ouest. Portefeuille Habanos complet pour un public du cigare premium en croissance.','RETIRÉ — ce pays n\'a pas de La Casa del Habano ; le réseau y a un autre échelon, ou rien',0,'2026-03-22 18:57:48','2026-09-04 23:07:22',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%2C%20Cotonou%20%E2%80%94%20Cadj%C3%A8houn%2C%20Benin',NULL,NULL,NULL,0,'Official La Casa del Habano in Cotonou, Benin\'s economic capital and West Africa\'s most important art market. Full Habanos portfolio for the growing premium cigar audience.','La Casa del Habano oficial de Cotonú, capital económica de Benín y principal mercado del arte de África Occidental. Portafolio completo de Habanos para un público del puro premium en crecimiento.','Offizielle La Casa del Habano in Cotonou, der Wirtschaftshauptstadt Benins und wichtigstem Kunstmarkt Westafrikas. Komplettes Habanos-Portfolio für ein wachsendes Premium-Zigarrenpublikum.','科托努官方 La Casa del Habano——贝宁经济首都，西非最重要的艺术市场。完整的哈瓦那雪茄产品线，面向不断成长的高端雪茄客群。','«لا كاسا ديل هابانو» الرسمي في كوتونو، العاصمة الاقتصادية لبنين وأهم سوق للفن في غرب أفريقيا. تشكيلة هابانوس الكاملة لجمهور متنامٍ من محبّي السيجار الفاخر.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2546,'benin','Hôtel du Lac — Fumoir','Cotonou — Boulevard de la Marina, Cotonou-Lac','Hotel Cigar Lounge','+229 21 31 35 00','€€€','Lounge cigares de l\'Hôtel du Lac, l\'hôtel historique du front de mer de Cotonou. Terrasse dominant la route côtière. Atmosphère classique appréciée des milieux diplomatiques et commerciaux.','sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=H%C3%B4tel%20du%20Lac%2C%20Cotonou%20%E2%80%94%20Boulevard%20de%20la%20Marina%2C%20Benin',NULL,NULL,NULL,0,'Cigar lounge at the Hôtel du Lac, Cotonou\'s historic waterfront hotel. Terrace overlooking the coastal road. Classic atmosphere favored by the diplomatic and commercial community.','Cigar lounge del Hôtel du Lac, el hotel histórico del frente marítimo de Cotonú. Terraza sobre la carretera costera. Ambiente clásico apreciado por los círculos diplomáticos y comerciales.','Zigarrenlounge im Hôtel du Lac, dem historischen Hotel an Cotonous Uferpromenade. Terrasse über der Küstenstraße. Klassische Atmosphäre, geschätzt von diplomatischen und kaufmännischen Kreisen.','Hôtel du Lac 的雪茄厅——科托努海滨的老牌酒店。露台俯瞰滨海公路。经典氛围深受外交与商界人士喜爱。','صالة السيجار في «أوتيل دو لاك»، الفندق التاريخي على واجهة كوتونو البحرية. تراس يطلّ على الطريق الساحلي. أجواء كلاسيكية تحظى بتقدير الأوساط الدبلوماسية والتجارية.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2547,'benin','Novotel Cotonou — Cigar Corner','Cotonou — Novotel Orisha, Haie Vive','Hotel Cigar Space','+229 21 30 07 07','€€€','Coin cigares du Novotel Cotonou Orisha, l\'hôtel d\'affaires de référence de la capitale économique du Bénin. Habanos sélectionnés, terrasse au bord de la piscine, fréquenté par les milieux commerciaux et les ONG.','sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=Novotel%20Cotonou%2C%20Cotonou%20%E2%80%94%20Novotel%20Orisha%2C%20Benin',NULL,NULL,NULL,0,'Cigar corner at the Novotel Cotonou Orisha, the business hotel of reference for Benin\'s economic capital. Curated Habanos, poolside terrace, serving the commercial and NGO community.','Rincón de puros del Novotel Cotonou Orisha, el hotel de negocios de referencia de la capital económica de Benín. Habanos seleccionados, terraza junto a la piscina; clientela comercial y de ONG.','Zigarrenecke im Novotel Cotonou Orisha, dem maßgeblichen Business-Hotel der Wirtschaftshauptstadt Benins. Ausgewählte Habanos, Terrasse am Pool, Publikum aus Handel und NGO-Kreisen.','Novotel Cotonou Orisha 的雪茄角——贝宁经济首都的标杆商务酒店。精选哈瓦那雪茄，泳池畔露台，客群来自商界与非政府组织。','ركن السيجار في فندق نوفوتيل كوتونو أوريشا، فندق الأعمال المرجعي في العاصمة الاقتصادية لبنين. سيجار هابانوس منتقى، وتراس على حافة المسبح، يقصده أوساط التجارة والمنظمات غير الحكومية.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2548,'guinea','La Casa del Habano — Conakry','Conakry — Kaloum, Avenue de la République','La Casa del Habano Officielle','+224 622 30 40 50','€€€','La Casa del Habano officielle de Conakry, capitale de la Guinée sur la presqu\'île de Kaloum. Catalogue Habanos complet pour les cadres miniers et la communauté diplomatique de l\'un des marchés les plus riches en ressources d\'Afrique de l\'Ouest.','RETIRÉ — ce pays n\'a pas de La Casa del Habano ; le réseau y a un autre échelon, ou rien',0,'2026-03-22 18:57:48','2026-09-04 23:07:22',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%2C%20Conakry%20%E2%80%94%20Kaloum%2C%20Guinea',NULL,NULL,NULL,0,'Official La Casa del Habano in Conakry, Guinea\'s capital on the Kaloum Peninsula. Full Habanos catalog for the mining executives and diplomatic community of one of West Africa\'s most resource-rich markets.','La Casa del Habano oficial de Conakri, capital de Guinea en la península de Kaloum. Catálogo Habanos completo para los directivos mineros y la comunidad diplomática de uno de los mercados más ricos en recursos de África Occidental.','Offizielle La Casa del Habano in Conakry, der Hauptstadt Guineas auf der Halbinsel Kaloum. Kompletter Habanos-Katalog für Bergbau-Führungskräfte und die Diplomatengemeinde eines der rohstoffreichsten Märkte Westafrikas.','科纳克里官方 La Casa del Habano——几内亚首都，位于卡卢姆半岛。完整的哈瓦那雪茄目录，服务于这一西非资源最富集市场之一的矿业高管与外交圈。','«لا كاسا ديل هابانو» الرسمي في كوناكري، عاصمة غينيا على شبه جزيرة كالوم. كتالوج هابانوس الكامل لمديري قطاع التعدين والسلك الدبلوماسي في واحد من أغنى أسواق غرب أفريقيا بالموارد.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2549,'guinea','Hôtel Noom Conakry — Cigar Lounge','Conakry — Hôtel Noom, Kaloum, Avenue du Port','Hotel Cigar Lounge','+224 631 00 10 10','€€€€','Lounge cigares de l\'Hôtel Noom, l\'hôtel de luxe le plus moderne de Guinée. Vue panoramique sur l\'Atlantique, Habanos premium, atmosphère exclusive pour les cadres du secteur minier et les investisseurs internationaux.','sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=H%C3%B4tel%20Noom%20Conakry%2C%20Conakry%20%E2%80%94%20H%C3%B4tel%20Noom%2C%20Guinea',NULL,NULL,NULL,0,'Cigar lounge at the Hôtel Noom, Guinea\'s most modern luxury hotel. Panoramic Atlantic views, premium Habanos, exclusive atmosphere for mining executives and international investors.','Cigar lounge del Hôtel Noom, el hotel de lujo más moderno de Guinea. Vistas panorámicas al Atlántico, Habanos premium y ambiente exclusivo para directivos del sector minero e inversores internacionales.','Zigarrenlounge im Hôtel Noom, dem modernsten Luxushotel Guineas. Panoramablick auf den Atlantik, Premium-Habanos, exklusive Atmosphäre für Führungskräfte des Bergbausektors und internationale Investoren.','Hôtel Noom 的雪茄厅——几内亚最现代的豪华酒店。全景眺望大西洋，高端哈瓦那雪茄，专为矿业高管与国际投资者营造的私密氛围。','صالة السيجار في فندق نووم، أحدث فندق فاخر في غينيا. إطلالة بانورامية على الأطلسي، وسيجار هابانوس فاخر، وأجواء حصرية لمديري قطاع التعدين والمستثمرين الدوليين.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2550,'guinea','Palm Camayenne — Espace Fumoir','Conakry — Hôtel Palm Camayenne, Quartier Camayenne','Hotel Cigar Space','+224 664 44 00 00','€€€','Espace cigares du Palm Camayenne, l\'hôtel d\'affaires établi de Conakry, dans le quartier huppé de Camayenne. Cigares premium, terrasse sur l\'Atlantique, hospitalité ouest-africaine.','sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=Palm%20Camayenne%2C%20Conakry%20%E2%80%94%20H%C3%B4tel%20Palm%20Camayenne%2C%20Guinea',NULL,NULL,NULL,0,'Cigar space at the Palm Camayenne, Conakry\'s established business hotel in the upscale Camayenne district. Premium cigars, Atlantic ocean terrace, West African hospitality.','Espacio de puros del Palm Camayenne, hotel de negocios consolidado de Conakri, en el elegante barrio de Camayenne. Puros premium, terraza sobre el Atlántico y hospitalidad de África Occidental.','Zigarrenbereich im Palm Camayenne, dem etablierten Business-Hotel Conakrys im gehobenen Viertel Camayenne. Premium-Zigarren, Atlantikterrasse, westafrikanische Gastfreundschaft.','Palm Camayenne 的雪茄区——科纳克里久负盛名的商务酒店，坐落于高档的卡马耶讷区。高端雪茄、面朝大西洋的露台，以及西非式款待。','ركن السيجار في «بالم كامايين»، فندق الأعمال العريق في كوناكري بحي كامايين الراقي. سيجار فاخر وتراس على الأطلسي وضيافة غرب أفريقية.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2551,'burkina','La Casa del Habano — Ouagadougou','Ouagadougou — Avenue Kwame Nkrumah, Secteur 4','La Casa del Habano Officielle','+226 25 30 60 00','€€','La Casa del Habano officielle de Ouagadougou, au cœur enclavé de l\'Afrique de l\'Ouest. Portefeuille Habanos complet pour les milieux d\'affaires burkinabè et les professionnels des agences de développement installés dans la capitale.','RETIRÉ — ce pays n\'a pas de La Casa del Habano ; le réseau y a un autre échelon, ou rien',0,'2026-03-22 18:57:48','2026-09-04 23:07:22',NULL,'https://www.google.com/maps/search/?api=1&query=La%20Casa%20del%20Habano%2C%20Ouagadougou%20%E2%80%94%20Avenue%20Kwame%20Nkrumah%2C%20Burkina%20Faso',NULL,NULL,NULL,0,'Official La Casa del Habano in Ouagadougou, the land-locked heart of West Africa. Full Habanos portfolio for the Burkinabe business community and development agency professionals based in the capital.','La Casa del Habano oficial de Uagadugú, en el corazón sin litoral de África Occidental. Portafolio completo de Habanos para la comunidad empresarial burkinesa y los profesionales de las agencias de desarrollo instalados en la capital.','Offizielle La Casa del Habano in Ouagadougou, im binnenländischen Herzen Westafrikas. Komplettes Habanos-Portfolio für die burkinische Geschäftswelt und die in der Hauptstadt ansässigen Fachleute der Entwicklungsagenturen.','瓦加杜古官方 La Casa del Habano——西非内陆腹地。完整的哈瓦那雪茄产品线，服务于布基纳法索商界与常驻首都的发展机构专业人士。','«لا كاسا ديل هابانو» الرسمي في واغادوغو، في القلب الحبيس لغرب أفريقيا. تشكيلة هابانوس الكاملة لأوساط الأعمال البوركينية ولمهنيّي وكالات التنمية المقيمين في العاصمة.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2552,'burkina','Hôtel Laïco — Cigar Bar','Ouagadougou — Hôtel Laïco, Avenue du Président Maurice Yaméogo','Hotel Cigar Bar','+226 25 30 60 60','€€€','Bar à cigares de l\'Hôtel Laïco (ex-Indépendance), l\'hôtel emblématique de Ouagadougou depuis l\'indépendance en 1960. Adresse historique des sommets régionaux. Cigares premium au bar de la terrasse.','sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=H%C3%B4tel%20La%C3%AFco%2C%20Ouagadougou%20%E2%80%94%20H%C3%B4tel%20La%C3%AFco%2C%20Burkina%20Faso',NULL,NULL,NULL,0,'Cigar bar at the Hôtel Laïco (ex-Indépendance), Ouagadougou\'s landmark hotel since independence in 1960. Historic address for regional summits. Premium cigars on the terrace bar.','Cigar bar del Hôtel Laïco (antes Indépendance), el hotel emblemático de Uagadugú desde la independencia en 1960. Dirección histórica de las cumbres regionales. Puros premium en el bar de la terraza.','Zigarrenbar im Hôtel Laïco (ehemals Indépendance), Ouagadougous Wahrzeichenhotel seit der Unabhängigkeit 1960. Historische Adresse regionaler Gipfeltreffen. Premium-Zigarren an der Terrassenbar.','Hôtel Laïco（前身为 Indépendance）的雪茄吧——自 1960 年独立以来瓦加杜古的地标酒店。历届区域峰会的历史场所。露台酒吧供应高端雪茄。','بار سيجار في فندق لايكو (سابقًا أنديبندانس)، الفندق الأيقوني في واغادوغو منذ الاستقلال عام 1960. عنوان تاريخي للقمم الإقليمية. سيجار فاخر في بار التراس.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2553,'burkina','Splendid Hôtel — VIP Lounge','Ouagadougou — Hôtel Splendid, Avenue de l\'Indépendance','Hotel Cigar Lounge','+226 25 33 21 10','€€','Lounge VIP du Splendid Hôtel, l\'hôtel d\'affaires du centre de Ouagadougou. Cigares premium sélectionnés pour les professionnels du secteur du développement et les responsables gouvernementaux de la capitale burkinabè.','sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=Splendid%20H%C3%B4tel%2C%20Ouagadougou%20%E2%80%94%20H%C3%B4tel%20Splendid%2C%20Burkina%20Faso',NULL,NULL,NULL,0,'VIP lounge at the Splendid Hôtel, Ouagadougou\'s central business hotel. Curated premium cigars for the development sector professionals and government officials in the Burkinabe capital.','Lounge VIP del Splendid Hôtel, el hotel de negocios del centro de Uagadugú. Puros premium seleccionados para los profesionales del sector del desarrollo y los altos cargos gubernamentales de la capital burkinesa.','VIP-Lounge im Splendid Hôtel, dem Business-Hotel im Zentrum Ouagadougous. Ausgewählte Premium-Zigarren für Fachleute des Entwicklungssektors und Regierungsvertreter in der burkinischen Hauptstadt.','Splendid Hôtel 的贵宾休息厅——瓦加杜古市中心的商务酒店。为布基纳法索首都的发展领域专业人士与政府官员精选高端雪茄。','صالة كبار الزوّار في فندق سبلينديد، فندق الأعمال في وسط واغادوغو. سيجار فاخر منتقى لمهنيّي قطاع التنمية والمسؤولين الحكوميين في العاصمة البوركينية.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2554,'mali','Hôtel Salam — Espace Cigares','Bamako — Hôtel Salam, Avenue de l\'OUA, Badalabougou','Hotel Cigar Space','+223 20 21 17 60','€€€','Espace cigares de l\'Hôtel Salam, premier hôtel d\'affaires de Bamako, au bord du fleuve Niger. Cigares premium, terrasse sur le fleuve, clientèle des secteurs minier et du développement.','sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=H%C3%B4tel%20Salam%2C%20Bamako%20%E2%80%94%20H%C3%B4tel%20Salam%2C%20Mali',NULL,NULL,NULL,0,'Cigar space at the Hôtel Salam, Bamako\'s premier business hotel on the Niger River. Premium cigars, river terrace, mining and development sector clientele.','Espacio de puros del Hôtel Salam, principal hotel de negocios de Bamako, a orillas del río Níger. Puros premium, terraza sobre el río y clientela de los sectores minero y del desarrollo.','Zigarrenbereich im Hôtel Salam, Bamakos führendem Business-Hotel am Niger. Premium-Zigarren, Flussterrasse, Publikum aus Bergbau- und Entwicklungssektor.','Hôtel Salam 的雪茄区——巴马科首屈一指的商务酒店，濒临尼日尔河。高端雪茄、临河露台，客群来自矿业与发展领域。','ركن السيجار في فندق السلام، أبرز فنادق الأعمال في باماكو على ضفاف نهر النيجر. سيجار فاخر وتراس على النهر، وروّاد من قطاعَي التعدين والتنمية.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2555,'mali','Azalaï Grand Hôtel — Fumoir','Bamako — Azalaï Grand Hôtel, Square Lumumba','Hotel Cigar Lounge','+223 20 22 21 22','€€€','Lounge cigares de l\'Azalaï Grand Hôtel, repère historique du centre de Bamako. Sélection premium choisie dans le fleuron malien de la chaîne hôtelière de luxe ouest-africaine.','sans source externe',1,'2026-03-22 18:57:48','2026-09-04 08:45:19',NULL,'https://www.google.com/maps/search/?api=1&query=Azala%C3%AF%20Grand%20H%C3%B4tel%2C%20Bamako%20%E2%80%94%20Azala%C3%AF%20Grand%20H%C3%B4tel%2C%20Mali',NULL,NULL,NULL,0,'Cigar lounge at the Azalaï Grand Hôtel, Bamako\'s historic city-center landmark. Curated premium selection in the West African luxury hotel chain\'s flagship Malian property.','Cigar lounge del Azalaï Grand Hôtel, referencia histórica del centro de Bamako. Selección premium en el buque insignia maliense de la cadena hotelera de lujo de África Occidental.','Zigarrenlounge im Azalaï Grand Hôtel, historisches Wahrzeichen im Zentrum Bamakos. Ausgewählte Premium-Auswahl im malischen Flaggschiff der westafrikanischen Luxushotelkette.','Azalaï Grand Hôtel 的雪茄厅——巴马科市中心的历史地标。西非豪华酒店集团马里旗舰店内的高端精选。','صالة السيجار في فندق أزالاي الكبير، المعلم التاريخي في وسط باماكو. تشكيلة فاخرة منتقاة في الفندق المالي الرئيسي لسلسلة الفنادق الفاخرة في غرب أفريقيا.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2557,'cambodia','Bertie Phnom Penh','Phnom Penh — House 16, Street 13, Village 9, Sangkat Wat Phnom, Khan Daun Penh','Cave & Lounge','+855 10 567 825',NULL,'Salon de cigares du quartier de Wat Phnom, face à la poste centrale. Humidor climatisé, salon principal, salon privé et mezzanine ; carte de vins et spiritueux composée pour les accords.','bertie-pnh.com',1,'2026-09-04 11:33:20','2026-09-04 17:11:50','Lun–Sam 12h–0h · Dim 14h–0h',NULL,'https://www.bertie-pnh.com/',NULL,NULL,0,'Cigar lounge in the Wat Phnom district, opposite the central post office. Climate-controlled walk-in humidor, main lounge, private room and mezzanine; wine and spirits list put together for pairings.','Salón de puros en el barrio de Wat Phnom, frente a la oficina central de correos. Humidor climatizado, salón principal, sala privada y entreplanta; carta de vinos y destilados compuesta para los maridajes.','Zigarrenlounge im Viertel Wat Phnom, gegenüber der Hauptpost. Klimatisierter begehbarer Humidor, Hauptlounge, Separee und Zwischengeschoss; Wein- und Spirituosenkarte für Pairings zusammengestellt.','位于洼弄区的雪茄吧，与中央邮局相对。设有恒温恒湿步入式雪茄柜、主厅、私人包厢及夹层；酒单为搭配雪茄而设。','صالة سيجار في حي وات فنوم، مقابل مكتب البريد المركزي. مستودع ترطيب مكيّف، وصالة رئيسية، وغرفة خاصة، وطابق معلّق؛ وقائمة نبيذ ومشروبات روحية أُعدّت للمزاوجة.',NULL,NULL,NULL);
INSERT INTO `lounges` (`id`, `country_id`, `name`, `city`, `type`, `phone`, `price`, `description`, `source`, `is_verified`, `created_at`, `updated_at`, `hours`, `maps_url`, `website`, `instagram`, `rating`, `rating_count`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `lat`, `lon`, `contribution_id`) VALUES (2558,'malaysia','Cohiba Atmosphere — Kota Damansara','Petaling Jaya — 20 Jalan Teknologi 3/4, Kota Damansara','Cohiba Atmosphere Officiel',NULL,NULL,'Salon Cohiba Atmosphere de la région de Kuala Lumpur, à Kota Damansara, tenu par l\'exploitant de La Casa del Habano de Malaisie.','lcdh.com.my',1,'2026-09-04 22:58:09','2026-09-04 22:58:09',NULL,NULL,'https://lcdh.com.my/',NULL,NULL,0,'Cohiba Atmosphere lounge in the Kuala Lumpur area, at Kota Damansara, run by the operator of La Casa del Habano Malaysia.','Salón Cohiba Atmosphere del área de Kuala Lumpur, en Kota Damansara, gestionado por el operador de La Casa del Habano de Malasia.','Cohiba-Atmosphere-Lounge im Großraum Kuala Lumpur, in Kota Damansara, betrieben vom Betreiber von La Casa del Habano Malaysia.','位于吉隆坡地区哥打白沙罗的 Cohiba Atmosphere 雪茄吧，由马来西亚 La Casa del Habano 的经营者管理。','صالة كوهيبا أتموسفير في منطقة كوالالمبور، بكوتا دامانسارا، يديرها مشغّل لا كاسا ديل هابانو في ماليزيا.',NULL,NULL,NULL);
